/* ── script #19 ── */
/* ── MOBILE VIEWPORT FIX ──
   100vh on mobile browsers includes the area behind the address bar,
   which is taller than what's actually visible. That pushed the video
   feed's action buttons (like/comment/share/save) off-screen on real
   phones. This keeps a --vh custom property in sync with the true
   visible height, used as a fallback for browsers without 100dvh. */
(function () {
  function setVh() {
    var vh = (window.visualViewport ? window.visualViewport.height : window.innerHeight) * 0.01;
    document.documentElement.style.setProperty('--vh', vh + 'px');
  }
  setVh();
  window.addEventListener('resize', setVh);
  window.addEventListener('orientationchange', setVh);
  if (window.visualViewport) {
    window.visualViewport.addEventListener('resize', setVh);
  }
})();

/* ── script #20 ── */
// Mirror the sleep-timer badge into the Sleep button of the Now Playing row.
(function () {
  function init() {
    const src = document.getElementById('sleepTimerBadge'), dst = document.getElementById('npSleepTabVal');
    if (!src || !dst) return;
    const sync = () => {
      const on = src.classList.contains('show');
      dst.textContent = on ? src.textContent.replace(/^[\s·]+/, '').replace(/end of track/i, 'END').toUpperCase() : '';
      dst.classList.toggle('show', on);
    };
    new MutationObserver(sync).observe(src, { attributes: true, childList: true, characterData: true, subtree: true });
    sync();
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
})();

/* ── script #21 ── */
// Now Playing action row: show a soft fade on whichever edge has more buttons to scroll to.
(function () {
  function update() {
    const row = document.getElementById('npActions'), wrap = document.getElementById('npActionsWrap');
    if (!row || !wrap) return;
    wrap.classList.toggle('can-left',  row.scrollLeft > 4);
    wrap.classList.toggle('can-right', row.scrollLeft + row.clientWidth < row.scrollWidth - 4);
  }
  function init() {
    const row = document.getElementById('npActions');
    if (!row) return;
    row.addEventListener('scroll', update, { passive: true });
    window.addEventListener('resize', update);
    update();
    setTimeout(update, 400);
    const scr = document.getElementById('nowPlayingScreen');
    if (scr && window.MutationObserver) {
      new MutationObserver(() => { row.scrollLeft = 0; setTimeout(update, 50); })
        .observe(scr, { attributes: true, attributeFilter: ['class'] });
    }
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
})();

