// ── 24-hour expiry: messages + notifications older than 24h are hidden here and purged in Supabase (see SQL block near "MESSAGES — Supabase Realtime") ──
const _EXPIRY_MS = 24 * 60 * 60 * 1000;
const _expiryCutoff = () => new Date(Date.now() - _EXPIRY_MS).toISOString();
// The app itself deletes expired data from Supabase (needs the DELETE policies in the SQL block near "MESSAGES — Supabase Realtime").
// Runs after sign-in and then every 30 min while the app is open: expired messages (+ their chat photos/videos/voice notes),
// expired notifications, and any of the user's own old chat uploads.
let _lastPurge = 0, _purgeBusy = false;
async function _purgeExpiredData(force) {
  if (!sb || !_demoUser || _purgeBusy || (!force && Date.now() - _lastPurge < 25 * 60 * 1000)) return;
  _purgeBusy = true; _lastPurge = Date.now();
  try {
    const uid = _demoUser.id, cutoff = _expiryCutoff(), B = 'chat-media';
    const pathOf = u => { const m = String(u || '').match(/\/chat-media\/([^?#]+)/); return m ? decodeURIComponent(m[1]) : null; };
    // 1) expired messages I'm part of, plus their media files
    for (let round = 0; round < 10; round++) {
      const r = await sb.from('yaps_messages').select('id,media_url').or('sender_id.eq.' + uid + ',receiver_id.eq.' + uid).lt('created_at', cutoff).limit(200);
      if (r.error || !r.data || !r.data.length) break;
      const paths = r.data.map(x => pathOf(x.media_url)).filter(Boolean);
      if (paths.length) { try { await sb.storage.from(B).remove(paths); } catch (e) {} }
      const d = await sb.from('yaps_messages').delete().in('id', r.data.map(x => x.id));
      if (d.error || r.data.length < 200) break;
    }
    // 2) expired notifications (mine + broadcasts)
    await sb.from('yaps_notifications').delete().or('user_id.eq.' + uid + ',user_id.is.null').lt('created_at', cutoff);
    // 3) any old uploads left in my own chat-media folder
    const l = await sb.storage.from(B).list(uid, { limit: 1000, sortBy: { column: 'created_at', order: 'asc' } });
    if (!l.error && l.data) {
      const old = l.data.filter(f => f.name && f.created_at && Date.parse(f.created_at) < Date.now() - _EXPIRY_MS).map(f => uid + '/' + f.name);
      for (let i = 0; i < old.length; i += 100) await sb.storage.from(B).remove(old.slice(i, i + 100));
    }
  } catch (e) { console.warn('[YAPS] expiry cleanup skipped', e && e.message); }
  _purgeBusy = false;
}
setInterval(() => { try { _purgeExpiredData(); } catch (e) {} }, 30 * 60 * 1000);

// Notifications without the Python API: the yaps_notifications table in Supabase (run supabase-notifications.sql once).
async function _notifInsertDirect(rows) {
  if (!sb || !_demoUser || !rows || !rows.length) return;
  const base = { actor_id: _demoUser.id, actor_name: _demoUser.name || 'Someone', actor_avatar: _demoUser.avatar || null };
  const payload = rows.map(r => Object.assign({}, base, r));
  for (let i = 0; i < payload.length; i += 200) {
    const r = await sb.from('yaps_notifications').insert(payload.slice(i, i + 200));
    if (r.error) throw r.error;
  }
}
async function _directNotifApi(path, method, body) {
  if (!sb || !_demoUser) throw new Error('Sign in first');
  const uid = _demoUser.id;
  if (path.indexOf('/api/notifications/read') === 0 && method === 'POST') {
    const ids = (body && body.ids) || [];
    if (ids.length) { const r = await sb.from('yaps_notifications').update({ read: true }).in('id', ids).eq('user_id', uid); if (r.error) throw r.error; }
    return { ok: true };
  }
  if (method === 'GET') {
    const m = path.match(/limit=(\d+)/);
    const r = await sb.from('yaps_notifications').select('*').or('user_id.eq.' + uid + ',user_id.is.null').gte('created_at', _expiryCutoff())
      .order('created_at', { ascending: false }).limit(m ? +m[1] : 50);
    if (r.error) throw r.error;
    return r.data || [];
  }
  if (method === 'POST' && body && body.to_user_id) {
    await _notifInsertDirect([{ user_id: body.to_user_id, type: body.type, body: body.body || '', track_title: body.track_title || '', track_img: body.track_img || '' }]);
    return { ok: true };
  }
  return undefined;
}

// Messages without the Python API: read/write the yaps_messages table in Supabase (run supabase-messages.sql once).
async function _directApi(path, method, body) {
  if (path.indexOf('/api/notifications') === 0) return _directNotifApi(path, method, body);
  if (path === '/api/me/profile' && method === 'PATCH') {
    if (!sb || !_demoUser) throw new Error('Sign in first');
    const uid0 = _demoUser.id, patch = {};
    ['full_name', 'username', 'bio', 'avatar_url', 'cover_url'].forEach(k => { if (body && body[k] !== undefined) patch[k] = body[k]; });
    const taken = e => e && (e.code === '23505' || /duplicate key|unique/i.test(e.message || ''));
    let r = await sb.from('yaps_profiles').update(patch).eq('id', uid0).select('*').maybeSingle();
    if (r.error) { if (taken(r.error)) throw new Error('That username is already taken'); throw r.error; }
    if (!r.data) {   // no profile row yet: create it
      r = await sb.from('yaps_profiles').insert({ id: uid0, ...patch }).select('*').maybeSingle();
      if (r.error) { if (taken(r.error)) throw new Error('That username is already taken'); throw r.error; }
    }
    if (r.data) window._yapsProfile = r.data;
    return r.data;
  }
  if (/^\/api\/(tracks|videos|moderation)/.test(path)) return _directMedia(path, method, body);
  if (path.indexOf('/api/messages') !== 0) return undefined;
  if (!sb || !_demoUser) throw new Error('Sign in first');
  const uid = _demoUser.id;
  if (path === '/api/messages/inbox' && method === 'GET') {
    const r = await sb.from('yaps_messages').select('*').or('sender_id.eq.' + uid + ',receiver_id.eq.' + uid).gte('created_at', _expiryCutoff())
      .order('created_at', { ascending: false }).limit(400);
    if (r.error) throw r.error;
    return r.data || [];
  }
  const m = path.match(/^\/api\/messages\/([^?\/]+)(?:\?limit=(\d+))?$/);
  if (m && method === 'GET') {
    const r = await sb.from('yaps_messages').select('*').eq('conversation_id', _convId(uid, m[1])).gte('created_at', _expiryCutoff())
      .order('created_at', { ascending: true }).limit(+m[2] || 100);
    if (r.error) throw r.error;
    return r.data || [];
  }
  if (path === '/api/messages' && method === 'POST' && body && body.receiver_id) {
    let rname = (typeof _currentChatUser !== 'undefined' && _currentChatUser && _currentChatUser.id === body.receiver_id) ? _currentChatUser.name : null;
    if (!rname) {
      try { const pr = await sb.from('yaps_profiles').select('full_name,username').eq('id', body.receiver_id).maybeSingle(); rname = pr.data && (pr.data.full_name || pr.data.username); } catch (e) {}
    }
    const row = {
      conversation_id: _convId(uid, body.receiver_id), sender_id: uid, receiver_id: body.receiver_id,
      sender_name: _demoUser.name, receiver_name: rname || 'User', body: body.body || '',
      track_data: body.track_data || null, media_url: body.media_url || null,
      media_type: body.media_type || null, media_duration: body.media_duration || null
    };
    const r = await sb.from('yaps_messages').insert(row);
    if (r.error) throw r.error;
    return { ok: true };
  }
  return undefined;
}

// True once YAPS_API_URL points at a real deployed backend (not the placeholder).
const _apiConfigured = () => !YAPS_API_URL.includes('YOUR-SERVICE');

// Calls the backend with the signed-in user's Supabase token (public routes work signed-out).
async function api(path, { method = 'GET', body } = {}) {
  if (!_apiConfigured()) {
    const direct = await _directApi(path, method, body);
    if (direct !== undefined) return direct;
    throw new Error('Set YAPS_API_URL in index.html to your deployed API');
  }
  const headers = { 'Content-Type': 'application/json' };
  try {
    const { data } = await sb.auth.getSession();
    if (data && data.session) headers.Authorization = 'Bearer ' + data.session.access_token;
  } catch (e) {}
  const res = await fetch(YAPS_API_URL + path, { method, headers, body: body ? JSON.stringify(body) : undefined });
  if (!res.ok) {
    let msg = res.statusText;
    try { const j = await res.json(); msg = typeof j.detail === 'string' ? j.detail : JSON.stringify(j.detail || j); } catch (e) {}
    throw new Error(msg || ('HTTP ' + res.status));
  }
  return res.status === 204 ? null : res.json();
}


