async function _loadUploadedAudio() {
  // Show loading indicator
  const dot = document.getElementById('audioStatusDot');
  if (dot) { dot.style.display = 'block'; dot.textContent = 'Loading audio...'; }

  // ── URL resolver ──
  // If AUDIO_BASE_URL is set, return direct URL immediately (no fetch needed — R2/GitHub CDN).
  // Otherwise try fetching as blob URL so it works locally via `python -m http.server`.
  async function resolveAudioUrl(filename) {
    if (AUDIO_BASE_URL) {
      // Direct cloud/CDN URL — no fetch, just build the URL
      return AUDIO_BASE_URL.replace(/\/$/, '') + '/' + encodeURIComponent(filename);
    }
    // Local mode: try to fetch and create a blob URL
    // Try filename as-is first, then encoded (handles parens, spaces, etc.)
    const attempts = [filename, encodeURIComponent(filename)];
    for (const attempt of attempts) {
      try {
        const res = await fetch(attempt);
        if (res.ok) {
          const blob = await res.blob();
          return URL.createObjectURL(blob);
        }
      } catch { /* try next */ }
    }
    return null;
  }

  // ── 1. Wire existing tracks in the tracks[] array ──
  const wirePromises = _audioFileMap.map(async (map) => {
    const idx = tracks.findIndex(map.match);
    if (idx >= 0 && !tracks[idx].audioUrl && !tracks[idx].blobUrl) {
      const url = await resolveAudioUrl(map.file);
      if (url) {
        // Use audioUrl for CDN links, blobUrl for local blobs
        if (AUDIO_BASE_URL) tracks[idx].audioUrl = url;
        else tracks[idx].blobUrl = url;
      }
    }
  });
  await Promise.all(wirePromises);

  // ── 2. Append extra tracks not already in the list ──
  let coverIdx = 0;
  const appendPromises = _extraUploadedFiles.map(async (extra) => {
    const exists = tracks.some(t => t.title.toLowerCase() === extra.title.toLowerCase());
    if (!exists) {
      const url = await resolveAudioUrl(extra.file);
      if (url) {
        const trackObj = {
          id: 100 + tracks.length + Math.floor(Math.random()*1000),
          title: extra.title,
          artist: extra.artist,
          img: _coverPool[coverIdx++ % _coverPool.length],
          genre: extra.genre,
          plays: Math.floor(Math.random()*500+100)+'K',
          likes: Math.floor(Math.random()*15+2)+'K',
          duration: '3:30',
          tags: extra.tags,
        };
        if (AUDIO_BASE_URL) trackObj.audioUrl = url;
        else trackObj.blobUrl = url;
        tracks.push(trackObj);
      }
    }
  });
  await Promise.all(appendPromises);

  // ── 3. Re-render current page now that audio is wired ──
  if (typeof renderHome === 'function' && currentPage === 'home') renderHome();
  if (typeof renderCharts === 'function' && currentPage === 'charts') renderCharts();
  if (typeof renderSearch === 'function' && currentPage === 'search') renderSearch();

  // ── 4. Update status indicator ──
  const withAudio = tracks.filter(t => t.audioUrl || t.blobUrl || t.audioSrc).length;
  if (dot) {
    if (withAudio > 0) {
      dot.textContent = `${withAudio} tracks ready`;
      dot.style.color = 'var(--accent)';
      setTimeout(() => { dot.style.display = 'none'; }, 4000);
    } else {
      // No audio found — give a helpful hint
      dot.textContent = 'Put MP3s in same folder as index.html';
      dot.style.color = '#ff9800';
      setTimeout(() => { dot.style.display = 'none'; }, 6000);
    }
  }
  console.log(`YAPS: ${withAudio} tracks with real audio ready`);
}

// Run after page load
window.addEventListener('load', _loadUploadedAudio);


