// Pull 4 real track/artist images that match a playlist's theme (genre, tag, or region),
// instead of generic Unsplash stock photos. Falls back to filling gaps from the wider
// catalog if a theme doesn't have 4 unique artist images on its own.
function _playlistImgs(matcher, count) {
  count = count || 4;
  const seen = new Set();
  const out = [];
  tracks.forEach(t => {
    if (out.length >= count) return;
    if (!t.img || seen.has(t.img)) return;
    if (matcher(t)) { out.push(t.img); seen.add(t.img); }
  });
  if (out.length < count) {
    tracks.forEach(t => {
      if (out.length >= count) return;
      if (!t.img || seen.has(t.img)) return;
      out.push(t.img); seen.add(t.img);
    });
  }
  return out;
}
// Each entry keeps the original homepage fields (title, tracks, imgs) and adds:
//   id    — used to open it in the existing playlist detail/player (see _catalogPlaylist)
//   cats  — filter chips on the Playlists "See all" page
//   desc  — short description
//   match — the SAME rule that picks the artwork also picks the playable tracks
function _mkPlaylist(id, title, tracksCount, cats, desc, match) {
  return { id, title, tracks: tracksCount, cats, desc, match, imgs: _playlistImgs(match) };
}
