// ── PER-ACCOUNT LIBRARY STORAGE ──
// While browsing as a guest, activity (likes, history, playlists, follows,
// reposts, comments, tips, last-playback) is saved under plain keys. Once
// someone signs in or creates an account, the same activity is saved under
// keys scoped to their user id instead, so different accounts on the same
// device never mix libraries. The first time a given account is used on this
// device, whatever was collected as a guest is copied over so nothing is
// lost when they sign up — it becomes that account's data going forward.
const _LIBRARY_BASE_KEYS = ['yaps_liked', 'yaps_history', 'yaps_playlists', 'yaps_reposted', 'yaps_stream_comments', 'yaps_tips_given', 'yaps_followed_artists', 'yaps_last_playback', 'yaps_libk'];
function _libKey(base) {
  return _demoUser ? `${base}_u_${_demoUser.id}` : base;
}
function _migrateGuestLibraryToAccount(userId) {
  try {
    const marker = 'yaps_migrated_u_' + userId;
    if (localStorage.getItem(marker)) return; // this account already has its own library on this device
    let migratedAny = false;
    _LIBRARY_BASE_KEYS.forEach(base => {
      const guestVal = localStorage.getItem(base);
      const acctKey = base + '_u_' + userId;
      if (guestVal !== null && localStorage.getItem(acctKey) === null) {
        localStorage.setItem(acctKey, guestVal);
        migratedAny = true;
      }
    });
    localStorage.setItem(marker, '1');
    if (migratedAny && typeof showToast === 'function') {
      showToast('Your likes, playlists & history are now saved to your account');
    }
  } catch (e) {}
}

// ── PERSIST: save likes, history, playlists to localStorage (lightweight) ──
function _persistSave() {
  try {
    localStorage.setItem(_libKey('yaps_liked'), JSON.stringify([..._likedTracks]));
    localStorage.setItem(_libKey('yaps_history'), JSON.stringify(_history.slice(0, 50)));
    localStorage.setItem(_libKey('yaps_playlists'), JSON.stringify(_userPlaylists));
    localStorage.setItem(_libKey('yaps_reposted'), JSON.stringify([..._repostedTracks]));
    localStorage.setItem(_libKey('yaps_stream_comments'), JSON.stringify(_stComments));
    localStorage.setItem(_libKey('yaps_tips_given'), JSON.stringify(_tipsGiven));
    localStorage.setItem(_libKey('yaps_followed_artists'), JSON.stringify([..._followedArtists]));
    if (_lastPlayback) localStorage.setItem(_libKey('yaps_last_playback'), JSON.stringify(_lastPlayback));
  } catch(e) {}
  try { _libStoreK(_libKeysFromState()); } catch(e) {}      // same library as stable song keys (survives catalogue changes / other devices)
  if (typeof _libPushSoon === 'function') _libPushSoon();   // cloud copy (signed-in only)
}

// Reloads the library for whichever identity (guest or the signed-in account)
// is currently active. Resets fields not found in storage instead of leaving
// stale in-memory state behind, so switching accounts on the same device
// never bleeds one person's likes/playlists into another's.
function _persistLoad() {
  try {
    const liked = localStorage.getItem(_libKey('yaps_liked'));
    _likedTracks = liked ? new Set(JSON.parse(liked)) : new Set();
    const hist = localStorage.getItem(_libKey('yaps_history'));
    _history = hist ? JSON.parse(hist) : [];
    const pl = localStorage.getItem(_libKey('yaps_playlists'));
    _userPlaylists = pl ? JSON.parse(pl) : [];
    const rep = localStorage.getItem(_libKey('yaps_reposted'));
    _repostedTracks = rep ? new Set(JSON.parse(rep)) : new Set();
    const sc = localStorage.getItem(_libKey('yaps_stream_comments'));
    _stComments = sc ? JSON.parse(sc) : {};
    const tg = localStorage.getItem(_libKey('yaps_tips_given'));
    _tipsGiven = tg ? JSON.parse(tg) : {};
    const fa = localStorage.getItem(_libKey('yaps_followed_artists'));
    _followedArtists = fa ? new Set(JSON.parse(fa)) : new Set();
    const lp = localStorage.getItem(_libKey('yaps_last_playback'));
    _lastPlayback = lp ? JSON.parse(lp) : null;
  } catch(e) {}
  try { const K = _libLoadK(); if (K) _libResolve(K); } catch(e) {}   // positions rebuilt from song keys
}
_persistLoad();

// Re-renders whatever's currently on screen that reads from the library
// (liked/downloads tabs, playlists, followed-artist state) after the active
// identity changes — e.g. right after signup migrates guest data in.
function _refreshLibraryUI() {
  try {
    if (typeof renderPersonalizedHome === 'function') renderPersonalizedHome();
    const libPage = document.getElementById('page-library');
    if (libPage && libPage.classList.contains('active') && typeof renderLibrary === 'function') renderLibrary();
  } catch (e) {}
}

// ── NAVIGATION ──
// Horizontally-scrolling rows (track/artist/playlist carousels, filter chip
// strips, etc.) can end up scrolled away from their start — either because
// the browser/WebView restores a previous scroll position when the page is
// reloaded or restored from cache, or because a row was mid-swipe when the
// page was left. Either way the row then opens already cut off instead of
// showing its first card. Force every such row back to scrollLeft 0 whenever
// a page is (re)shown, so it always starts at the beginning.
function _resetHorizontalScrollRows(root) {
  (root || document).querySelectorAll(
    '.scroll-row, .stream-filters, .chart-country-chips, .genre-chip-row, .yv2-cats, .yv2-trend-row, .library-tabs'
  ).forEach(el => { el.scrollLeft = 0; });
}
window.addEventListener('pageshow', () => _resetHorizontalScrollRows());
document.addEventListener('DOMContentLoaded', () => _resetHorizontalScrollRows());

// ── SHARE SONGS WITH DJ STUDIO (studio.html) ──
// Writes the live song list (built-in + shared/remote) to localStorage so studio.html
// always sees the same songs as this page. Device uploads are read by the studio
// straight from IndexedDB ('YapsMusicDB'), so they are not copied here.
function _studioSync() {
  try {
    if (typeof tracks === 'undefined') return;
    const list = [];
    tracks.forEach(t => {
      const audio = t.audioUrl || t.audioSrc;
      if (!audio || t._saved || /^(blob:|data:)/.test(audio)) return;
      const img = t.img && !/^blob:/.test(t.img) ? t.img : '';
      list.push({ id: String(t.id), title: t.title, artist: t.artist, cover: img, audio: audio,
        genre: t.genre || '', duration: t.duration || '', tags: t.tags || [], up: !!t._remote });
    });
    const _j = JSON.stringify(list);
    if (window.__studioLastSync !== _j) { window.__studioLastSync = _j; localStorage.setItem('yaps_shared_catalogue', _j); }
    if (typeof YAPS_API_URL === 'string' && !YAPS_API_URL.includes('YOUR-SERVICE'))
      localStorage.setItem('yaps_shared_api', YAPS_API_URL);
  } catch (e) { console.warn('Studio sync skipped:', e && e.message); }
}
function openStudio(trackId, deck) {
  _studioSync();
  if (window._studioOpen) window._studioOpen(trackId, deck);
}
// ── DJ STUDIO: pick which deck a song loads into (same bottom-sheet look as the song menu) ──
function _djMakeDeckSheet() {
  let sh = document.getElementById('djDeckSheet');
  if (sh) return sh;
  sh = document.createElement('div');
  sh.id = 'djDeckSheet'; sh.className = 'nrp-sheet';
  sh.innerHTML = `<div class="nrp-sheet-back" data-close="1"></div>
    <div class="nrp-sheet-panel" role="dialog" aria-modal="true" aria-labelledby="djDeckTitle">
      <div class="nrp-sheet-head"><img id="djDeckImg" alt=""><div class="nrp-sheet-t"><b id="djDeckTitle"></b><span id="djDeckArtist"></span></div></div>
      <button type="button" class="nrp-act" data-deck="A"><i class="fas fa-headphones" aria-hidden="true"></i>Load to Deck A</button>
      <button type="button" class="nrp-act" data-deck="B"><i class="fas fa-headphones" aria-hidden="true"></i>Load to Deck B</button>
    </div>`;
  document.body.appendChild(sh);
  sh.addEventListener('click', function (e) {
    if (e.target.closest('[data-close]')) { sh.classList.remove('open'); return; }
    const b = e.target.closest('[data-deck]'); if (!b) return;
    const id = sh.dataset.id; sh.classList.remove('open');
    openStudio(id, b.dataset.deck);
  });
  document.addEventListener('keydown', function (e) { if (e.key === 'Escape') sh.classList.remove('open'); });
  return sh;
}
function openDeckPicker(i) {
  const t = (typeof tracks !== 'undefined') ? tracks[i] : null;
  if (!t) { openStudio(); return; }
  const sh = _djMakeDeckSheet();
  sh.dataset.id = String(t.id);
  document.getElementById('djDeckImg').src = t.img || '';
  document.getElementById('djDeckTitle').textContent = t.title;
  document.getElementById('djDeckArtist').textContent = t.artist;
  sh.classList.add('open');
  const first = sh.querySelector('[data-deck]'); if (first) first.focus();
}
window.addEventListener('pagehide', _studioSync);
document.addEventListener('visibilitychange', () => { if (document.hidden) _studioSync(); });
