function toggleShuffle() {
  shuffleOn = !shuffleOn;
  if (shuffleOn) buildShuffleOrder();
  const btn = document.getElementById('shuffleBtn');
  if (btn) btn.classList.toggle('active', shuffleOn);
  const npBtn = document.getElementById('npShuffleBtn');
  if (npBtn) npBtn.classList.toggle('active', shuffleOn);
  showToast(shuffleOn ? 'Shuffle on' : 'Shuffle off');
  _persistPlayerPrefs();
  if (queueOpen) renderQueue();
}

// ── PLAYBACK SPEED ──
const PLAYBACK_SPEEDS = [0.5, 0.75, 1, 1.25, 1.5, 2];
let _playbackSpeed = 1;

function cyclePlaybackSpeed() {
  const i = PLAYBACK_SPEEDS.indexOf(_playbackSpeed);
  _playbackSpeed = PLAYBACK_SPEEDS[(i + 1) % PLAYBACK_SPEEDS.length];
  audioEngine.playbackRate = _playbackSpeed;
  _syncSpeedLabel();
  showToast('Speed: ' + _playbackSpeed + 'x');
}

function _syncSpeedLabel() {
  const lbl = document.getElementById('npSpeedLabel');
  if (lbl) lbl.textContent = _playbackSpeed + 'x';
  const btn = document.getElementById('npSpeedBtn');
  if (btn) btn.classList.toggle('active', _playbackSpeed !== 1);
  const tv = document.getElementById('npSpeedTabVal');
  if (tv) tv.textContent = _playbackSpeed + 'X';
}

function toggleRepeat() {
  repeatMode = (repeatMode + 1) % 3;
  audioEngine.loop = (repeatMode === 2 && !(tracks[currentTrack] && tracks[currentTrack].startAt));
  _persistPlayerPrefs();
  if (queueOpen) setTimeout(renderQueue, 0);
  const btn = document.getElementById('repeatBtn');
  if (!btn) return;
  btn.classList.toggle('active', repeatMode > 0);
  btn.classList.remove('fa-redo', 'fa-redo-alt');
  btn.classList.add(repeatMode === 2 ? 'fa-redo-alt' : 'fa-redo');

  const npBtn = document.getElementById('npRepeatBtn');
  if (npBtn) {
    npBtn.classList.toggle('active', repeatMode > 0);
    npBtn.classList.remove('fa-redo', 'fa-redo-alt');
    npBtn.classList.add(repeatMode === 2 ? 'fa-redo-alt' : 'fa-redo');
  }

  if (repeatMode === 0) showToast('Repeat off');
  else if (repeatMode === 1) showToast('Repeat all');
  else { btn.setAttribute('data-one','1'); showToast('Repeat one'); }
}

function toggleLikeBtm(el) { el.style.color = el.style.color === 'var(--accent)' ? 'var(--dim)' : 'var(--accent)'; }
function toggleFeedLike(el) {
  el.classList.toggle('liked');
  const icon = el.querySelector('i');
  const liked = el.classList.contains('liked');
  if (icon) icon.style.color = liked ? 'var(--accent)' : '';
  // update the count displayed
  const text = el.childNodes[el.childNodes.length - 1];
  if (text && text.nodeType === 3) {
    const current = parseInt(text.textContent.trim().replace(/[^0-9]/g,'')) || 0;
    text.textContent = ' ' + (liked ? current + 1 : Math.max(0, current - 1));
  }
  showToast(liked ? 'Liked!' : 'Removed like');
}
function toggleActive(el) { el.classList.toggle('active'); }

// ── KEYBOARD SHORTCUTS ──
document.addEventListener('keydown', e => {
  const tag = document.activeElement.tagName;
  if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;
  if (e.key === ' ') { e.preventDefault(); togglePlay(); }
  else if (e.key === 'ArrowRight') { e.preventDefault(); nextTrack(); }
  else if (e.key === 'ArrowLeft') { e.preventDefault(); prevTrack(); }
  else if (e.key === 's' || e.key === 'S') { toggleShuffle(); }
  else if (e.key === 'r' || e.key === 'R') { toggleRepeat(); }
});

// ── QUEUE ──
let _queuedTracks = []; // extra tracks added by user

function toggleQueue() {
  queueOpen = !queueOpen;
  document.getElementById('queuePanel').classList.toggle('open', queueOpen);
  renderQueue();
}

// Tapping a queued song plays it and takes it off the queue (so it doesn't play twice)
function playQueued(idx) {
  const i = _queuedTracks.indexOf(idx);
  if (i >= 0) _queuedTracks.splice(i, 1);
  playTrack(idx);
}
function addToQueue(idx) {
  _queuedTracks.push(idx);
  showToast('Added to queue!');
  if (queueOpen) renderQueue();
}
function playNextInQueue(idx) {
  _queuedTracks.unshift(idx);
  showToast('Will play next');
  if (queueOpen) renderQueue();
}
function removeFromQueue(pos) {
  _queuedTracks.splice(pos, 1);
  renderQueue();
}
function clearQueue() {
  _queuedTracks.length = 0;
  renderQueue();
  showToast('Queue cleared');
}

function renderQueue() {
  const now = tracks[currentTrack];
  if (!now) return;
  const E = s => _escHtml(s == null ? '' : s);
  const chips = (shuffleOn ? '<span class="queue-chip"><i class="fas fa-random"></i> Shuffle</span>' : '')
    + (repeatMode === 1 ? '<span class="queue-chip"><i class="fas fa-redo"></i> Repeat all</span>' : '')
    + (repeatMode === 2 ? '<span class="queue-chip"><i class="fas fa-redo-alt"></i> Repeat one</span>' : '')
    + (_activeQueueLabel ? `<span class="queue-chip">From ${E(_activeQueueLabel)}</span>` : '');
  document.getElementById('queueNowPlaying').innerHTML = `
    <div class="qi-art"><img loading="lazy" decoding="async" src="${E(now.img)}" alt="" style="width:100%;height:100%;object-fit:cover;border-radius:6px;"></div>
    <div class="qi-info"><div class="qi-title">${E(now.title)}</div><div class="qi-artist">${E(now.artist)}</div>${chips ? `<div class="queue-chips">${chips}</div>` : ''}</div>
    <div class="qi-duration">${E(now.duration)}</div>
  `;
  const row = (t, click, extra) => `
    <div class="queue-item" onclick="${click}">
      <div class="qi-art"><img src="${E(t.img)}" alt="" loading="lazy" style="width:100%;height:100%;object-fit:cover;border-radius:6px;"></div>
      <div class="qi-info"><div class="qi-title">${E(t.title)}</div><div class="qi-artist">${E(t.artist)}</div></div>
      <div class="qi-duration">${E(t.duration)}</div>${extra || ''}
    </div>`;
  const queued = [];
  _queuedTracks.forEach((idx, pos) => { if (tracks[idx]) queued.push({ idx, pos }); });
  const next = _upcoming(25);
  let html = '';
  if (queued.length) {
    html += `<div class="queue-section-title queue-sec-row"><span>Next in queue · ${queued.length}</span><button type="button" class="queue-clear" onclick="event.stopPropagation();clearQueue()">Clear</button></div>`;
    html += queued.map(q => row(tracks[q.idx], `playQueued(${q.idx})`,
      `<button type="button" class="queue-rm" aria-label="Remove from queue" onclick="event.stopPropagation();removeFromQueue(${q.pos})"><i class="fas fa-times"></i></button>`)).join('');
  }
  if (next.length) {
    html += `<div class="queue-section-title">${shuffleOn ? 'Next · shuffled' : (_activeQueueLabel ? 'Next from ' + E(_activeQueueLabel) : 'Next up')}</div>`;
    html += next.map(i => row(tracks[i], `playTrack(${i})`)).join('');
  }
  if (!queued.length && !next.length) {
    html = `<div class="queue-empty">${repeatMode === 2 ? 'Repeating this song.' : 'Nothing coming up. Add songs with “Add to queue”, or turn on Repeat to keep going.'}</div>`;
  }
  document.getElementById('queueList').innerHTML = html;
}

// ── MODALS ──
// Sign in / Create account is its own page (auth.html). goAuth('signin' | 'signup', 'listener' | 'artist' | 'dj')
function goAuth(side, type) {
  var q = [];
  if (side === 'signup') q.push('mode=signup');
  if (type) q.push('type=' + encodeURIComponent(type));
  var here = location.pathname.split('/').pop();
  if (here && here !== 'index.html' && /^[\w\-.]+\.html$/.test(here)) q.push('next=' + encodeURIComponent(here));
  location.href = 'auth.html' + (q.length ? '?' + q.join('&') : '');
}
function openModal(name) {
  if (name === 'auth') { goAuth('signin'); return; }
  closeAllDropdowns();
  document.getElementById('modal' + name.charAt(0).toUpperCase() + name.slice(1)).classList.add('open');
  if (name === 'language') _renderLangOptions();
}
function closeModal(name) {
  var _m = document.getElementById('modal' + name.charAt(0).toUpperCase() + name.slice(1));
  if (_m) _m.classList.remove('open');
}

