function _currentLang() {
  return localStorage.getItem('yaps_language') || 'en';
}

function applyLanguage(lang) {
  if (!_i18n[lang]) lang = 'en';
  localStorage.setItem('yaps_language', lang);
  document.documentElement.lang = lang;
  const dict = _i18n[lang];
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const key = el.getAttribute('data-i18n');
    if (dict[key]) el.textContent = dict[key];
  });
  document.querySelectorAll('[data-i18n-ph]').forEach(el => {
    const key = el.getAttribute('data-i18n-ph');
    if (dict[key]) el.placeholder = dict[key];
  });
  _renderLangOptions();
  if (typeof _syncPremiumUI === 'function') _syncPremiumUI();
}

function _T(key, fallback) { const d = _i18n[_currentLang()]; return (d && d[key]) || fallback; }

function setAppLanguage(lang) {
  applyLanguage(lang);
  const label = _langMeta[lang] ? _langMeta[lang].native : lang;
  if (typeof showToast === 'function') showToast('Language set to ' + label);
}

function _renderLangOptions() {
  const list = document.getElementById('langOptionList');
  if (!list) return;
  const current = _currentLang();
  list.innerHTML = Object.keys(_langMeta).map(code => {
    const m = _langMeta[code];
    const active = code === current ? ' active' : '';
    return `
      <div class="lang-option${active}" onclick="setAppLanguage('${code}')">
        <div>
          <div class="lang-option-native">${m.native}</div>
          <div class="lang-option-english">${m.english}</div>
        </div>
        <i class="fas fa-check lang-option-check"></i>
      </div>
    `;
  }).join('');
}

// Apply the saved language as soon as the DOM is ready, so returning users
// see their chosen language immediately rather than a flash of English.
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => applyLanguage(_currentLang()));
} else {
  applyLanguage(_currentLang());
}

// ── RATE APP ──
let _rateStarsVal = 0;
function openRateAppModal() {
  _rateStarsVal = 0;
  _paintRateStars();
  const c = document.getElementById('rateComment');
  if (c) c.value = '';
  openModal('rate');
}
function _setRateStars(n) {
  _rateStarsVal = n;
  _paintRateStars();
}
function _paintRateStars() {
  document.querySelectorAll('#rateStars i').forEach(el => {
    const n = parseInt(el.dataset.star, 10);
    if (n <= _rateStarsVal) {
      el.classList.remove('far'); el.classList.add('fas');
      el.style.color = 'var(--accent)';
    } else {
      el.classList.remove('fas'); el.classList.add('far');
      el.style.color = 'var(--dim)';
    }
  });
}
function _submitAppRating() {
  if (_rateStarsVal < 1) { showToast('Tap a star to rate YAPS first'); return; }
  const comment = (document.getElementById('rateComment')?.value || '').trim();
  const entry = { stars: _rateStarsVal, comment, at: Date.now() };
  try {
    const existing = JSON.parse(localStorage.getItem('yaps_app_ratings') || '[]');
    existing.push(entry);
    localStorage.setItem('yaps_app_ratings', JSON.stringify(existing));
  } catch (e) {}
  closeModal('rate');
  showToast(_rateStarsVal >= 4 ? 'Thanks for the ' + _rateStarsVal + '★ rating!' : 'Thanks for your feedback, we\'re on it');
}

