// ── LEGAL (Privacy Policy / Terms of Service) ──
function openLegal(tab) {
  openModal('legal');
  const wanted = tab || 'privacypolicy';
  const tabEl = wanted === 'terms' ? document.getElementById('legalTabTerms') : document.getElementById('legalTabPrivacy');
  if (tabEl) switchModalTab(tabEl, wanted);
}

function openHelpCenter() {
  const input = document.getElementById('helpSearchInput');
  if (input) input.value = '';
  _renderHelpCenter('');
  openModal('help');
}

function _renderHelpCenter(query) {
  const results = document.getElementById('helpResults');
  if (!results) return;
  const q = (query || '').trim().toLowerCase();

  let html = '';
  let matchCount = 0;
  _helpData.forEach((cat, ci) => {
    const items = q
      ? cat.items.filter(it => it.q.toLowerCase().includes(q) || it.a.toLowerCase().includes(q))
      : cat.items;
    if (!items.length) return;
    matchCount += items.length;
    html += `<div class="help-cat"><div class="help-cat-title"><i class="fas ${cat.icon}"></i>${cat.cat}</div>`;
    items.forEach((it, ii) => {
      const id = `help-${ci}-${ii}`;
      html += `
        <div class="help-item" id="${id}">
          <div class="help-q" onclick="_toggleHelpItem('${id}')">
            <span>${it.q}</span>
            <i class="fas fa-chevron-down"></i>
          </div>
          <div class="help-a"><div class="help-a-inner">${it.a}</div></div>
        </div>`;
    });
    html += `</div>`;
  });

  if (!matchCount) {
    html = `<div class="help-empty"><i class="fas fa-magnifying-glass" style="display:block;font-size:20px;margin-bottom:8px;"></i>No results for "${query}"<br>Try a different search, or contact support below.</div>`;
  }
  results.innerHTML = html;
}

function _toggleHelpItem(id) {
  const el = document.getElementById(id);
  if (!el) return;
  const wasOpen = el.classList.contains('open');
  el.classList.toggle('open', !wasOpen);
}

// ── SETTINGS ──
function openSettings() {
  _renderSettingsAccount();
  _renderSettingsAppearance();

  const cf = document.getElementById('settingsCrossfadeSlider');
  if (cf) { cf.value = _crossfadeSeconds; document.getElementById('setCfVal').textContent = _crossfadeSeconds + 's'; }

  const autoplay = localStorage.getItem('yaps_autoplay_enabled');
  document.getElementById('setAutoplayToggle').checked = autoplay === null ? true : autoplay === 'true';

  const notifs = localStorage.getItem('yaps_notifs_enabled');
  document.getElementById('setNotifsToggle').checked = (notifs === null ? true : notifs === 'true') && (!yapsPushSupported() || Notification.permission === 'granted');
  const _pl = document.getElementById('setPushLabel'), _ps = document.getElementById('setPushSub');
  if (_pl && typeof YAPS_PUSH_LABEL !== 'undefined') { _pl.textContent = YAPS_PUSH_LABEL; _ps.textContent = YAPS_PUSH_SUB; }

  const rcpt = document.getElementById('setReceiptsToggle'); if (rcpt) rcpt.checked = yapsReadReceiptsOn();
  const onl = document.getElementById('setOnlineToggle'); if (onl) onl.checked = localStorage.getItem('yaps_show_online') !== 'false';

  const quality = localStorage.getItem('yaps_stream_quality') || 'standard';
  document.getElementById('setQualitySelect').value = quality;
  _updateQualitySub(quality);

  openModal('settings');
}

const _qualityDataUsage = {
  data_saver: '~0.5 MB / min (songs uploaded after this update)',
  standard: '~1 MB / min (songs uploaded after this update)',
  high: 'Original file quality',
};
function _updateQualitySub(v) {
  const sub = document.getElementById('setQualitySub');
  if (sub) sub.textContent = _qualityDataUsage[v] || '';
}
function settingsSetQuality(v) {
  if (v === 'high' && !isPremium()) {
    showToast('High quality requires Premium');
    document.getElementById('setQualitySelect').value = localStorage.getItem('yaps_stream_quality') || 'standard';
    closeModal('settings');
    openSubscriptionModal();
    return;
  }
  localStorage.setItem('yaps_stream_quality', v);
  _updateQualitySub(v);
}

// ── APPEARANCE / THEME ──
var PREMIUM_THEMES = [];   // all colors (incl. Aurora) are free; Premium = ad-free only
function setAppTheme(name, opts) {
  opts = opts || {};
  if (PREMIUM_THEMES.indexOf(name) > -1 && !isPremium()) {          // Premium-only themes (Aurora + premium colors)
    showToast((name.charAt(0).toUpperCase() + name.slice(1)) + ' is a Premium color');
    closeModal('settings');
    openSubscriptionModal();
    return;
  }
  if (name === 'neon') {
    document.documentElement.removeAttribute('data-theme');
  } else {
    document.documentElement.setAttribute('data-theme', name);
  }
  localStorage.setItem('yaps_theme', name);
  // keep the browser chrome / PWA status bar color in sync
  const themeColorMeta = document.querySelector('meta[name="theme-color"]');
  if (themeColorMeta) {
    const colors = { neon: '#050712', ocean: '#050b22', crimson: '#0c0505', emerald: '#04120b', violet: '#0b0716', aurora: '#050814', gold: '#0d0a02', sunset: '#120704', rose: '#12050b', arctic: '#03111a' };
    themeColorMeta.setAttribute('content', document.documentElement.getAttribute('data-mode') === 'light' ? '#eef4ff' : (colors[name] || '#050712'));
  }
  _renderSettingsAppearance();
  if (typeof _npInvalidateAccentRGB === 'function') _npInvalidateAccentRGB();
  if (!opts.silent) showToast('Theme updated');
}
function _renderSettingsAppearance() {
  const current = localStorage.getItem('yaps_theme') || 'aurora';
  const grid = document.getElementById('themeSwatchGrid');
  if (!grid) return;
  grid.querySelectorAll('.theme-swatch').forEach(el => {
    el.classList.toggle('active', el.dataset.themeName === current);
  });
  const pg = document.getElementById('premiumColorGrid');
  if (pg) pg.querySelectorAll('.theme-swatch').forEach(el => {
    el.classList.toggle('active', el.dataset.themeName === current);
    el.classList.remove('locked');
  });
  const pcs = document.getElementById('premiumColorsSub');
  if (pcs) pcs.textContent = 'Extra colors, free for everyone, tap to apply';
  const au = document.getElementById('auroraSwatch');
  if (au) {
    au.classList.toggle('active', current === 'aurora');
    au.classList.remove('locked');
    const sub = document.getElementById('auroraSwatchSub');
    if (sub) sub.textContent = 'All colors · glowing 3D neon';
  }
}

function _renderSettingsAccount() {
  const avatar = document.getElementById('setAcctAvatar');
  const name = document.getElementById('setAcctName');
  const email = document.getElementById('setAcctEmail');
  const actionLabel = document.getElementById('setAcctActionLabel');
  const editBtn = document.getElementById('setAcctEditBtn');
  if (_demoUser) {
    avatar.innerHTML = _avatarInner(_demoUser.avatar, _demoUser.name);
    name.textContent = _demoUser.name;
    email.textContent = _demoUser.email;
    actionLabel.textContent = 'Sign out';
    if (editBtn) editBtn.style.display = 'flex';
  } else {
    avatar.textContent = 'G';
    name.textContent = 'Guest';
    email.textContent = 'Not signed in';
    actionLabel.textContent = 'Sign in';
    if (editBtn) editBtn.style.display = 'none';
  }
}

function settingsAccountAction() {
  if (_demoUser) {
    signOutUser();
    _renderSettingsAccount();
  } else {
    closeModal('settings');
    openModal('auth');
  }
}

function settingsSetCrossfade(v) {
  document.getElementById('setCfVal').textContent = v + 's';
  setCrossfadeSeconds(v);
  // keep the queue-panel mixer slider in sync if it's on screen
  const cfSlider = document.getElementById('crossfadeSlider');
  const cfLabel = document.getElementById('cfVal');
  if (cfSlider) cfSlider.value = v;
  if (cfLabel) cfLabel.textContent = v + 's';
}

function settingsSetFlag(key, value) {
  localStorage.setItem(key, value ? 'true' : 'false');
}

function settingsIsNotifsEnabled() {
  const v = localStorage.getItem('yaps_notifs_enabled');
  return v === null ? true : v === 'true';
}

function settingsClearHistory() {
  if (!confirm('Clear your listening history and Wrapped stats? This can\'t be undone.')) return;
  _history = [];
  localStorage.removeItem('yaps_history');
  if (typeof _wrClear === 'function') _wrClear();
  showToast('Listening history cleared');
}

async function settingsClearAllData() {
  if (!confirm('This resets liked songs, history, playlists, downloads and preferences on this device. Continue?')) return;
  await clearAllDownloads(true);
  ['yaps_liked','yaps_history','yaps_playlists','yaps_reposted','yaps_stream_comments','yaps_tips_given',
   'yaps_autoplay_enabled','yaps_notifs_enabled','yaps_notif_seen_broadcast'].forEach(k => localStorage.removeItem(k));
  if (typeof _wrClear === 'function') _wrClear();
  showToast('Local data reset, reloading…');
  setTimeout(() => location.reload(), 900);
}


function switchModalTab(el, tab) {
  el.closest('.modal').querySelectorAll('.modal-tab').forEach(t=>t.classList.remove('active'));
  el.closest('.modal').querySelectorAll('.modal-tab-content').forEach(c=>c.classList.remove('active'));
  el.classList.add('active');
  document.getElementById('modal-'+tab).classList.add('active');
  // if switching to signup, make sure form is visible (not success screen)
  if (tab === 'signup') {
    const form = document.getElementById('modal-signup');
    const success = document.getElementById('signupSuccess');
    if (form) form.style.display = '';
    if (success) success.style.display = 'none';
  }
}

// ── DROPDOWNS ──
function toggleDropdown(id) {
  const dd = document.getElementById(id);
  const isOpen = dd.classList.contains('open');
  closeAllDropdowns();
  if (!isOpen) dd.classList.add('open');
}
function closeAllDropdowns() {
  document.querySelectorAll('.dropdown').forEach(d => d.classList.remove('open'));
}
document.addEventListener('click', e => {
  if (!e.target.closest('.topbar-avatar') && !e.target.closest('.dropdown')) closeAllDropdowns();
}, { passive: true });

// ── TOAST ──
let toastTimer;
function showToast(msg) {
  const toast = document.getElementById('toast');
  document.getElementById('toastMsg').textContent = msg;
  toast.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toast.classList.remove('show'), 2500);
}

// ── LIB TABS ──
function libTab(el, tab) {
  const container = el.closest('.library-tabs, .lib-tabs');
  container.querySelectorAll('.lib-tab').forEach(t => t.classList.remove('active'));
  el.classList.add('active');
  const page = el.closest('.page');
  if (page && page.id === 'page-profile') { renderProfileTab(tab); return; }
  if (page && page.id === 'page-artists') { renderArtistTab(tab); return; }
  _currentLibTab = tab;
  renderLibrary();
}

// ── NOTIF TABS ──
const notifTypeMap = {
  'all': null,
  'mentions': 'mention',
  'likes': 'like',
  'reposts': 'repost',
  'comments': 'comment',
  'messages': 'message',
  'follows': 'follow',
  'releases': 'release',
};
function notifTab(el) {
  el.closest('.notif-tabs').querySelectorAll('.notif-tab').forEach(t=>t.classList.remove('active'));
  el.classList.add('active');
  const label = el.textContent.trim().toLowerCase().split(' ')[0];
  _currentNotifTab = label;
  renderNotifications();
}

// ── LIVE TOP SEARCH ──
let _searchDebounce = null;
function liveTopSearch(query) {
  clearTimeout(_searchDebounce);
  const dd = document.getElementById('searchDropdown');
  if (!query.trim()) { dd.classList.remove('open'); return; }
  _searchDebounce = setTimeout(() => {
    const q = query.toLowerCase();
    const matchedTracks = tracks.filter(t =>
      t.title.toLowerCase().includes(q) || t.artist.toLowerCase().includes(q) || t.genre.toLowerCase().includes(q)
    ).slice(0, 4);
    const matchedArtists = artists.filter(a =>
      a.name.toLowerCase().includes(q)
    ).slice(0, 3);
    const allPlaylists = [
      ..._userPlaylists.map(p => ({ ...p, curated: false })),
      ..._quickVibePlaylists.map(p => ({ ...p, curated: true })),
    ];
    const matchedPlaylists = allPlaylists.filter(p =>
      p.name.toLowerCase().includes(q)
    ).slice(0, 3);

    let html = '';
    if (matchedTracks.length === 0 && matchedArtists.length === 0 && matchedPlaylists.length === 0) {
      html = `<div class="sd-empty"><i class="fas fa-search" style="display:block;font-size:22px;margin-bottom:8px;"></i>No results for "${query}"</div>`;
    } else {
      if (matchedArtists.length) {
        html += `<div class="sd-section-title">Artists</div>`;
        html += matchedArtists.map(a => `
          <div class="sd-item" onclick="document.getElementById('searchDropdown').classList.remove('open');openArtistProfileByName('${a.name.replace(/'/g,"\\'")}')">
            <div class="sd-item-art round"><img loading="lazy" decoding="async" src="${a.img}" alt="${a.name}"></div>
            <div class="sd-item-info"><div class="sd-title">${a.name}</div><div class="sd-sub">${a.followers} followers</div></div>
            <span class="sd-item-type">Artist</span>
          </div>
        `).join('');
      }
      if (matchedPlaylists.length) {
        html += `<div class="sd-section-title">Playlists</div>`;
        html += matchedPlaylists.map(p => `
          <div class="sd-item" onclick="document.getElementById('searchDropdown').classList.remove('open');${p.curated ? `openQuickVibe('${p.id}')` : `openPlaylist('${p.id}')`}">
            <div class="sd-item-art round"><i class="fas fa-list" style="display:flex;align-items:center;justify-content:center;height:100%;color:var(--accent);"></i></div>
            <div class="sd-item-info"><div class="sd-title">${p.name}</div><div class="sd-sub">${(p.trackIndices||[]).length} tracks</div></div>
            <span class="sd-item-type">Playlist</span>
          </div>
        `).join('');
      }
      if (matchedTracks.length) {
        html += `<div class="sd-section-title">Tracks</div>`;
        html += matchedTracks.map((t, i) => `
          <div class="sd-item" onclick="document.getElementById('searchDropdown').classList.remove('open');playTrack(${tracks.indexOf(t)})">
            <div class="sd-item-art"><img loading="lazy" decoding="async" src="${t.img}" alt="${t.title}"></div>
            <div class="sd-item-info"><div class="sd-title">${t.title}</div><div class="sd-sub">${t.artist}</div></div>
            <span class="sd-item-type">${t.genre}</span>
          </div>
        `).join('');
      }
      html += `<div class="sd-all-link" onclick="navigate('search');syncMainSearch('${query.replace(/'/g,"\\'")}');document.getElementById('searchDropdown').classList.remove('open')">See all results for "${query}" →</div>`;
    }
    dd.innerHTML = html;
    dd.classList.add('open');
  }, 180);
}

// ── HOME SEARCH BAR → opens the Search page with the typed query ──
function homeSearchGo() {
  const inp = document.getElementById('homeSearchInput');
  const q = inp ? inp.value.trim() : '';
  navigate('search');
  if (q) syncMainSearch(q);
  else { const mi = document.getElementById('mainSearchInput'); if (mi) mi.focus(); }
  if (inp) inp.value = '';
}
function homeVoiceSearch() {
  navigate('search');
  startVoiceSearch();
}

function syncMainSearch(query) {
  const mi = document.getElementById('mainSearchInput');
  if (mi) { mi.value = query; filterMainSearch(query); }
}

function filterMainSearch(query) {
  const q = query.toLowerCase().trim();
  if (!q) { renderSearch(); return; }
  const browse = document.getElementById('genre-browse-view');
  const detail = document.getElementById('genre-detail-view');
  detail.classList.remove('active');
  browse.style.display = '';

  // Show filtered results in the genre-grid area
  const grid = document.getElementById('genre-grid');
  const matchedTracks = tracks.filter(t =>
    t.title.toLowerCase().includes(q) || t.artist.toLowerCase().includes(q) || t.genre.toLowerCase().includes(q)
  );
  const allPlaylists = [
    ..._userPlaylists.map(p => ({ ...p, curated: false })),
    ..._quickVibePlaylists.map(p => ({ ...p, curated: true })),
  ];
  const matchedPlaylists = allPlaylists.filter(p => p.name.toLowerCase().includes(q));

  if (matchedTracks.length === 0 && matchedPlaylists.length === 0) {
    grid.innerHTML = `<div style="grid-column:1/-1;text-align:center;padding:40px;color:var(--dim);">
      <i class="fas fa-search" style="font-size:40px;margin-bottom:16px;display:block;"></i>
      <div style="font-size:16px;font-weight:600;margin-bottom:6px;">No results found</div>
      <div style="font-size:13px;">Try a different search or browse genres below</div>
    </div>`;
  } else {
    grid.style.gridTemplateColumns = '1fr';
    const playlistsHTML = matchedPlaylists.length ? `
      <div style="font-size:13px;font-weight:700;color:var(--muted);margin:4px 0 8px;">Playlists</div>
      ${matchedPlaylists.map(p => `
        <div class="track-row" style="cursor:pointer;" onclick="${p.curated ? `openQuickVibe('${p.id}')` : `openPlaylist('${p.id}')`}">
          <div style="width:44px;height:44px;border-radius:8px;background:var(--card);display:flex;align-items:center;justify-content:center;color:var(--accent);flex-shrink:0;"><i class="fas fa-list"></i></div>
          <div style="flex:1;min-width:0;margin-left:12px;">
            <div style="font-weight:600;">${p.name}</div>
            <div style="font-size:12px;color:var(--muted);">${(p.trackIndices||[]).length} tracks</div>
          </div>
        </div>
      `).join('')}
      ${matchedTracks.length ? '<div style="font-size:13px;font-weight:700;color:var(--muted);margin:16px 0 8px;">Tracks</div>' : ''}
    ` : '';
    grid.innerHTML = playlistsHTML + matchedTracks.map((t, i) => trackRowHTML(t, tracks.indexOf(t))).join('');
  }
}

document.addEventListener('click', e => {
  if (!e.target.closest('.topbar-search')) {
    const dd = document.getElementById('searchDropdown');
    if (dd) dd.classList.remove('open');
  }
}, { passive: true });

// ── ARTISTS PAGE ──
let _artistFilter = 'All';
let _artistSearch = '';
let _currentArtistProfile = null;

const ATP_GENRES = ['All', 'Afrobeats', 'Hip Hop', 'R&B', 'Dancehall'];
let _atpTimer = null, _atpReturn = 'home', _atpFirst = true;
const _atpReduced = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
const _atpEsc = x => String(x == null ? '' : x).replace(/[&<>"']/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[c]));

// ══════════════════════════════════════════════════════════════════════
//  ARTIST ACCOUNTS → ARTISTS PAGE
//  Every yaps_profiles row with account_type = 'artist' is added to the `artists` array
//  (Artists page, Home artists row, search, Explore) with no manual step.
// ══════════════════════════════════════════════════════════════════════
const _ARTIST_FALLBACK_IMG = 'images/yaps-music-cover.jpg';
let _acctArtistsAt = 0, _acctArtistsBusy = false;
// user-typed text/URLs end up inside HTML/inline handlers/CSS: strip anything that could break out
function _acctSafeText(v, max) { return String(v == null ? '' : v).replace(/[<>"'`&\\\u0000-\u001f]/g, '').replace(/\s+/g, ' ').trim().slice(0, max || 60); }
function _acctSafeUrl(v) {
  v = String(v || '').trim();
  if (!/^https?:\/\//i.test(v)) return '';
  return v.replace(/['"()<>\\\s]/g, c => '%' + c.charCodeAt(0).toString(16).toUpperCase().padStart(2, '0'));
}
function _renderHomeArtistsRow() {
  const arow = document.getElementById('artists-row'); if (!arow) return;
  arow.innerHTML = artists.map(a => `
    <div class="artist-card" onclick="openArtistProfileByName('${a.name.replace(/'/g,"\\'")}')">
      <div class="ac-art">
        <img src="${a.img}" alt="${a.name}" loading="lazy" style="width:100%;height:100%;object-fit:cover;">
      </div>
      <div class="ac-name">${a.name}</div>
      <div class="ac-subs">${a.followers} followers</div>
    </div>
  `).join('');
}
async function _syncAccountArtists(force) {
  if (typeof sb === 'undefined' || !sb || _acctArtistsBusy) return;
  if (!force && Date.now() - _acctArtistsAt < 60000) return;
  _acctArtistsBusy = true;
  try {
    let rows = null;
    for (const cols of ['id,username,full_name,avatar_url,bio,created_at', 'id,username,full_name,avatar_url,bio', 'id,username,full_name,avatar_url']) {
      try { const r = await sb.from('yaps_profiles').select(cols).eq('account_type', 'artist').limit(300); if (!r.error) { rows = r.data || []; break; } } catch (e) {}
    }
    if (!rows) return;
    _acctArtistsAt = Date.now();
    rows.sort((a, b) => Date.parse(b.created_at || 0) - Date.parse(a.created_at || 0));   // newest accounts first
    let changed = false;
    rows.forEach(u => {
      const username = _acctSafeText(u.username, 30);
      let name = _acctSafeText(u.full_name && !/@/.test(u.full_name) ? u.full_name : (username || u.full_name), 40);
      if (!name) return;
      const img = _acctSafeUrl(u.avatar_url) || _ARTIST_FALLBACK_IMG;
      const mine = artists.find(a => a._account && a._account.id === u.id);
      if (mine) {   // already listed: refresh photo / bio / name
        if (mine.img !== img || mine.bio !== (u.bio || '')) { mine.img = img; mine.bio = u.bio || ''; changed = true; }
        return;
      }
      const clash = artists.find(a => _normName(a.name) === _normName(name));
      if (clash && !clash._account) return;                       // a built-in artist already has this name
      if (clash && username) name = _acctSafeText(name + ' (@' + username + ')', 60);   // two accounts, same display name
      else if (clash) return;
      artists.push({ name, img, followers: '0', bio: u.bio || '', username, _fromAccount: true, _account: { id: u.id, full_name: u.full_name || name, username: u.username || '', avatar_url: u.avatar_url || '' } });
      changed = true;
    });
    if (changed) {
      try { _renderHomeArtistsRow(); } catch (e) {}
      try {
        const gv = document.getElementById('artists-grid-view');
        if (currentPage === 'artists' && gv && gv.style.display !== 'none') renderArtistsGrid();
      } catch (e) {}
    }
  } catch (e) { console.warn('Artist accounts unavailable:', e && e.message); }
  finally { _acctArtistsBusy = false; }
}
window.addEventListener('load', () => setTimeout(() => _syncAccountArtists(true), 900));

function renderArtistsPage(withSkeleton) {
  _syncAccountArtists();   // pick up artists who created an account since the last visit (throttled to once a minute)
  document.getElementById('artist-profile-detail').style.display = 'none';
  document.getElementById('artists-grid-view').style.display = '';
  _atpRenderChips();
  const q = document.getElementById('artistSearchInput');
  if (q && q.value !== _artistSearch) q.value = _artistSearch;
  const cl = document.getElementById('atpClear'); if (cl) cl.classList.toggle('show', !!_artistSearch);
  if (withSkeleton === false) { renderArtistsGrid(); return; }
  _atpSkeleton(withSkeleton === 'short' ? 220 : 420);
}

function _atpRenderChips() {
  const wrap = document.getElementById('atpChips'); if (!wrap) return;
  wrap.innerHTML = ATP_GENRES.map(g =>
    `<button type="button" class="atp-chip${g === _artistFilter ? ' active' : ''}" role="tab" aria-selected="${g === _artistFilter}" onclick="filterArtistsByGenre('${g.replace(/'/g, "\\'")}')">${_atpEsc(g)}</button>`).join('');
}

function _atpSkeleton(ms) {
  const grid = document.getElementById('artists-full-grid'); if (!grid) return;
  clearTimeout(_atpTimer);
  document.getElementById('atpCount').innerHTML = '';
  grid.innerHTML = Array.from({ length: 12 }, () =>
    `<div class="artist-card-full atp-sk"><div class="sk sk-c"></div><div class="sk sk-l"></div><div class="sk sk-s"></div><div class="sk sk-b"></div></div>`).join('');
  _atpTimer = setTimeout(renderArtistsGrid, _atpReduced ? 0 : ms);
}

// Same data + same filters as before: `artists`, name search, genre via the tracks catalog.
function _atpFiltered() {
  let list = artists;
  if (_artistSearch) {
    const q = _artistSearch.trim().toLowerCase();
    if (q) list = list.filter(a => a.name.toLowerCase().includes(q));
  }
  if (_artistFilter !== 'All') {
    const g = _artistFilter.toLowerCase();
    list = list.filter(a => tracks.some(t => _artistMatchRegex(a.name).test(t.artist.toLowerCase()) && (t.genre || '').toLowerCase().includes(g)));
  }
  return list;
}

function renderArtistsGrid() {
  const grid = document.getElementById('artists-full-grid'); if (!grid) return;
  clearTimeout(_atpTimer);
  const filtered = _atpFiltered();
  const count = document.getElementById('atpCount');

  if (filtered.length === 0) {
    count.innerHTML = '';
    const q = _artistSearch.trim(), g = _artistFilter;
    const title = q ? 'No artists found' : `No ${_atpEsc(g)} artists yet`;
    const msg = q ? `We couldn't find “${_atpEsc(q)}”${g !== 'All' ? ' in ' + _atpEsc(g) : ''}. Check the spelling or try another name.` : 'New artists join YAPS all the time. Try another genre in the meantime.';
    grid.innerHTML = `<div class="atp-empty"><div class="atp-empty-ico"><i class="fas fa-user-slash"></i></div><h3>${title}</h3><p>${msg}</p><button type="button" onclick="atpReset()">${q ? 'Clear search' : 'Show all artists'}</button></div>`;
    return;
  }

  const bits = [];
  if (_artistFilter !== 'All') bits.push(_atpEsc(_artistFilter));
  if (_artistSearch.trim()) bits.push('“' + _atpEsc(_artistSearch.trim()) + '”');
  count.innerHTML = `<b>${filtered.length}</b> artist${filtered.length === 1 ? '' : 's'}${bits.length ? ' · ' + bits.join(' · ') : ''}`;

  grid.innerHTML = filtered.map((a, i) => {
    const isFollowing = _followedArtists.has(a.name);
    const re = _artistMatchRegex(a.name);
    const trackCount = tracks.filter(t => re.test(t.artist.toLowerCase())).length;
    const jsName = a.name.replace(/\\/g, '\\\\').replace(/'/g, "\\'");
    const name = _atpEsc(a.name);
    return `
      <div class="artist-card-full" role="button" tabindex="0" aria-label="Open ${name}" style="--d:${_atpReduced ? 0 : Math.min(i, 12) * 40}ms" onclick="openArtistProfileByName('${_atpEsc(jsName)}')" onkeydown="if(event.key==='Enter'&&event.target===this){openArtistProfileByName('${_atpEsc(jsName)}')}">
        <div class="acf-art"><img src="${_atpEsc(a.img)}" alt="${name}" decoding="async" ${i > 7 ? 'loading="lazy"' : ''} onload="this.classList.add('ready')" onerror="this.classList.add('ready');this.style.visibility='hidden'"></div>
        <div class="acf-name">${name}</div>
        <div class="acf-subs"><span><b>${_atpEsc(a.followers)}</b> followers</span><span>${trackCount} track${trackCount === 1 ? '' : 's'}</span></div>
        <button type="button" class="acf-follow-btn ${isFollowing ? 'following' : ''}" aria-pressed="${isFollowing}" onclick="event.stopPropagation();toggleFollowArtist('${_atpEsc(jsName)}',this)">${isFollowing ? 'Following' : '+ Follow'}</button>
        <button type="button" class="acf-msg-btn acf-join-btn" aria-label="Join ${name} community" onclick="event.stopPropagation();atpJoinCommunity('${_atpEsc(jsName)}')"><i class="fas fa-people-group"></i> Join Community</button>
      </div>`;
  }).join('');
}


// "Join Community" on every artist card: opens that artist's community so fans of the artist can find each other
function atpJoinCommunity(name) {
  try {
    const a = (typeof _atpFiltered === 'function' ? _atpFiltered() : []).find(x => x.name === name) || { name };
    const uid = String((a._account && a._account.id) || '').toLowerCase().replace(/[^a-z0-9-]/g, '');
    const key = String(name || '').toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 60);
    if (typeof window.openCommunity === 'function') {
      window.openCommunity({ c: uid ? 'artist-u-' + uid : 'artist-' + key, name: name, join: true });   // same room ids as the artist profile's Join Community button
    } else if (typeof cnMessageArtist === 'function') { cnMessageArtist(name); }
  } catch (e) { console.log('[YAPS] Join community failed', e); showToast('Could not open the community, try again'); }
}
let _atpSearchT = null;
function filterArtists(query) {
  _artistSearch = query || '';
  const cl = document.getElementById('atpClear'); if (cl) cl.classList.toggle('show', !!_artistSearch);
  clearTimeout(_atpSearchT);
  _atpSearchT = setTimeout(renderArtistsGrid, 150);
}
function atpClearSearch() {
  const q = document.getElementById('artistSearchInput'); if (q) { q.value = ''; q.focus(); }
  filterArtists('');
}

function filterArtistsByGenre(genre) {
  if (genre === _artistFilter) return;
  _artistFilter = genre;
  _atpRenderChips();
  const on = document.querySelector('#atpChips .atp-chip.active');
  if (on && on.scrollIntoView) on.scrollIntoView({ inline: 'center', block: 'nearest', behavior: _atpReduced ? 'auto' : 'smooth' });
  _atpSkeleton(220);
}
function atpReset() {
  if (_artistSearch.trim()) { _artistSearch = ''; const q = document.getElementById('artistSearchInput'); if (q) q.value = ''; const cl = document.getElementById('atpClear'); if (cl) cl.classList.remove('show'); }
  else _artistFilter = 'All';
  _atpRenderChips();
  _atpSkeleton(200);
}

// "See all" from a Featured Artists section → the existing Artists page (fresh view).
function atpOpen() {
  if (currentPage !== 'artists') _atpReturn = currentPage || 'home';
  _artistSearch = ''; _artistFilter = 'All';
  navigate('artists');
  if (typeof updateBottomNav === 'function') updateBottomNav('search');
  try { history.pushState({ atp: 1 }, ''); } catch (e) {}
}
function _atpLeave() {
  const to = _atpReturn || 'home';
  navigate(to);
  if (typeof updateBottomNav === 'function') updateBottomNav(to);
}
function atpBack() {
  if (history.state && history.state.atp) history.back(); // popstate handler navigates
  else _atpLeave();
}
window.addEventListener('popstate', () => {
  if (currentPage !== 'artists') return;
  const detail = document.getElementById('artist-profile-detail');
  if (detail && detail.style.display !== 'none') {          // back from a profile → artists grid first
    closeArtistProfile();
    try { history.pushState({ atp: 1 }, ''); } catch (e) {}
    return;
  }
  _atpLeave();
});

function toggleFollowArtist(name, btn) {
  if (_followedArtists.has(name)) {
    _followedArtists.delete(name);
    btn.textContent = '+ Follow';
    btn.classList.remove('following');
    showToast('Unfollowed ' + name);
  } else {
    _followedArtists.add(name);
    btn.textContent = 'Following';
    btn.classList.add('following');
    showToast('Following ' + name + '!');
  }
  _persistSave();
  if (typeof renderPersonalizedHome === 'function') renderPersonalizedHome();
}

const artistBios = {
  'Bobi Wine': 'Robert Kyagulanyi Ssentamu, known as Bobi Wine, is a Ugandan politician, activist, and singer. He rose to fame with socially conscious music before becoming a leading opposition figure in Uganda.',
  'Jose Chameleone': 'Joseph Mayanja, known professionally as Jose Chameleone, is one of Uganda\'s most celebrated musicians. His career spans over two decades of Afropop, dancehall, and reggae hits.',
  'Eddy Kenzo': 'Eddy Kenzo is a Ugandan singer and songwriter born Edward Kiwanuka. He won the BET Award for Best New International Act in 2015, putting Ugandan music on the world stage.',
  'Sheebah Karungi': 'Sheebah Karungi is a Ugandan singer, dancer and actress. Known as the Queen of Kampala, she is one of Uganda\'s most successful and recognizable female artists.',
  'Fik Fameica': 'Fik Fameica is a Ugandan rapper and entertainer known for catchy Luganda rap hits and his vibrant energy. He has collaborated with top East African artists.',
  'Lutty Neika': 'Lutty Neika is a Ugandan singer known for melodic Afropop hits like "Oyaya", and teamed up with Bravion Emcee on the collab single "Anaconda".',
  'Bravion Emcee': 'Bravion Emcee is a Ugandan artist who joined forces with Lutty Neika on the collaborative single "Anaconda".',
};

// Matches a track to an artist using a word-boundary check against the FULL
// artist name (not just the first word), so "A Pass" no longer matches any
// track whose artist string merely contains the letter "a".
function _artistMatchRegex(name) {
  const esc = name.toLowerCase().replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return new RegExp('(^|[^a-z0-9])' + esc + '($|[^a-z0-9])', 'i');
}

function openArtistProfileByName(name) {
  const a = artists.find(ar => ar.name === name);
  if (!a) { showToast('Artist not found'); return; }
  navigate('artists');
  _currentArtistProfile = a;
  _resolveArtistAccount(a);   // Message is always shown: direct message if the artist has a YAPS account, otherwise their YAPS Connect community
  try { cnArtistProfileShown(a); } catch (e) {}

  document.getElementById('artists-grid-view').style.display = 'none';
  const detail = document.getElementById('artist-profile-detail');
  detail.style.display = 'block';

  document.getElementById('apDetailBanner').style.backgroundImage = `url('${a.img}')`;
  document.getElementById('apDetailAvatar').style.backgroundImage = `url('${a.img}')`;
  document.getElementById('apDetailName').textContent = a.name;
  document.getElementById('apDetailHandle').textContent = a._fromAccount ? `@${a.username || a.name.toLowerCase().replace(/\s+/g,'')} · Uganda` : `@${a.name.toLowerCase().replace(/\s+/g,'')} · Kampala, Uganda`;
  document.getElementById('apDetailFollowers').textContent = a.followers;
  document.getElementById('apDetailBio').textContent = artistBios[a.name] || (a._fromAccount ? (a.bio || `${a.name} just joined YAPSMusic.`) : `${a.name} is a celebrated Ugandan artist with ${a.followers} followers on YAPSMusic.`);

  // Tracks by artist — exact word-boundary match, so collabs ("X ft. Y") still
  // attribute correctly to each named artist, but "A Pass" no longer matches
  // every track containing the letter "a".
  const matchRe = _artistMatchRegex(a.name);
  const artistTracks = tracks.filter(t => matchRe.test(t.artist.toLowerCase()));
  document.getElementById('apDetailTracks').textContent = artistTracks.length;
  const totalPlays = artistTracks.reduce((sum, t) => {
    const n = parseFloat(t.plays.replace(/[KM]/g, m => m === 'K' ? 'e3' : 'e6'));
    return sum + n;
  }, 0);
  document.getElementById('apDetailPlays').textContent = totalPlays > 1e6 ? (totalPlays/1e6).toFixed(1)+'M' : Math.floor(totalPlays/1e3)+'K';

  const isFollowing = _followedArtists.has(a.name);
  const followBtn = document.getElementById('apFollowBtn');
  followBtn.innerHTML = isFollowing ? '<i class="fas fa-check"></i> Following' : '<i class="fas fa-user-plus"></i> Follow';
  followBtn.style.background = isFollowing ? 'var(--card2)' : '';

  const list = document.getElementById('artist-detail-tracks');
  list.innerHTML = artistTracks.length > 0
    ? artistTracks.map(t => trackRowHTML(t, tracks.indexOf(t))).join('')
    : emptyLibState('fa-music', 'No tracks yet', `${a.name} doesn't have any songs on YAPS yet, check back soon.`);

  // Scope next/prev/shuffle playback to just this artist's songs while
  // their profile is open, so tapping a track here doesn't pull in the
  // full catalog.
  // Opening a profile must not hijack what's already playing: only take over if nothing is playing
  // (or the playing song is already one of theirs); otherwise wait until a song here is tapped.
  const _aq = artistTracks.map(t => tracks.indexOf(t));
  if (!_hasPlayedOnce || (!isPlaying && audioEngine.paused) || _aq.includes(currentTrack)) {
    _activeQueue = _aq; _activeQueueLabel = a.name; _activeQueueScope = ['artists']; _pendingQueue = null;
  } else {
    _pendingQueue = { list: _aq, label: a.name, scope: ['artists'] };
  }
}

function closeArtistProfile() {
  const _mb = document.getElementById('apMsgBtn'); if (_mb) _mb.style.display = 'none';
  document.getElementById('artist-profile-detail').style.display = 'none';
  document.getElementById('artists-grid-view').style.display = '';
  _currentArtistProfile = null;
  _pendingQueue = null;
  // keep playing in this artist's order if their song is what's playing
  if (!(_activeQueue && _activeQueue.includes(currentTrack) && (isPlaying || !audioEngine.paused))) {
    _activeQueue = null; _activeQueueLabel = null; _activeQueueScope = null;
  }
}

// Artist Radio: the artist's songs first (shuffled), then songs from the same genres, as one queue
function startArtistRadio() {
  const a = _currentArtistProfile;
  if (!a) return;
  const playable = t => !!(t && (t.audioUrl || t.audioSrc));
  const shuf = arr => { for (let i = arr.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [arr[i], arr[j]] = [arr[j], arr[i]]; } return arr; };
  const re = _artistMatchRegex(a.name);
  const own = tracks.filter(t => playable(t) && re.test(String(t.artist).toLowerCase()));
  const genres = new Set(own.map(t => t.genre).filter(Boolean));
  const ownSet = new Set(own);
  let more = tracks.filter(t => playable(t) && !ownSet.has(t) && (genres.size ? genres.has(t.genre) : true));
  const list = shuf(own.slice()).concat(shuf(more).slice(0, 40)).map(t => tracks.indexOf(t));
  if (!list.length) { showToast('No songs available for ' + a.name + ' Radio yet'); return; }
  _pendingQueue = null;
  _activeQueue = list; _activeQueueLabel = a.name + ' Radio'; _activeQueueScope = ['artists'];
  playTrack(list[0]);
  showToast(a.name + ' Radio');
}
function toggleArtistFollow() {
  if (!_currentArtistProfile) return;
  const name = _currentArtistProfile.name;
  const btn = document.getElementById('apFollowBtn');
  if (_followedArtists.has(name)) {
    _followedArtists.delete(name);
    btn.innerHTML = '<i class="fas fa-user-plus"></i> Follow';
    btn.style.background = '';
    showToast('Unfollowed ' + name);
  } else {
    _followedArtists.add(name);
    btn.innerHTML = '<i class="fas fa-check"></i> Following';
    btn.style.background = 'var(--card2)';
    showToast('Now following ' + name + '!');
  }
  _persistSave();
  if (typeof renderPersonalizedHome === 'function') renderPersonalizedHome();
}

// ── EXPLORE PAGE ──
function renderExplorePage() {
  renderExploreSection('featured');
}

// ── Explore helpers ──
function exploreTrackCard(t) {
  const idx = tracks.indexOf(t);
  return `
    <div class="track-card" onclick="playTrack(${idx})" style="cursor:pointer;">
      <div class="tc-art">
        <img src="${t.img}" alt="${t.title}" loading="lazy" style="width:100%;height:100%;object-fit:cover;">
        <div class="tc-waveform">${waveformBars(22)}</div>
        <div class="tc-play"><i class="fas fa-play"></i></div>
      </div>
      <div class="tc-title">${t.title}</div>
      <div class="tc-artist">${t.artist}</div>
      <div class="tc-meta">
        <span><i class="fas fa-play"></i> ${t.plays}</span>
        <span><i class="fas fa-heart"></i> ${t.likes}</span>
      </div>
    </div>`;
}

function exploreChartRow(t, rank) {
  const idx = tracks.indexOf(t);
  const isTop = rank <= 3;
  return `
    <div class="chart-item" onclick="playTrack(${idx})">
      <div class="chart-rank ${isTop ? 'top' : ''}">${rank}</div>
      <div class="chart-art"><img src="${t.img}" alt="${t.title}" loading="lazy" style="width:100%;height:100%;object-fit:cover;border-radius:6px;"></div>
      <div class="chart-info">
        <div class="chart-title">${t.title}</div>
        <div class="chart-artist">${t.artist} · ${t.genre}</div>
      </div>
      <div class="chart-plays">${t.plays}</div>
      <div class="chart-trend ${isTop ? 'up' : 'new'}" style="margin-left:8px;">${isTop ? '▲' : '●'}</div>
    </div>`;
}

// Songs that belong to a mood — the SAME rule the mood page uses, so the card
// artwork, the song count and the page you land on always agree.
function _moodTracks(genre) {
  const g = String(genre).toLowerCase();
  return tracks.filter(t =>
    (t.genre || '').toLowerCase().includes(g) ||
    (t.tags || []).some(tag => tag.toLowerCase().includes(g))
  );
}

// Pick the cover art that best represents a mood: prefer a cover that isn't
// reused across many songs (e.g. a generic playlist banner) so cards look distinct.
function _moodCover(list) {
  if (!list.length) return '';
  const freq = {};
  list.forEach(t => { freq[t.img] = (freq[t.img] || 0) + 1; });
  const distinct = list.find(t => t.img && freq[t.img] <= 3);
  return (distinct || list.find(t => t.img) || {}).img || '';
}

function exploreMoodCard(emoji, label, color, filter) {
  const list = _moodTracks(filter);
  if (!list.length) return '';               // no songs yet → don't show an empty collection
  const cover = _moodCover(list);
  const url = cover.replace(/ /g, '%20').replace(/'/g, '%27').replace(/"/g, '%22');
  const safeFilter = String(filter).replace(/'/g, "\\'");
  const safeLabel  = String(label).replace(/'/g, "\\'");
  // layers (top→bottom): dark fade for legible text, cover art, gradient fallback
  const bg = cover
    ? `linear-gradient(to top,rgba(5,11,34,0.88) 0%,rgba(5,11,34,0.35) 55%,rgba(5,11,34,0.10) 100%),url('${url}') center 25%/cover no-repeat,${color}`
    : color;
  return `
    <div class="mood-card" onclick="applyExploreMood('${safeFilter}','${safeLabel}')" style="background:${bg};">
      <div class="mood-card-count"><i class="fas fa-music"></i> ${list.length} song${list.length === 1 ? '' : 's'}</div>
      <div class="mood-card-label">${label}</div>
    </div>`;
}

function applyExploreMood(genre, label) {
  const container = document.getElementById('explore-content');
  const filtered = _moodTracks(genre);
  const toShow = filtered.length ? filtered : tracks.slice(0, 8);
  container.innerHTML = `
    <div style="display:flex;align-items:center;gap:10px;margin-bottom:16px;cursor:pointer;" onclick="renderExploreSection('featured')">
      <i class="fas fa-arrow-left" style="color:var(--accent);"></i>
      <span style="font-size:13px;font-weight:600;color:var(--accent);">Back to Explore</span>
    </div>
    <div class="explore-section-title" style="margin-top:0;">${label || genre} · ${toShow.length} tracks</div>
    <div class="explore-track-grid">${toShow.map(t => exploreTrackCard(t)).join('')}</div>`;
}

function exploreArtistSpotlight(a) {
  const artistTracks = tracks.filter(t => _artistMatchRegex(a.name).test(t.artist.toLowerCase()));
  const firstTrackIdx = artistTracks.length ? tracks.indexOf(artistTracks[0]) : null;
  const isFollowing = _followedArtists.has(a.name);
  return `
    <div style="
      background:linear-gradient(135deg, var(--card), var(--card2));
      border:1px solid var(--border); border-radius:14px;
      overflow:hidden; cursor:pointer; flex-shrink:0; width:200px;
      transition:transform 0.2s,border-color 0.2s;"
      onmouseover="this.style.borderColor='var(--accent)';this.style.transform='translateY(-2px)'"
      onmouseout="this.style.borderColor='var(--border)';this.style.transform=''"
      onclick="openArtistProfileByName('${a.name.replace(/'/g,"\\'")}')">
      <div style="height:80px;background:url('${a.img}') center/cover no-repeat;position:relative;">
        <div style="position:absolute;inset:0;background:linear-gradient(to bottom,transparent 40%,rgba(5,11,34,0.9));"></div>
      </div>
      <div style="padding:10px 12px;">
        <div style="display:flex;align-items:center;gap:8px;margin-top:-26px;margin-bottom:8px;">
          <img loading="lazy" decoding="async" src="${a.img}" style="width:40px;height:40px;border-radius:50%;border:2px solid var(--border);object-fit:cover;flex-shrink:0;" alt="${a.name}">
          <div style="margin-top:14px;">
            <div style="font-size:13px;font-weight:700;">${a.name}</div>
            <div style="font-size:11px;color:var(--muted);">${a.followers} followers</div>
          </div>
        </div>
        <div style="display:flex;gap:6px;margin-top:4px;">
          <button onclick="event.stopPropagation();${firstTrackIdx !== null ? `playTrack(${firstTrackIdx})` : `showToast('${a.name.replace(/'/g,"\\'")} has no tracks yet')`}" style="flex:1;background:var(--accent);color:#fff;border:none;border-radius:8px;padding:6px;font-size:12px;font-weight:700;cursor:pointer;"><i class="fas fa-play"></i> Play</button>
          <button onclick="event.stopPropagation();toggleFollowArtist('${a.name.replace(/'/g,"\\'")}',this)" class="acf-follow-btn ${isFollowing ? 'following' : ''}" style="flex:1;border-radius:8px;padding:6px;font-size:12px;">${isFollowing ? '' : '+ Follow'}</button>
        </div>
      </div>
    </div>`;
}

function renderExploreSection(section) {
  const container = document.getElementById('explore-content');
  let html = '';

  if (section === 'featured') {
    // ── Hero featured track — fixed index, not random ──
    const hero = tracks.find(t => t.id === 201) || tracks[0]; // stable pick: Yoyo (looked up by id so re-ranking the list doesn't change it)
    const heroIdx = tracks.indexOf(hero);
    html += `
      <div onclick="playTrack(${heroIdx})" style="
        position:relative; border-radius:16px; overflow:hidden;
        height:200px; cursor:pointer; margin-bottom:24px;
        background:url('${hero.img}') center/cover no-repeat;">
        <div style="position:absolute;inset:0;background:linear-gradient(to right,rgba(5,11,34,0.92) 0%,rgba(5,11,34,0.4) 100%);"></div>
        <div style="position:absolute;inset:0;padding:24px;display:flex;flex-direction:column;justify-content:flex-end;gap:6px;">
          <div style="font-size:11px;font-weight:700;letter-spacing:1px;color:var(--accent);text-transform:uppercase;">Featured Track</div>
          <div style="font-size:22px;font-weight:900;line-height:1.2;">${hero.title}</div>
          <div style="font-size:13px;color:var(--muted);">${hero.artist} · ${hero.genre}</div>
          <div style="display:flex;gap:12px;margin-top:8px;">
            <button style="background:var(--accent);color:#fff;border:none;border-radius:24px;padding:8px 20px;font-weight:700;font-size:13px;cursor:pointer;"><i class="fas fa-play"></i> Play Now</button>
            <button onclick="event.stopPropagation();showToast('Added to queue!')" style="background:rgba(255,255,255,0.15);color:#fff;border:1px solid rgba(255,255,255,0.3);border-radius:24px;padding:8px 16px;font-weight:600;font-size:13px;cursor:pointer;"><i class="fas fa-plus"></i> Queue</button>
          </div>
        </div>
        <div style="position:absolute;top:16px;right:16px;background:rgba(0,0,0,0.5);border-radius:8px;padding:4px 10px;font-size:11px;font-weight:700;color:var(--accent);">${hero.plays} plays</div>
      </div>`;

    // ── Mood Collections ──
    html += `<div class="explore-section-title">Mood Collections</div>`;
    html += `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:10px;margin-bottom:24px;">
      ${exploreMoodCard('','Afrobeats Bangers','linear-gradient(135deg,var(--accent-dark),var(--accent))','Afrobeats')}
      ${exploreMoodCard('','Ugandan Classics','linear-gradient(135deg,color-mix(in srgb,var(--accent-dark) 55%,#000),var(--accent-dark))','Afropop')}
      ${exploreMoodCard('','Dance Floor','linear-gradient(145deg,var(--accent-dark),var(--accent-light))','Dancehall')}
      ${exploreMoodCard('','Hip Hop UG','linear-gradient(125deg,color-mix(in srgb,var(--accent-dark) 40%,#000),var(--accent))','Hip Hop')}
      ${exploreMoodCard('','Luganda Vibes','linear-gradient(120deg,var(--accent-dark),var(--accent-light))','Luganda')}
      ${exploreMoodCard('','R&B Vibes','linear-gradient(110deg,var(--accent-light),var(--accent))','R&B')}
    </div>`;

    // ── Artist Spotlight ──
    html += `<div class="explore-section-title">Artist Spotlight</div>`;
    html += `<div style="display:flex;gap:12px;overflow-x:auto;padding-bottom:12px;margin-bottom:24px;scrollbar-width:none;">
      ${artists.slice(0, 8).map(a => exploreArtistSpotlight(a)).join('')}
    </div>`;

    // ── Hot right now grid — Gospel-only weekends, Gospel-free weekdays ──
    const hot = gospelWeekendPool(tracks).slice(0, 8);
    html += `<div class="explore-section-title">Hot Right Now</div>`;
    html += `<div class="explore-track-grid">${hot.map(t => exploreTrackCard(t)).join('')}</div>`;

    // ── Uganda Legends ──
    const legends = tracks.filter(t => ['King Saha','Rema Namakula','John Blaq','Sheebah','Azawi','Joshua Baraka'].some(n => t.artist.includes(n)));
    if (legends.length) {
      html += `<div class="explore-section-title">Uganda Legends</div>`;
      html += `<div class="explore-track-grid">${legends.slice(0,8).map(t => exploreTrackCard(t)).join('')}</div>`;
    }

  } else if (section === 'new') {
    // ── New releases hero — Gospel-only weekends, Gospel-free weekdays ──
    const newPool = gospelWeekendPool(tracks);
    const newest = newPool.slice(-3);
    html += `<div class="explore-section-title" style="margin-top:0;">Just Dropped</div>`;
    html += `<div style="display:flex;flex-direction:column;gap:0;border:1px solid var(--border);border-radius:14px;overflow:hidden;margin-bottom:24px;">
      ${newest.map(t => {
        const idx = tracks.indexOf(t);
        return `<div class="chart-item" onclick="playTrack(${idx})" style="border-bottom:1px solid var(--border);">
          <div class="chart-art"><img src="${t.img}" alt="${t.title}" loading="lazy" style="width:100%;height:100%;object-fit:cover;border-radius:6px;"></div>
          <div class="chart-info"><div class="chart-title">${t.title}</div><div class="chart-artist">${t.artist}</div></div>
          <div style="font-size:11px;color:var(--accent);font-weight:700;margin-left:auto;">NEW</div>
        </div>`;
      }).join('')}
    </div>`;

    // ── Fresh drops grid ──
    html += `<div class="explore-section-title">Fresh Drops</div>`;
    html += `<div class="explore-track-grid">${newPool.slice(-10).map(t => exploreTrackCard(t)).join('')}</div>`;

    // ── TikTok ──
    const tiktok = tracks.filter(t => t.tags.includes('TikTok'));
    if (tiktok.length) {
      html += `<div class="explore-section-title">Fresh on TikTok</div>`;
      html += `<div class="explore-track-grid">${tiktok.slice(0,6).map(t => exploreTrackCard(t)).join('')}</div>`;
    }

  } else if (section === 'trending') {
    // ── Chart-style ranked list — Gospel-only weekends, Gospel-free weekdays ──
    const trendPool = gospelWeekendPool(tracks);
    const byPlays = [...trendPool].sort((a,b) => {
      const parse = s => parseFloat(s.replace('M','e6').replace('K','e3'));
      return parse(b.plays) - parse(a.plays);
    });
    html += `<div class="explore-section-title" style="margin-top:0;">Top 10 Chart</div>`;
    html += `<div style="border:1px solid var(--border);border-radius:14px;overflow:hidden;margin-bottom:24px;">
      ${(isGospelWeekend() ? byPlays : curatedTrending()).slice(0,10).map((t, i) => exploreChartRow(t, i+1)).join('')}
    </div>`;

    // ── Rising fast grid ──
    const rising = isGospelWeekend() ? trendPool : trendPool.filter(t => t.tags.includes('Trending'));
    html += `<div class="explore-section-title">Rising Fast</div>`;
    html += `<div class="explore-track-grid">${rising.slice(0,8).map(t => exploreTrackCard(t)).join('')}</div>`;

  } else if (section === 'tiktok') {
    const viral = tracks.filter(t => t.tags.includes('TikTok'));
    const remixes = tracks.filter(t => t.tags.includes('Remix'));

    // ── TikTok viral hero ──
    if (viral.length) {
      const hero = viral[0];
      const heroIdx = tracks.indexOf(hero);
      html += `
        <div onclick="playTrack(${heroIdx})" style="
          position:relative;border-radius:16px;overflow:hidden;height:160px;cursor:pointer;margin-bottom:20px;
          background:linear-gradient(135deg,#0a2050,#1565c0);">
          <div style="position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:64px;opacity:0.15;"></div>
          <div style="position:absolute;inset:0;padding:20px;display:flex;flex-direction:column;justify-content:flex-end;gap:4px;">
            <div style="font-size:11px;font-weight:700;letter-spacing:1px;color:#6fb6ff;text-transform:uppercase;">TikTok #1</div>
            <div style="font-size:20px;font-weight:900;">${hero.title}</div>
            <div style="font-size:13px;color:rgba(255,255,255,0.7);">${hero.artist} · ${hero.plays} plays</div>
          </div>
        </div>`;
    }

    html += `<div class="explore-section-title" style="margin-top:0;">TikTok Viral Hits</div>`;
    html += `<div class="explore-track-grid">${(viral.length ? viral : tracks.slice(0,8)).map(t => exploreTrackCard(t)).join('')}</div>`;

    if (remixes.length) {
      html += `<div class="explore-section-title">Remix Zone</div>`;
      html += `<div class="explore-track-grid">${remixes.map(t => exploreTrackCard(t)).join('')}</div>`;
    }

  }

  container.innerHTML = html || '<div style="padding:40px;text-align:center;color:var(--dim);">Nothing here yet, check back soon!</div>';
}

// ── RENDER DASHBOARD ──
function renderDashboard() {
  if (!_isOwner()) {
    document.getElementById('dashContent').style.display = 'none';
    document.getElementById('dashAccessDenied').style.display = 'block';
    const dm = document.getElementById('dashDeniedMsg');
    if (dm) dm.textContent = _demoUser ? ('You are signed in as ' + (_demoUser.email || _demoUser.name) + ', which is not the owner account. Sign in with the owner account.') : 'This area is private. Sign in with the owner account to access it.';
    // Re-check in case the owner list was only just set up
    if (_demoUser && !window._ownerRechecked) { window._ownerRechecked = true; _refreshOwner().then(() => { if (_isOwner()) renderDashboard(); }); }
    return;
  }
  document.getElementById('dashContent').style.display = '';
  document.getElementById('dashAccessDenied').style.display = 'none';

  // Update owner name
  const ownerNameEl = document.getElementById('dashOwnerName');
  if (ownerNameEl) ownerNameEl.textContent = _demoUser ? _demoUser.name : 'YAPS Artist';

  // Real data only: stats come from the signed-in owner's own tracks
  const _num = v => { const x = String(v == null ? 0 : v).trim(); const n = parseFloat(x.replace(/,/g,'')) || 0; return /m$/i.test(x) ? n*1e6 : /k$/i.test(x) ? n*1e3 : n; };
  const _fmt = n => n >= 1e6 ? (n/1e6).toFixed(1).replace(/\.0$/,'') + 'M' : n >= 1e3 ? (n/1e3).toFixed(1).replace(/\.0$/,'') + 'K' : String(Math.round(n));
  const me = _demoUser && _demoUser.name ? _demoUser.name.trim().toLowerCase() : null;
  const mine = me ? tracks.filter(t => String(t.artist || '').trim().toLowerCase() === me) : [];
  const statCards = document.querySelectorAll('.dash-stat-card .dsc-val');
  if (statCards[0]) statCards[0].textContent = _fmt(mine.reduce((n, t) => n + _num(t.plays), 0));
  if (statCards[2]) statCards[2].textContent = _fmt(mine.reduce((n, t) => n + _num(t.likes), 0));
  const _empty = '<div style="padding:22px 8px;text-align:center;color:var(--muted);font-size:13px;">No uploads yet. Upload your first track to see it here.</div>';

  // Recent releases (your uploads)
  const releasesEl = document.getElementById('dashReleasesList');
  if (releasesEl) {
    releasesEl.innerHTML = mine.length ? mine.slice(0, 5).map(t => `
      <div class="dash-release-row" onclick="playTrack(${tracks.indexOf(t)})">
        <img loading="lazy" decoding="async" src="${t.img}" style="width:40px;height:40px;border-radius:8px;object-fit:cover;flex-shrink:0;" alt="${t.title}">
        <div style="flex:1;min-width:0;">
          <div style="font-size:13px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${t.title}</div>
          <div style="font-size:11px;color:var(--muted);">${t.genre}</div>
        </div>
        <div style="text-align:right;flex-shrink:0;">
          <div style="font-size:12px;color:var(--muted);"><i class="fas fa-music" style="font-size:10px;"></i> ${t.plays}</div>
          <div style="font-size:12px;color:var(--muted);"><i class="fas fa-heart" style="font-size:10px;"></i> ${t.likes}</div>
        </div>
      </div>`).join('') : _empty;
  }

  // Top tracks (your uploads, by plays)
  const topEl = document.getElementById('dashTopTracksList');
  if (topEl) {
    const sorted = [...mine].sort((a, b) => _num(b.plays) - _num(a.plays)).slice(0, 5);
    const maxPlays = sorted.length ? (_num(sorted[0].plays) || 1) : 1;
    topEl.innerHTML = sorted.length ? sorted.map((t, i) => `
        <div class="dash-top-track" onclick="playTrack(${tracks.indexOf(t)})">
          <div style="width:20px;font-size:12px;font-weight:700;color:var(--dim);text-align:center;">${i+1}</div>
          <div style="width:32px;height:32px;border-radius:6px;overflow:hidden;flex-shrink:0;">
            <img loading="lazy" decoding="async" src="${t.img}" alt="${t.title}" style="width:100%;height:100%;object-fit:cover;">
          </div>
          <div style="flex:1;min-width:0;">
            <div style="font-size:12px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${t.title}</div>
            <div class="dash-track-bar-wrap"><div class="dash-track-bar-fill" style="width:${(_num(t.plays) / maxPlays * 100).toFixed(0)}%;"></div></div>
          </div>
          <div style="font-size:11px;color:var(--muted);flex-shrink:0;">${t.plays}</div>
        </div>`).join('') : _empty;
  }

  // Render calendar
  renderDashCalendar();
}

function renderDashCalendar() {
  const grid = document.getElementById('dashCalendar');
  if (!grid) return;
  const now = new Date();
  const year = now.getFullYear();
  const month = now.getMonth();
  const today = now.getDate();
  const firstDay = new Date(year, month, 1).getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const days = ['Su','Mo','Tu','We','Th','Fr','Sa'];
  let html = days.map(d => `<div class="dash-cal-day-hdr">${d}</div>`).join('');
  for (let i = 0; i < firstDay; i++) html += `<div></div>`;
  for (let d = 1; d <= daysInMonth; d++) {
    const isToday = d === today;
    const hasEvent = false;
    html += `<div class="dash-cal-day ${isToday ? 'today' : ''} ${hasEvent ? 'has-event' : ''}" onclick="showToast('${month+1}/${d}, ${hasEvent ? 'Event scheduled!' : 'No events'}')">${d}</div>`;
  }
  grid.innerHTML = html;
}


// ══════════════════════════════════════════════════════════════
//  YAPSMUSIC — PERSISTENT STORAGE (IndexedDB)
//  Audio blobs + track metadata survive page refresh & browser close.
//  Storage lives in the browser — no server needed.
// ══════════════════════════════════════════════════════════════

const DB_NAME = 'YapsMusicDB';
const DB_VERSION = 2;
let _db = null;

function openDB() {
  return new Promise((resolve, reject) => {
    if (_db) return resolve(_db);
    const req = indexedDB.open(DB_NAME, DB_VERSION);
    req.onupgradeneeded = e => {
      const db = e.target.result;
      // Store full track metadata
      if (!db.objectStoreNames.contains('tracks')) {
        db.createObjectStore('tracks', { keyPath: 'id' });
      }
      // Store raw audio blobs (large binary)
      if (!db.objectStoreNames.contains('audio')) {
        db.createObjectStore('audio', { keyPath: 'id' });
      }
      // Store artwork blobs
      if (!db.objectStoreNames.contains('artwork')) {
        db.createObjectStore('artwork', { keyPath: 'id' });
      }
      // Store downloaded-for-offline audio blobs, keyed by the track's
      // audioSrc/audioUrl so it stays stable across array re-ordering.
      if (!db.objectStoreNames.contains('downloads')) {
        db.createObjectStore('downloads', { keyPath: 'id' });
      }
    };
    req.onsuccess = e => { _db = e.target.result; resolve(_db); };
    req.onerror = () => reject(req.error);
  });
}

function dbPut(storeName, record) {
  return openDB().then(db => new Promise((resolve, reject) => {
    const tx = db.transaction(storeName, 'readwrite');
    tx.objectStore(storeName).put(record);
    tx.oncomplete = resolve;
    tx.onerror = () => reject(tx.error);
  }));
}

function dbGet(storeName, id) {
  return openDB().then(db => new Promise((resolve, reject) => {
    const tx = db.transaction(storeName, 'readonly');
    const req = tx.objectStore(storeName).get(id);
    req.onsuccess = () => resolve(req.result || null);
    req.onerror = () => reject(req.error);
  }));
}

function dbGetAll(storeName) {
  return openDB().then(db => new Promise((resolve, reject) => {
    const tx = db.transaction(storeName, 'readonly');
    const req = tx.objectStore(storeName).getAll();
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  }));
}

function dbDelete(storeName, id) {
  return openDB().then(db => new Promise((resolve, reject) => {
    const tx = db.transaction(storeName, 'readwrite');
    tx.objectStore(storeName).delete(id);
    tx.oncomplete = resolve;
    tx.onerror = () => reject(tx.error);
  }));
}

// ══════════════════════════════════════════════════════════════
//  OFFLINE DOWNLOADS — "Download & enjoy" (advertised on splash screen)
//  Caches a track's actual audio file as a blob in IndexedDB so it can
//  play back with no network connection.
// ══════════════════════════════════════════════════════════════
let _downloadedBlobUrls = new Map();   // key (audioSrc/audioUrl) -> object URL
let _downloadedMeta = new Map();       // key -> { title, artist, img, duration, genre, downloadedAt, size }
let _downloadingKeys = new Set();      // keys currently mid-download (shows spinner)
let _downloadProgress = new Map();     // key -> 0-100 percent complete (only set while downloading)

// Only tracks served from a real URL can be "downloaded" — device-uploaded
// tracks (blobUrl) are already local, there's nothing to fetch.
function _downloadKey(t) {
  return (t && (t.audioUrl || t.audioSrc)) || null;
}
function isDownloaded(t) { const k = _downloadKey(t); return !!k && _downloadedBlobUrls.has(k); }
function isDownloading(t) { const k = _downloadKey(t); return !!k && _downloadingKeys.has(k); }

async function loadDownloads() {
  try {
    const saved = await dbGetAll('downloads');
    saved.forEach(rec => {
      if (!rec.blob || !rec.blob.size) { try { dbDelete('downloads', rec.id); } catch (e) {} return; }   // damaged / emptied by the browser: forget it so it can be re-downloaded
      _downloadedBlobUrls.set(rec.id, URL.createObjectURL(rec.blob));
      _downloadedMeta.set(rec.id, { title: rec.title, artist: rec.artist, img: rec.img, duration: rec.duration, genre: rec.genre, downloadedAt: rec.downloadedAt, size: rec.size || rec.blob.size || 0 });
      // Tracks received via local P2P sharing (or any download whose source
      // track is no longer in the catalog) have no matching entry in `tracks`
      // — recreate a lightweight one so it still shows up in Downloads/plays.
      if (!tracks.some(t => _downloadKey(t) === rec.id)) {
        tracks.push({ title: rec.title, artist: rec.artist, img: rec.img || 'icons/icon-192.png?v=4', duration: rec.duration || '', genre: rec.genre || 'Shared', plays: '0', likes: 0, tags: [rec.genre || 'Shared'], audioSrc: rec.id });
      }
    });
    if (saved.length) _requestPersistence();
  } catch (e) {
    console.log('[YAPS] Could not load downloads', e);
  }
  if (typeof _renderHomeDownloads === 'function') _renderHomeDownloads();
}

// Ask the browser not to evict downloads when the phone is low on space (granted automatically to installed apps on most Android phones)
async function _requestPersistence() {
  try {
    if (!navigator.storage || !navigator.storage.persist) return false;
    let ok = navigator.storage.persisted ? await navigator.storage.persisted() : false;
    if (!ok) ok = await navigator.storage.persist();
    window._storagePersisted = !!ok;
    return !!ok;
  } catch (e) { return false; }
}

function _fmtBytes(bytes) {
  if (!bytes) return '0 MB';
  const mb = bytes / (1024 * 1024);
  return mb >= 1 ? mb.toFixed(1) + ' MB' : Math.max(1, Math.round(bytes / 1024)) + ' KB';
}

// Pushes a live progress percentage into the row's download button without
// re-rendering the whole list (cheap enough to call on every chunk).
function _paintDownloadProgress(idx, pct) {
  const el = document.getElementById('dlbtn-' + idx);
  if (!el) return;
  el.style.setProperty('--pct', pct);
  const label = el.querySelector('span');
  if (label) label.textContent = pct;
}

// ── Save a song as a real file in the phone's own storage (Downloads folder) ──
function _songFileName(t, blob) {
  const mime = ((blob && blob.type) || '').toLowerCase();
  const byMime = { 'audio/mpeg':'mp3','audio/mp3':'mp3','audio/mp4':'m4a','audio/x-m4a':'m4a','audio/aac':'aac','audio/wav':'wav','audio/x-wav':'wav','audio/ogg':'ogg','audio/opus':'opus','audio/flac':'flac','audio/webm':'webm' };
  let ext = byMime[mime.split(';')[0]];
  if (!ext) { const m = String(_downloadKey(t) || '').split('?')[0].match(/\.(mp3|m4a|aac|wav|ogg|opus|flac|webm)$/i); ext = m ? m[1].toLowerCase() : 'mp3'; }
  const clean = x => String(x || '').replace(/[\\/:*?"<>|\u0000-\u001f]+/g, ' ').replace(/\s+/g, ' ').trim();
  const name = [clean(t && t.artist), clean(t && t.title)].filter(Boolean).join(' - ') || 'YAPS Music song';
  return name.slice(0, 120) + '.' + ext;
}

// ── Cover art inside the downloaded file ──
// When a song is saved to the phone, write its cover picture + title/artist/genre into the
// MP3's ID3 tag so the cover shows in the phone's music player, gallery, lock screen,
// Bluetooth/car display, and any other app, even outside YAPS Music.
async function _yapsCoverBytes(t) {
  const srcs = [t && t.img, 'icons/icon-192.png?v=4'].filter(Boolean);
  for (const src of srcs) {
    try {
      const r = await fetch(src);
      if (!r.ok) continue;
      const b = await r.blob();
      if (!/^image\//i.test(b.type || '')) continue;
      // Normalise any image type (webp/png/gif) to a square-ish JPEG that every player understands
      try {
        const bmp = await createImageBitmap(b);
        const max = 600, sc = Math.min(1, max / Math.max(bmp.width, bmp.height));
        const w = Math.max(1, Math.round(bmp.width * sc)), h = Math.max(1, Math.round(bmp.height * sc));
        const c = document.createElement('canvas'); c.width = w; c.height = h;
        const g = c.getContext('2d'); g.fillStyle = '#000'; g.fillRect(0, 0, w, h); g.drawImage(bmp, 0, 0, w, h);
        const jb = await new Promise(res => c.toBlob(res, 'image/jpeg', 0.9));
        if (jb) return new Uint8Array(await jb.arrayBuffer());
      } catch (e) {}
      if (/jpe?g/i.test(b.type)) return new Uint8Array(await b.arrayBuffer());
    } catch (e) {}
  }
  return null;
}
function _id3Frame(id, body) {
  const f = new Uint8Array(10 + body.length);
  for (let i = 0; i < 4; i++) f[i] = id.charCodeAt(i);
  const n = body.length;
  f[4] = (n >>> 24) & 255; f[5] = (n >>> 16) & 255; f[6] = (n >>> 8) & 255; f[7] = n & 255;
  f.set(body, 10);
  return f;
}
function _id3Text(id, str) {
  str = String(str || '').trim();
  if (!str) return null;
  const body = new Uint8Array(1 + 2 + str.length * 2);
  body[0] = 1; body[1] = 0xFF; body[2] = 0xFE;                       // UTF-16 with BOM (handles Luganda letters, emoji, etc.)
  for (let i = 0; i < str.length; i++) { const c = str.charCodeAt(i); body[3 + i * 2] = c & 255; body[4 + i * 2] = c >> 8; }
  return _id3Frame(id, body);
}
async function _withCoverArt(blob, t) {
  try {
    if (!blob || !t) return blob;
    const head = new Uint8Array(await blob.slice(0, 10).arrayBuffer());
    const isMp3 = /mp3|mpeg/i.test(blob.type || '') || (head[0] === 0x49 && head[1] === 0x44 && head[2] === 0x33) || (head[0] === 0xFF && (head[1] & 0xE0) === 0xE0);
    if (!isMp3 || /m4a|mp4|aac|ogg|opus|flac|wav|webm/i.test(blob.type || '')) return blob;   // only MP3 uses ID3 tags
    // Drop any old ID3v2 tag so we don't end up with two
    let audioStart = 0;
    if (head[0] === 0x49 && head[1] === 0x44 && head[2] === 0x33) {
      audioStart = 10 + (((head[6] & 127) << 21) | ((head[7] & 127) << 14) | ((head[8] & 127) << 7) | (head[9] & 127)) + ((head[5] & 0x10) ? 10 : 0);
      if (audioStart > blob.size) audioStart = 0;
    }
    const frames = [
      _id3Text('TIT2', t.title), _id3Text('TPE1', t.artist), _id3Text('TPE2', t.artist),
      _id3Text('TALB', t.album || t.title), _id3Text('TCON', t.genre), _id3Text('TCOP', 'YAPS Music')
    ].filter(Boolean);
    const cover = await _yapsCoverBytes(t);
    if (cover) {
      const mime = 'image/jpeg';
      const body = new Uint8Array(1 + mime.length + 1 + 1 + 1 + cover.length);   // enc, mime\0, type, desc\0, data
      let o = 0; body[o++] = 0;
      for (let i = 0; i < mime.length; i++) body[o++] = mime.charCodeAt(i);
      body[o++] = 0; body[o++] = 3; body[o++] = 0;                              // 3 = front cover, empty description
      body.set(cover, o);
      frames.push(_id3Frame('APIC', body));
    }
    if (!frames.length) return blob;
    const size = frames.reduce((a, f) => a + f.length, 0);
    const hdr = new Uint8Array(10);
    hdr.set([0x49, 0x44, 0x33, 3, 0, 0]);
    hdr[6] = (size >> 21) & 127; hdr[7] = (size >> 14) & 127; hdr[8] = (size >> 7) & 127; hdr[9] = size & 127;
    return new Blob([hdr, ...frames, blob.slice(audioStart)], { type: 'audio/mpeg' });
  } catch (e) { console.log('[YAPS] Cover art embed skipped', e); return blob; }
}

function saveSongToDevice(blob, t) {
  try {
    const a = document.createElement('a');
    const url = URL.createObjectURL(blob);
    a.href = url; a.download = _songFileName(t, blob); a.rel = 'noopener'; a.style.display = 'none';
    document.body.appendChild(a); a.click();
    setTimeout(() => { try { a.remove(); URL.revokeObjectURL(url); } catch (e) {} }, 60000);
    return true;
  } catch (e) { console.log('[YAPS] Save to phone failed', e); return false; }
}
// For a song that is already downloaded in the app: put a copy in the phone's storage too
async function saveTrackToPhone(idx) {
  const t = tracks[idx]; const key = _downloadKey(t);
  const url = key && _downloadedBlobUrls.get(key);
  if (!url) { showToast('Download the song first'); return; }
  try {
    const blob = await _withCoverArt(await (await fetch(url)).blob(), t);
    showToast(saveSongToDevice(blob, t) ? '"' + t.title + '" is being saved to your phone\'s Downloads folder' : 'Could not save to your phone, try again');
  } catch (e) { showToast('Could not save to your phone, try again'); }
}

async function downloadTrack(idx) {
  const t = tracks[idx];
  const key = _downloadKey(t);
  if (!key) { showToast('This track can\'t be downloaded'); return; }
  if (window.YAPS_SETTINGS && !YAPS_SETTINGS.canDownloadNow()) { showToast('Downloads are set to Wi-Fi only, connect to Wi-Fi or change it in Settings'); return; }
  if (_downloadedBlobUrls.has(key)) { showToast('Already downloaded'); return; }
  if (_downloadingKeys.has(key)) return;

  _downloadingKeys.add(key);
  _downloadProgress.set(key, 0);
  _bustTrackCache(idx);
  renderLibrary(); if (typeof renderArtistTab === 'function' && document.getElementById('artist-detail-tracks')) renderArtistTab('popular');
  showToast('Downloading "' + t.title + '"…');

  try {
    const res = await fetch(typeof _dsDownloadUrl === 'function' ? _dsDownloadUrl(t, key) : key);
    if (!res.ok) throw new Error('HTTP ' + res.status);

    const total = Number(res.headers.get('content-length')) || 0;
    if (typeof _dsCountDownload === 'function') _dsCountDownload(total);
    if (/text\/html/i.test(res.headers.get('content-type') || '')) throw new Error('NOT_AUDIO');   // an error page, not a song
    try {
      if (total && navigator.storage && navigator.storage.estimate) {
        const est = await navigator.storage.estimate();
        if (est.quota && est.quota - est.usage < total * 1.3) { const q = new Error('Not enough storage'); q.name = 'QuotaExceededError'; throw q; }
      }
    } catch (e) { if (e && e.name === 'QuotaExceededError') throw e; }
    let blob;

    // Stream the response so we can report real progress; fall back to a
    // plain blob() if the browser can't give us a reader (e.g. some polyfills).
    if (res.body && res.body.getReader) {
      const reader = res.body.getReader();
      const chunks = [];
      let received = 0;
      let lastPainted = -1;
      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        chunks.push(value);
        received += value.length;
        if (total > 0) {
          const pct = Math.min(99, Math.floor((received / total) * 100));
          if (pct !== lastPainted) {
            lastPainted = pct;
            _downloadProgress.set(key, pct);
            _paintDownloadProgress(idx, pct);
          }
        }
      }
      blob = new Blob(chunks, { type: res.headers.get('content-type') || 'audio/mpeg' });
    } else {
      blob = await res.blob();
    }

    if (!res.headers.get('content-encoding') && total > 0 && blob.size !== total) throw new Error('INCOMPLETE');   // connection dropped part-way: never save half a song
    if (blob.size < 20 * 1024) throw new Error('NOT_AUDIO');
    await dbPut('downloads', {
      id: key, title: t.title, artist: t.artist, img: t.img,
      duration: t.duration, genre: t.genre, downloadedAt: Date.now(), size: blob.size, blob
    });
    _downloadedBlobUrls.set(key, URL.createObjectURL(blob));
    _downloadedMeta.set(key, { title: t.title, artist: t.artist, img: t.img, duration: t.duration, genre: t.genre, downloadedAt: Date.now(), size: blob.size });
    const _savedToPhone = _yS('saveToPhone', true) && saveSongToDevice(await _withCoverArt(blob, t), t);
    showToast(_savedToPhone ? '"' + t.title + '" saved to your phone\'s Downloads folder (' + _fmtBytes(blob.size) + ')' : '"' + t.title + '" available offline (' + _fmtBytes(blob.size) + ')');
    _requestPersistence();
  } catch (e) {
    console.log('[YAPS] Download failed', e);
    const em = String((e && e.message) || '');
    showToast(e && e.name === 'QuotaExceededError' ? 'Phone storage is full, remove some downloads or free up space'
      : em === 'INCOMPLETE' ? 'Download was interrupted, tap download to try again'
      : em === 'NOT_AUDIO' ? 'This song\'s file could not be found'
      : (navigator.onLine ? 'Download failed, try again' : 'Download failed, you are offline'));
  } finally {
    _downloadingKeys.delete(key);
    _downloadProgress.delete(key);
    _bustTrackCache(idx);
    renderLibrary();
    if (typeof _renderHomeDownloads === 'function') _renderHomeDownloads();
  }
}

// Downloads every liked track that isn't already saved offline, one at a time
// so it doesn't flood the connection or IndexedDB with parallel writes.
async function downloadAllLiked() {
  const idxs = [...tracks.keys()].filter(i =>
    _likedTracks.has(i) && _downloadKey(tracks[i]) && !isDownloaded(tracks[i]) && !isDownloading(tracks[i]));
  if (!idxs.length) { showToast('Nothing new to download'); return; }
  showToast(`Downloading ${idxs.length} liked track${idxs.length > 1 ? 's' : ''}…`);
  for (const i of idxs) { await downloadTrack(i); }
}

// Wipes every offline download (IndexedDB blobs + in-memory state). Used by
// the Downloads tab's "Clear all" button and by the Settings "reset data" action.
async function clearAllDownloads(silent) {
  const keys = [..._downloadedBlobUrls.keys()];
  for (const key of keys) {
    try { await dbDelete('downloads', key); } catch (e) {}
    const url = _downloadedBlobUrls.get(key);
    if (url) URL.revokeObjectURL(url);
  }
  _downloadedBlobUrls.clear();
  _downloadedMeta.clear();
  _downloadProgress.clear();
  Object.keys(_trackRowCache).forEach(k => delete _trackRowCache[k]);
  if (!silent) { showToast('All downloads removed'); renderLibrary(); }
  if (typeof _renderHomeDownloads === 'function') _renderHomeDownloads();
  return keys.length;
}

async function removeDownload(idx) {
  const t = tracks[idx];
  const key = _downloadKey(t);
  if (!key || !_downloadedBlobUrls.has(key)) return;
  await dbDelete('downloads', key);
  URL.revokeObjectURL(_downloadedBlobUrls.get(key));
  _downloadedBlobUrls.delete(key);
  _downloadedMeta.delete(key);
  showToast('Removed download');
  _bustTrackCache(idx);
  renderLibrary();
  if (typeof _renderHomeDownloads === 'function') _renderHomeDownloads();
}

// Load all saved tracks from IndexedDB into the tracks array on startup
async function loadSavedTracks() {
  try {
    const saved = await dbGetAll('tracks');
    const audioRecs = await dbGetAll('audio');
    const artRecs = await dbGetAll('artwork');

    const audioMap = {};
    audioRecs.forEach(r => { audioMap[r.id] = URL.createObjectURL(r.blob); });

    const artMap = {};
    artRecs.forEach(r => { artMap[r.id] = URL.createObjectURL(r.blob); });

    saved.sort((a, b) => b.savedAt - a.savedAt); // newest first
    saved.forEach(t => {
      // Don't add if already exists (e.g. page re-render)
      if (tracks.some(x => x.id === t.id)) return;
      tracks.unshift({
        ...t,
        blobUrl: audioMap[t.id] || null,
        img: artMap[t.id] || t.img,
        _saved: true,
      });
    });

    if (saved.length > 0) {
      try { _libReapply(); } catch (e) {}   // songs were added at the front: rebuild saved positions from song keys
      _homeRendered = false; // bust cache so saved tracks appear
      if (typeof renderHome === 'function') renderHome();
      console.log(`[YAPS] Loaded ${saved.length} saved track(s) from storage`);
      if (typeof window._nrpOnData === 'function') window._nrpOnData();
    }
  } catch (err) {
    console.warn('[YAPS] Could not load saved tracks:', err);
  }
}

// Delete a saved track permanently
async function deleteSavedTrack(trackId) {
  try {
    await dbDelete('tracks', trackId);
    await dbDelete('audio', trackId);
    await dbDelete('artwork', trackId);
    const idx = tracks.findIndex(t => t.id === trackId);
    if (idx >= 0) { _prepareTrackShift(); tracks.splice(idx, 1); _remapTrackIndices(i => i === idx ? -1 : (i > idx ? i - 1 : i)); }
    if (typeof renderHome === 'function') renderHome();
    showToast('Track deleted permanently');
  } catch (err) {
    showToast('Could not delete track');
  }
}

// ── Upload state ──
let _uploadedAudioFile = null;
let _uploadedArtworkFile = null;

document.getElementById('audioFileInput').addEventListener('change', function() {
  if (this.files[0]) handleAudioFileSelected(this.files[0]);
});
document.getElementById('artworkFileInput').addEventListener('change', function() {
  if (this.files[0]) handleArtworkSelected(this.files[0]);
});

function handleAudioDrop(e) {
  e.preventDefault();
  document.getElementById('uploadZone').classList.remove('drag-over');
  const file = e.dataTransfer.files[0];
  if (file && file.type.startsWith('audio/')) {
    handleAudioFileSelected(file);
  } else {
    showToast('Please drop an audio file (MP3, WAV, FLAC...)');
  }
}

function handleAudioFileSelected(file) {
  _uploadedAudioFile = file;
  const sizeMB = (file.size / 1024 / 1024).toFixed(1);
  document.getElementById('uploadFileName').textContent = file.name;
  document.getElementById('uploadFileSize').textContent = `${sizeMB} MB · ${file.type.replace('audio/','')}`;
  document.getElementById('uploadSelectedFile').classList.add('show');
  const titleGuess = file.name.replace(/\.[^.]+$/, '').replace(/[-_]/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
  const titleInput = document.getElementById('uploadTitle');
  if (titleInput && !titleInput.value) titleInput.value = titleGuess;
  showUploadForm();
  showToast('Audio file selected, fill in the details');
}

function handleArtworkSelected(file) {
  _uploadedArtworkFile = file;
  const url = URL.createObjectURL(file);
  const zone = document.getElementById('artworkUploadZone');
  zone.style.backgroundImage = `url('${url}')`;
  zone.style.backgroundSize = 'cover';
  zone.style.backgroundPosition = 'center';
  document.getElementById('artworkUploadLabel').textContent = '' + file.name;
  showToast('Artwork selected');
}

function clearUploadFile() {
  _uploadedAudioFile = null;
  _uploadedArtworkFile = null;
  document.getElementById('uploadSelectedFile').classList.remove('show');
  document.getElementById('uploadZone').style.display = '';
  document.getElementById('uploadForm').classList.remove('visible');
  document.getElementById('audioFileInput').value = '';
  const zone = document.getElementById('artworkUploadZone');
  zone.style.backgroundImage = '';
  document.getElementById('artworkUploadLabel').textContent = 'Add a cover image (recommended)';
  document.getElementById('uploadTitle').value = '';
  const artistInput = document.getElementById('uploadArtist'); if (artistInput) artistInput.value = '';
  const albumInput = document.getElementById('uploadAlbum'); if (albumInput) albumInput.value = '';
  const descInput = document.getElementById('uploadDescription'); if (descInput) descInput.value = '';
  const tagsInput = document.getElementById('uploadTags'); if (tagsInput) tagsInput.value = '';
  const copyrightBox = document.getElementById('uploadCopyrightConfirm'); if (copyrightBox) copyrightBox.checked = false;
  _uploadExplicit = false;
  _setTrending(false);
  goToUploadStep(1);
}

// ── UPLOAD WIZARD (Step 1: Upload · Step 2: Details · Step 3: Artwork & Rights) ──
let _uploadTrending = false;
function _setTrending(val) {
  _uploadTrending = !!val;
  const yes = document.getElementById('uploadTrendingYes');
  const no = document.getElementById('uploadTrendingNo');
  if (yes) yes.classList.toggle('selected', !!val);
  if (no) no.classList.toggle('selected', !val);
}
let _uploadExplicit = false;
function _setExplicit(val) {
  _uploadExplicit = val;
  const yes = document.getElementById('uploadExplicitYes');
  const no = document.getElementById('uploadExplicitNo');
  if (yes) yes.classList.toggle('selected', val);
  if (no) no.classList.toggle('selected', !val);
}

function goToUploadStep(n) {
  const step1 = document.getElementById('uploadStep1');
  const step2 = document.getElementById('uploadStep2');
  const step3 = document.getElementById('uploadStep3');
  if (!step2 || !step3) return;
  if (n === 2 && !_uploadedAudioFile) { showToast('Please select an audio or video file first'); return; }
  if (step1) step1.style.display = (n === 1) ? '' : 'none';
  step2.style.display = (n === 2) ? '' : 'none';
  step3.style.display = (n === 3) ? '' : 'none';
  [1,2,3].forEach(i => {
    const pill = document.getElementById('uploadStepPill' + i);
    if (!pill) return;
    const dot = pill.querySelector('span');
    const active = i <= n;
    pill.style.color = active ? 'var(--accent)' : 'var(--dim)';
    if (dot) { dot.style.background = active ? 'var(--accent)' : 'var(--border)'; dot.style.color = active ? '#fff' : 'var(--dim)'; }
  });
}

async function _submitUploadInner() {
  const titleInput = document.getElementById('uploadTitle');
  const genreInput = document.getElementById('uploadGenre');
  const artistInput = document.getElementById('uploadArtist');
  const copyrightBox = document.getElementById('uploadCopyrightConfirm');
  const title = titleInput ? titleInput.value.trim() : '';
  const genre = genreInput ? genreInput.value : 'Afrobeats';
  const customArtist = artistInput ? artistInput.value.trim() : '';

  if (!_uploadedAudioFile) { showToast('Please select an audio file first'); goToUploadStep(1); return; }
  if (!title) { showToast('Please enter a track title'); goToUploadStep(2); if (titleInput) titleInput.focus(); return; }
  if (copyrightBox && !copyrightBox.checked) { showToast('Please confirm you own the rights to this upload'); copyrightBox.focus(); return; }
  if (_uploadedAudioFile.size > _MAX_AUDIO) { showToast('Audio file is too large (max 50 MB). Export a smaller MP3.'); goToUploadStep(1); return; }
  if (_uploadedArtworkFile && (!_checkImageFile(_uploadedArtworkFile) || _uploadedArtworkFile.size > _MAX_ART)) { if (_uploadedArtworkFile.size > _MAX_ART) showToast('Artwork is too large (max 10 MB)'); goToUploadStep(3); return; }

  if (!_uploadedArtworkFile && !confirm('This song has no cover image. Listeners find songs faster when they can see a cover.\n\nOK = upload without a cover\nCancel = go back and add one')) { goToUploadStep(3); return; }

  const ownerUpload = _isOwner();
  // Everyone is asked "Is this song trending?". Owner uploads go straight into Trending Now;
  // other artists send a request (TrendingRequest tag) that the owner confirms in the review queue.
  const markTrending = ownerUpload && _uploadTrending;
  const requestTrending = !ownerUpload && _uploadTrending;
  const baseTags = ['Uganda', genre];
  if (markTrending) baseTags.push('Trending');
  else if (requestTrending) baseTags.push('TrendingRequest');

  const progressWrap = document.getElementById('uploadProgressWrap');
  const progressFill = document.getElementById('uploadProgressFill');
  const progressLabel = document.getElementById('uploadProgressLabel');
  progressWrap.classList.add('show'); _uploadClearError();

  // ── Determine upload mode ──
  // Remote (cloud) upload requires a configured Supabase client AND a logged-in user.
  // Otherwise we fall back to the local IndexedDB path below.
  // Also needs the backend: it saves the song row. Without it the file would reach Storage
  // but never appear in the app, so keep it on this device instead.
  const isRemote = !!(sb && _demoUser);
  window._lastUploadPending = false;

  let pct = 0;
  const fakeProgress = isRemote ? 0 : setInterval(() => {
    pct = Math.min(pct + (isRemote ? 3 : 12) + Math.random() * 4, isRemote ? 80 : 90);
    progressFill.style.width = pct + '%';
    progressLabel.textContent = isRemote
      ? `Uploading to cloud... ${Math.floor(pct)}%`
      : `Saving to device... ${Math.floor(pct)}%`;
  }, 180);

  try {
    const blobUrl = URL.createObjectURL(_uploadedAudioFile);

    // Get real audio duration
    const duration = await new Promise(res => {
      const tmp = new Audio(blobUrl);
      tmp.addEventListener('loadedmetadata', () => {
        const d = Math.floor(tmp.duration);
        res(isNaN(d) ? '0:00' : `${Math.floor(d/60)}:${String(d%60).padStart(2,'0')}`);
      });
      tmp.addEventListener('error', () => res('0:00'));
      setTimeout(() => res('0:00'), 4000);
    });

    let audioUrl  = null;   // R2 public URL (remote mode)
    let artworkUrl = _uploadedArtworkFile
      ? URL.createObjectURL(_uploadedArtworkFile)
      : (window._yapsCover ? window._yapsCover(title, customArtist || (_demoUser && _demoUser.name) || '') : '');
    const _hasArt = !!_uploadedArtworkFile;   // no cover -> store nothing; the app draws an initials cover for it

    if (isRemote) {
      const artistName = customArtist || (ownerUpload ? 'YAPS Official' : (_demoUser.name || 'Yaps Artist'));
      const safeName = (n) => (n || 'file').replace(/[^a-zA-Z0-9._-]/g, '_');

      // 1) Upload the audio file to Storage
      progressLabel.textContent = 'Uploading audio...';
      const audioPath = `${_demoUser.id}/${Date.now()}_${safeName(_uploadedAudioFile.name)}`;
      const _pp = (base, span, lbl) => p => { progressFill.style.width = (base + p * span / 100) + '%'; progressLabel.textContent = lbl + ' ' + Math.floor(p) + '%'; };
      audioUrl = await _apiUpload('audio', _uploadedAudioFile, { onProgress: _pp(0, _uploadedArtworkFile ? 75 : 92, 'Uploading audio') });

      // 2) Upload artwork if provided
      if (_uploadedArtworkFile) {
        progressLabel.textContent = 'Uploading artwork...';
        const artPath = `${_demoUser.id}/${Date.now()}_${safeName(_uploadedArtworkFile.name)}`;
        artworkUrl = await _apiUpload('artwork', _uploadedArtworkFile, { onProgress: _pp(75, 17, 'Uploading artwork') });
      }

      // 3) Insert the track row — ADJUST COLUMN NAMES to match your actual `tracks` table
      progressLabel.textContent = 'Saving track to database...';
      const savedTrack = await api('/api/tracks', { method: 'POST', body: {
        title: String(title).slice(0, 150), artist: String(artistName).slice(0, 100),
        genre: String(genre).slice(0, 40), duration: String(duration).slice(0, 10), explicit: _uploadExplicit,
        tags: [...baseTags].slice(0, 20).map(String), audio_url: audioUrl, artwork_url: _hasArt ? artworkUrl : null,
      } });

      clearInterval(fakeProgress);
      progressFill.style.width = '100%';
      const _live = !savedTrack.status || savedTrack.status === 'approved';
      window._lastUploadPending = !_live;
      progressLabel.textContent = _live ? 'Uploaded to cloud!' : 'Submitted for review!';

      const trackId = savedTrack.id;
      const newTrack = {
        id: trackId, title, artist: artistName, img: artworkUrl,
        genre, plays: '0', likes: '0', duration,
        tags: [...baseTags], audioUrl, _remote: true, savedAt: Date.now(),
      };
      if (!_live) { /* waits for approval */ } else if (markTrending) { _prepareTrackShift(); tracks.unshift(newTrack); _remapTrackIndices(i => i + 1); } else tracks.push(newTrack);
      // Also cache locally so it plays instantly, even before the shared stream re-syncs
      if (_live) await dbPut('tracks', { id: String(trackId), title, artist: artistName, img: artworkUrl, genre, plays: '0', likes: '0', duration, tags: [...baseTags], savedAt: Date.now() });
      _yapsOptimizeInBackground(trackId, _uploadedAudioFile, newTrack);   // makes the Data Saver / Normal copies after the song is already live

    } else {
      // ── LOCAL PATH: IndexedDB (offline / not logged in) ──
      const trackId = 'upl_' + Date.now();
      const artistName = customArtist || (ownerUpload ? 'YAPS Official' : 'Yaps Bula');
      const newTrack = {
        id: trackId, title, artist: artistName, img: artworkUrl,
        genre, plays: '0', likes: '0', duration,
        tags: [...baseTags], blobUrl, savedAt: Date.now(), _saved: true,
      };

      await dbPut('tracks', {
        id: trackId, title, artist: artistName,
        img: 'https://images.unsplash.com/photo-1493225457124-a3eb161ffa5f?w=400&q=70&auto=format',
        genre, plays: '0', likes: '0', duration, tags: [...baseTags], savedAt: Date.now(),
      });
      await dbPut('audio', { id: trackId, blob: _uploadedAudioFile });
      if (_uploadedArtworkFile) {
        await dbPut('artwork', { id: trackId, blob: _uploadedArtworkFile });
        newTrack.img = artworkUrl;
      }

      clearInterval(fakeProgress);
      progressFill.style.width = '100%';
      progressLabel.textContent = 'Saved to device!';
      _prepareTrackShift(); tracks.unshift(newTrack); _remapTrackIndices(i => i + 1);

    }

    setTimeout(() => {
      progressWrap.classList.remove('show');
      progressFill.style.width = '0%';
      clearUploadFile();
      if (typeof renderHome === 'function') renderHome();
      if (false) showToast('');
      else showToast(markTrending
        ? `"${title}" is live and featured in Trending Now!`
        : requestTrending && window._lastUploadPending
        ? `"${title}" submitted, your trending request is reviewed with it`
        : isRemote
          ? (window._lastUploadPending ? `"${title}" submitted, it goes live once approved` : `"${title}" is live, everyone can hear it!`)
          : `"${title}" saved locally, plays even after refresh!`);
      if (window._lastUploadPending) { try { openMyReleases(); } catch (e) {} } else { playTrack(0); setTimeout(() => navigate('home'), 1200); }
    }, 900);

    // Tell the uploader's followers about the new song.
    if (isRemote && !window._lastUploadPending) notifyFollowersOfRelease(title, _hasArt ? artworkUrl : "");
    // Let every listener know when the official account drops something new.
    if (ownerUpload) {
      sendNotification({ toUserId: null, type: 'release', trackTitle: title, trackImg: _hasArt ? artworkUrl : "", body: `New release: "${title}"` });
    }

  } catch (err) {
    clearInterval(fakeProgress);
    progressWrap.classList.remove('show');
    console.error('[YAPS] Upload failed:', err);
    showToast(_uploadErrText(err)); _uploadShowError(err);
  }
}


