// ── UPDATED SHOW UPLOAD FORM ──
function showUploadForm() {
  const reveal = () => {
    document.getElementById('uploadZone').style.display = 'none';
    document.getElementById('uploadForm').classList.add('visible');
    const trendHint = document.getElementById('uploadTrendingHint');
    if (trendHint) trendHint.textContent = _isOwner() ? 'Yes puts this song straight into Trending Now.' : 'Trending songs are shown in Trending Now. Your answer is confirmed during review.';
    goToUploadStep(2);
  };
  // Owner (unlocked via the 5-tap logo + PIN) can upload straight away —
  // no need to create/sign into a listener account first.
  if (_isOwner()) { reveal(); return; }
  requireAuth(reveal);
}



