// ── GUEST GUARD — ask people without an account to create one ──
// One bottom sheet, used both when a guest taps an account-only action (like, upload, playlist…)
// and as a friendly welcome prompt when a guest opens the app (see _guestWelcomePrompt).
function _showAuthSheet(opts) {
  opts = opts || {};
  const old = document.getElementById('authNudgeModal'); if (old) old.remove();
  const el = document.createElement('div');
  el.id = 'authNudgeModal';
  el.style.cssText = 'position:fixed;inset:0;z-index:10060;display:flex;align-items:flex-end;justify-content:center;background:rgba(0,0,0,0.6);backdrop-filter:blur(4px);';
  el.innerHTML =
    '<div role="dialog" aria-modal="true" aria-labelledby="anTitle" style="background:var(--card);border-radius:24px 24px 0 0;padding:28px 24px 30px;width:100%;max-width:480px;text-align:center;border-top:1.5px solid var(--border);">' +
      '<div style="font-size:36px;margin-bottom:12px;"><i class="fas fa-user-circle" style="color:var(--accent)"></i></div>' +
      '<div id="anTitle" style="font-size:18px;font-weight:800;color:var(--text);margin-bottom:8px;">' + (opts.title || 'Create a free account') + '</div>' +
      '<div style="font-size:14px;color:var(--muted);margin-bottom:24px;line-height:1.6;">' + (opts.text || 'Like songs, save playlists and upload your music.<br>It\u2019s free and takes 30 seconds.') + '</div>' +
      '<button type="button" id="anCreate" style="width:100%;padding:14px;background:var(--accent);color:#fff;border:none;border-radius:12px;font-size:15px;font-weight:800;cursor:pointer;font-family:\'Archivo\',sans-serif;margin-bottom:10px;">Create Free Account</button>' +
      '<button type="button" id="anSignin" style="width:100%;padding:12px;background:transparent;color:var(--accent);border:1.5px solid var(--accent);border-radius:12px;font-size:14px;font-weight:700;cursor:pointer;font-family:\'Archivo\',sans-serif;margin-bottom:10px;">I already have an account</button>' +
      '<button type="button" id="anLater" style="width:100%;padding:10px;background:transparent;color:var(--muted);border:none;font-size:14px;font-weight:600;cursor:pointer;font-family:\'Archivo\',sans-serif;">Maybe later</button>' +
    '</div>';
  const close = () => { el.remove(); };
  const go = (side) => { close(); goAuth(side); };
  el.querySelector('#anCreate').onclick = () => go('signup');
  el.querySelector('#anSignin').onclick = () => go('signin');
  el.querySelector('#anLater').onclick = () => { close(); if (opts.onLater) opts.onLater(); };
  el.addEventListener('click', e => { if (e.target === el) { close(); if (opts.onLater) opts.onLater(); } });
  document.body.appendChild(el);
}
function requireAuth(action) {
  if (_demoUser) { action(); return; }
  _showAuthSheet();
}

// Welcome prompt for guests: when the app opens with no signed-in account, offer to create one.
// Shown once per visit; "Maybe later" snoozes it for 3 days. Waits until no other dialog is open.
function _guestWelcomePrompt() {
  if (!sb || _demoUser) return;
  try { if (sessionStorage.getItem('yaps_guest_prompted') === '1') return; } catch (e) {}
  let snoozeUntil = 0;
  try { snoozeUntil = parseInt(localStorage.getItem('yaps_guest_snooze') || '0', 10) || 0; } catch (e) {}
  if (Date.now() < snoozeUntil) return;
  let tries = 0;
  const t = setInterval(() => {
    if (_demoUser || ++tries > 40) { clearInterval(t); return; }          // signed in meanwhile, or gave up
    const welcome = document.getElementById('welcomeThemeModal');
    if (document.querySelector('.modal-overlay.open') || document.getElementById('authNudgeModal') ||
        (welcome && welcome.classList.contains('open'))) return;          // something else is on screen: wait
    clearInterval(t);
    try { sessionStorage.setItem('yaps_guest_prompted', '1'); } catch (e) {}
    _showAuthSheet({
      title: 'Welcome to YAPS Music',
      text: 'Create a free account to like songs, build playlists, follow artists and keep your library on every device.',
      onLater: () => { try { localStorage.setItem('yaps_guest_snooze', String(Date.now() + 3 * 864e5)); } catch (e) {} }
    });
  }, 1500);
}

// ── LIKE / REPOST TRACK ──
function toggleLikeTrack(idx) {
  if (!_demoUser) { requireAuth(() => toggleLikeTrack(idx)); return; }
  if (_likedTracks.has(idx)) { _likedTracks.delete(idx); showToast('Removed from likes'); }
  else {
    _likedTracks.add(idx); showToast('Added to likes');
    // Settings → Downloads: auto-download liked songs (respects Wi-Fi only / offline)
    if (_yS('autoDlLiked', false) && window.YAPS_SETTINGS && YAPS_SETTINGS.canDownloadNow() && navigator.onLine && typeof downloadTrack === 'function') setTimeout(() => downloadTrack(idx), 400);
  }
  _persistSave();
  if (typeof renderPersonalizedHome === 'function') renderPersonalizedHome();
  // update heart icon in player bar if this is current track
  const heart = document.getElementById('pbHeart');
  if (heart && idx === currentTrack) heart.classList.toggle('liked', _likedTracks.has(idx));
  const npHeart = document.getElementById('npLikeBtn');
  if (npHeart && idx === currentTrack) npHeart.classList.toggle('liked', _likedTracks.has(idx));
  const t = tracks[idx];
  if (t && _likedTracks.has(idx)) notifyTrackOwner('like', t);
  // NOTE: likes are only persisted locally (localStorage) right now, keyed by array
  // index `idx`, not by a stable track id. Syncing likes to Supabase so they show up
  // for other users / other devices needs a `likes` table keyed on the real track id
  // (t.id for remote tracks) rather than this array position — worth doing as its own
  // task since array indices aren't stable across sessions once tracks are reordered.
}

function toggleRepost(idx, btn) {
  if (_repostedTracks.has(idx)) { _repostedTracks.delete(idx); btn.style.color = ''; showToast('Repost removed'); }
  else { _repostedTracks.add(idx); btn.style.color = 'var(--accent)'; showToast('Reposted!'); notifyTrackOwner('repost', tracks[idx]); }
  _persistSave();
}

// ── NATIVE SHARE ──
// trackId is optional so existing calls (e.g. video share) still work unchanged;
// when it's provided the shared link deep-links straight to that song.
/* Share card: a 1080x1350 picture (cover, title, artist, "Listen on YAPS Music") that looks good in WhatsApp status / Instagram / TikTok.
   If the cover can't be read (blocked by CORS or offline) the card still renders with a gradient + initials. */
function _yapsLoadImg(src, ms) {
  return new Promise(res => {
    if (!src) return res(null);
    const im = new Image(); im.crossOrigin = 'anonymous';
    const t = setTimeout(() => res(null), ms || 2500);
    im.onload = () => { clearTimeout(t); res(im); }; im.onerror = () => { clearTimeout(t); res(null); };
    im.src = src;
  });
}
async function _yapsShareCardFile(track, title, artist) {
  const W = 1080, H = 1350, c = document.createElement('canvas'); c.width = W; c.height = H;
  const g = c.getContext('2d');
  const bg = g.createLinearGradient(0, 0, W, H); bg.addColorStop(0, '#0b1f2e'); bg.addColorStop(.5, '#2a1260'); bg.addColorStop(1, '#6b1b8f');
  g.fillStyle = bg; g.fillRect(0, 0, W, H);
  const img = await _yapsLoadImg(track && track.img);
  if (img) { g.save(); g.globalAlpha = .28; g.filter = 'blur(40px)'; g.drawImage(img, -100, -100, W + 200, H + 200); g.restore(); g.filter = 'none'; }
  const S = 760, x = (W - S) / 2, y = 150;
  const rr = (px, py, w, h, r) => { g.beginPath(); g.moveTo(px + r, py); g.arcTo(px + w, py, px + w, py + h, r); g.arcTo(px + w, py + h, px, py + h, r); g.arcTo(px, py + h, px, py, r); g.arcTo(px, py, px + w, py, r); g.closePath(); };
  g.save(); g.shadowColor = 'rgba(0,0,0,.55)'; g.shadowBlur = 60; g.shadowOffsetY = 24; rr(x, y, S, S, 40); g.fillStyle = '#111'; g.fill(); g.restore();
  g.save(); rr(x, y, S, S, 40); g.clip();
  if (img) g.drawImage(img, x, y, S, S);
  else {
    const cg = g.createLinearGradient(x, y, x + S, y + S); cg.addColorStop(0, '#0ea66b'); cg.addColorStop(.5, '#7c3aed'); cg.addColorStop(1, '#c026d3');
    g.fillStyle = cg; g.fillRect(x, y, S, S); g.fillStyle = 'rgba(255,255,255,.92)'; g.font = '800 300px Arial,sans-serif'; g.textAlign = 'center';
    g.fillText((String(title || '?').trim().charAt(0) || '?').toUpperCase(), W / 2, y + S / 2 + 105);
  }
  g.restore();
  g.textAlign = 'center'; g.fillStyle = '#fff';
  const fit = (txt, size, wt, maxW) => { let f = size; do { g.font = wt + ' ' + f + 'px Arial,sans-serif'; f -= 2; } while (g.measureText(txt).width > maxW && f > 24); };
  fit(String(title || ''), 64, '800', W - 140); g.fillText(String(title || ''), W / 2, y + S + 100);
  g.fillStyle = 'rgba(255,255,255,.78)'; fit(String(artist || ''), 42, '600', W - 160); g.fillText(String(artist || ''), W / 2, y + S + 160);
  const pill = 'Listen on YAPS Music', pw = 520, ph = 84, px = (W - pw) / 2, py = H - 170;
  const pg = g.createLinearGradient(px, 0, px + pw, 0); pg.addColorStop(0, '#0ea66b'); pg.addColorStop(.5, '#7c3aed'); pg.addColorStop(1, '#c026d3');
  rr(px, py, pw, ph, 42); g.fillStyle = pg; g.fill(); g.fillStyle = '#fff'; g.font = '800 34px Arial,sans-serif'; g.fillText(pill, W / 2, py + 54);
  g.fillStyle = 'rgba(255,255,255,.55)'; g.font = '600 26px Arial,sans-serif'; g.fillText(location.host || 'yapsmusic.app', W / 2, H - 45);
  const blob = await new Promise(res => { try { c.toBlob(res, 'image/png'); } catch (e) { res(null); } });
  if (!blob) return null;
  return new File([blob], String(title || 'song').replace(/[^\w-]+/g, '_').slice(0, 40) + '-yaps.png', { type: 'image/png' });
}

function nativeShare(title, artist, trackId) {
  const shareUrl = (trackId !== undefined && trackId !== null)
    ? `${location.origin}${location.pathname}?track=${encodeURIComponent(trackId)}`
    : location.href;

  // Copy fallback: navigator.clipboard is undefined on non-HTTPS pages and some in-app browsers.
  const copyFallback = () => {
    try {
      if (navigator.clipboard && navigator.clipboard.writeText) {
        return navigator.clipboard.writeText(shareUrl).then(() => showToast('Link copied!'), () => showToast(shareUrl));
      }
    } catch (e) {}
    showToast(shareUrl);   // last resort: show the link so it can be copied by hand
  };
  const plain = () => {
    if (navigator.share) {
      navigator.share({ title: `${title} by ${artist}`, text: `Listen to ${title} by ${artist} on YAPSMusic`, url: shareUrl })
        .catch(err => { if (!err || err.name !== 'AbortError') copyFallback(); });
    } else {
      copyFallback();
    }
  };

  // Preferred: picture card + link (needs file sharing support, e.g. Android Chrome). Anything else falls back to the plain link share.
  if (navigator.share && navigator.canShare && trackId !== undefined && trackId !== null) {
    const track = (typeof tracks !== 'undefined' ? tracks : []).find(t => String(t.id) === String(trackId));
    _yapsShareCardFile(track, title, artist).then(file => {
      if (!file || !navigator.canShare({ files: [file] })) return plain();
      return navigator.share({ files: [file], title: `${title} by ${artist}`, text: `Listen to ${title} by ${artist} on YAPSMusic\n${shareUrl}` })
        .catch(err => { if (!err || err.name !== 'AbortError') plain(); });
    }).catch(plain);
    return;
  }
  plain();
}

// ── DEEP LINK: open + play the exact song from a shared ?track=<id> URL ──
function _playFromDeepLink() {
  const params = new URLSearchParams(location.search);
  const trackParam = params.get('track');
  if (!trackParam) return;

  // Match by real track id (works for both numeric ids and Supabase upload ids)
  const idx = tracks.findIndex(t => String(t.id) === String(trackParam));

  if (idx === -1) {
    // Track not found in what's currently loaded locally (e.g. it's a track uploaded
    // by someone else and this device hasn't synced it) — tell the user instead of
    // silently opening to the home screen.
    showToast("Couldn't find that song, it may have been removed");
    return;
  }

  playTrack(idx);
  openNowPlayingScreen();

  // Clean the URL so refreshing/sharing again from here doesn't re-trigger,
  // but keep the entry in browser history.
  history.replaceState(null, '', location.pathname);
}

// Run after the app's own DOMContentLoaded init (tracks[] and playTrack are
// defined by then), and also immediately if the doc has already loaded.
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', _playFromDeepLink);
} else {
  _playFromDeepLink();
}

// ── ADD TO PLAYLIST MODAL ──
let _addToPlaylistTarget = -1;
function showAddToPlaylist(trackIdx) {
  requireAuth(() => {
    _addToPlaylistTarget = trackIdx;
    const modal = document.getElementById('playlistPickerModal');
    if (!modal) return;
    renderPlaylistPicker();
    modal.classList.add('open');
  });
}

function renderPlaylistPicker() {
  const list = document.getElementById('playlistPickerList');
  if (!list) return;
  if (_userPlaylists.length === 0) {
    list.innerHTML = `<div style="padding:24px;text-align:center;color:var(--dim);font-size:13px;">No playlists yet. Create one below!</div>`;
    return;
  }
  const t = tracks[_addToPlaylistTarget];
  list.innerHTML = _userPlaylists.map(pl => {
    const has = pl.trackIndices.includes(_addToPlaylistTarget);
    return `<div class="notif-item" style="cursor:pointer;padding:12px 20px;" onclick="addTrackToPlaylistById(${pl.id})">
      <div style="font-size:20px;margin-right:12px;"></div>
      <div style="flex:1;"><div style="font-size:13px;font-weight:600;">${pl.name}</div><div style="font-size:12px;color:var(--muted);">${pl.trackIndices.length} tracks</div></div>
      ${has ? `<span style="color:var(--accent);font-size:12px;font-weight:700;">Added</span>` : `<span style="color:var(--muted);font-size:12px;">Add</span>`}
    </div>`;
  }).join('');
}

function addTrackToPlaylistById(plId) {
  const pl = _userPlaylists.find(p => p.id === plId);
  if (!pl) return;
  if (pl.trackIndices.includes(_addToPlaylistTarget)) { showToast('Already in ' + pl.name); return; }
  pl.trackIndices.push(_addToPlaylistTarget);
  _persistSave();
  showToast(`Added to "${pl.name}"`);
  renderPlaylistPicker();
}

function createNewPlaylistFromPicker() {
  const input = document.getElementById('newPlaylistNameInput');
  const name = input ? input.value.trim() : '';
  if (!name) { showToast('Enter a playlist name first'); return; }
  const pl = { id: Date.now(), name, trackIndices: _addToPlaylistTarget >= 0 ? [_addToPlaylistTarget] : [] };
  _userPlaylists.push(pl);
  _persistSave();
  input.value = '';
  if (_addToPlaylistTarget >= 0 && tracks[_addToPlaylistTarget]) {
    showToast(`Created "${name}" and added ${tracks[_addToPlaylistTarget].title}`);
  } else {
    showToast(`Created "${name}"`);
  }
  renderPlaylistPicker();
}

function closePlaylistPicker() {
  const modal = document.getElementById('playlistPickerModal');
  if (modal) modal.classList.remove('open');
  _addToPlaylistTarget = -1;
}

// ── CREATE PLAYLIST (from library new button) ──
function openCreatePlaylist() {
  _addToPlaylistTarget = -1;
  const modal = document.getElementById('playlistPickerModal');
  if (modal) { renderPlaylistPicker(); modal.classList.add('open'); }
}

