// ── SMART FILTER (home genre chips) ──
function setFilter(el, name) {
  if (el) {
    document.querySelectorAll('.stream-filters .filter-chip').forEach(c => c.classList.remove('active'));
    el.classList.add('active');
  }
  const trow = document.getElementById('trending-row');
  if (!trow) return;
  if (name === 'All') {
    const allPool = isGospelWeekend() ? tracks.slice(0,8) : curatedTrending();
    trow.innerHTML = allPool.map((t) => _trendingCardHTML(t, tracks.indexOf(t))).join('');
    return;
  }
  const filtered = tracks.filter(t => t.genre.toLowerCase().includes(name.toLowerCase()) || t.tags.some(tag => tag.toLowerCase().includes(name.toLowerCase())));
  trow.innerHTML = filtered.length ? filtered.slice(0,12).map((t) => _trendingCardHTML(t, tracks.indexOf(t))).join('') :
    `<div style="padding:32px;text-align:center;color:var(--dim);width:100%;">No ${name} tracks found</div>`;
}

function _trendingCardHTML(t, i) {
  return `
    <div class="track-card" onclick="playTrack(${i})">
      <div class="tc-art">
        <img src="${t.img}" alt="${t.title}" loading="lazy" style="width:100%;height:100%;object-fit:cover;">
        <div class="tc-waveform">${waveformBars(22)}</div>
        <div class="tc-play"><i class="fas fa-play"></i></div>
      </div>
      <div class="tc-title">${t.title}</div>
      <div class="tc-artist">${t.artist}</div>
      <div class="tc-meta">
        <span><i class="fas fa-play"></i> ${t.plays}</span>
        <span><i class="fas fa-heart"></i> ${t.likes}</span>
      </div>
    </div>
  `;
}

// ── INIT ──
// Real YouTube videos — each derived from a track already in the `tracks`
// catalog above (single source of truth: track.youtubeId). Only songs
// actually tagged "Trending" in the catalog are shown here, so this grid
// stays current rather than mixing in decade-old classics. Thumbnails are
// pulled directly from YouTube's own CDN, so there's nothing extra to host.
const _trendingVideoTrackIds = [37, 1, 53, 2, 8, 34, 166, 21, 5, 6, 12, 23, 55, 83, 4, 13, 7, 161, 14, 162];
let _trendingVideos = _trendingVideoTrackIds.map(id => {
  const t = tracks.find(tr => tr.id === id);
  if (!t || !t.youtubeId) return null;
  return { trackId: t.id, title: t.title, artist: t.artist, youtubeId: t.youtubeId, views: t.plays, img: t.img };
}).filter(Boolean);
function _ytThumb(id) { return `https://img.youtube.com/vi/${id}/hqdefault.jpg`; }

// ══════════════════════════════════════════════════════════
//  VIDEOS BROWSE PAGE (YouTube-style) — hero, categories,
//  trending grid, new releases list. Built on top of the
//  existing `tracks` catalog and `_trendingVideos` (real
//  YouTube-backed videos), so content stays in sync with the
//  rest of the app.
// ══════════════════════════════════════════════════════════
const yv2Categories = ['All', 'Trending', 'New Releases', 'Afrobeats', 'Ugandan Music', 'Hip Hop'];
let _yv2Category = 'All';
let _yv2HeroIdx = 0;
let _yv2HeroTimer = null;

function _yv2TrackForVideo(v) {
  return tracks.find(t => t.id === v.trackId);
}
function _yv2Duration(v) {
  const t = _yv2TrackForVideo(v);
  return (t && t.duration) || '';
}
function _yv2MatchesCategory(genre, tags, cat) {
  if (cat === 'All') return true;
  if (cat === 'Trending') return true; // trending row is already trending-only
  if (cat === 'New Releases') return (tags || []).includes('New');
  if (cat === 'Ugandan Music') return (tags || []).includes('Uganda');
  return (genre || '').toLowerCase().includes(cat.toLowerCase()) || (tags || []).some(tg => tg.toLowerCase().includes(cat.toLowerCase()));
}

function renderVideoBrowse() {
  _yv2RenderCats();
  _yv2RenderHero();
  _yv2RenderTrending();
  _yv2RenderNewReleases();
}

function _yv2RenderCats() {
  const wrap = document.getElementById('yv2Cats');
  if (!wrap) return;
  wrap.innerHTML = yv2Categories.map(c =>
    `<div class="yv2-cat${c === _yv2Category ? ' active' : ''}" onclick="yv2SetCategory('${c}')">${c}</div>`
  ).join('') + `<div class="yv2-cat-more"><i class="fas fa-ellipsis"></i></div>`;
}

function yv2SetCategory(cat) {
  _yv2Category = cat;
  _yv2RenderCats();
  _yv2RenderTrending();
  _yv2RenderNewReleases();
  const section = document.getElementById('yv2TrendRow');
  if (section) section.closest('.yv2-section').scrollIntoView({ behavior: 'smooth', block: 'start' });
}

function _yv2RenderHero() {
  const bg = document.getElementById('yv2HeroBg');
  const dots = document.getElementById('yv2HeroDots');
  if (!bg || !dots) return;
  const slides = _trendingVideos.slice(0, 4);
  if (!slides.length) return;
  if (_yv2HeroIdx >= slides.length) _yv2HeroIdx = 0;
  bg.style.backgroundImage = `url('${slides[_yv2HeroIdx].img}')`;
  dots.innerHTML = slides.map((s, i) =>
    `<div class="yv2-hero-dot${i === _yv2HeroIdx ? ' active' : ''}" onclick="yv2GoHero(${i})"></div>`
  ).join('');
  clearInterval(_yv2HeroTimer);
  _yv2HeroTimer = setInterval(() => {
    _yv2HeroIdx = (_yv2HeroIdx + 1) % slides.length;
    _yv2RenderHero();
  }, 6000);
}
function yv2GoHero(i) {
  _yv2HeroIdx = i;
  clearInterval(_yv2HeroTimer);
  _yv2RenderHero();
}
function yv2PlayHero() {
  const slides = _trendingVideos.slice(0, 4);
  const s = slides[_yv2HeroIdx];
  if (s) yv2Watch(s.youtubeId, s.title, s.artist);
}

function _yv2RenderTrending() {
  const row = document.getElementById('yv2TrendRow');
  if (!row) return;
  const filtered = _trendingVideos.filter(v => {
    const t = _yv2TrackForVideo(v);
    return _yv2MatchesCategory(t ? t.genre : '', t ? t.tags : [], _yv2Category);
  });
  const list = filtered.length ? filtered : _trendingVideos;
  row.innerHTML = list.map(v => {
    const dur = _yv2Duration(v);
    return `
    <div class="yv2-vcard" onclick="yv2Watch('${v.youtubeId}','${_yv2Esc(v.title)}','${_yv2Esc(v.artist)}')">
      <div class="yv2-vthumb">
        <img src="${v.img}" alt="${_yv2Esc(v.title)}" loading="lazy">
        ${dur ? `<div class="yv2-vdur">${dur}</div>` : ''}
      </div>
      <div class="yv2-vmeta">
        <div>
          <div class="yv2-vtitle">${v.title}</div>
          <div class="yv2-vartist">${v.artist}</div>
        </div>
        <div class="yv2-vmenu" role="button" aria-label="More options" onclick="event.stopPropagation();yv2VideoMenu('${v.youtubeId}','${_yv2Esc(v.title)}','${_yv2Esc(v.artist)}')"><i class="fas fa-ellipsis-vertical"></i></div>
      </div>
    </div>`;
  }).join('');
}

function _yv2RenderNewReleases() {
  const list = document.getElementById('yv2NewList');
  if (!list) return;
  const hasVideoTag = t => (t.tags || []).includes('New') && !!t.youtubeId;
  let items = tracks.filter(t => hasVideoTag(t) && _yv2MatchesCategory(t.genre, t.tags, _yv2Category));
  if (!items.length) items = tracks.filter(hasVideoTag);
  items = items.slice(0, 8);
  list.innerHTML = items.map(t => {
    const idx = tracks.indexOf(t);
    return `
    <div class="yv2-newitem" onclick="yv2Watch('${t.youtubeId}','${_yv2Esc(t.title)}','${_yv2Esc(t.artist)}')">
      <div class="yv2-newthumb">
        <img src="${t.img}" alt="${_yv2Esc(t.title)}" loading="lazy">
        ${t.duration ? `<div class="yv2-newdur">${t.duration}</div>` : ''}
      </div>
      <div class="yv2-newinfo">
        <div class="yv2-newtitle-row">
          <div class="yv2-newtitle">${t.title}</div>
          <div class="yv2-newbadge">NEW</div>
        </div>
        <div class="yv2-newartist">${t.artist}</div>
        <div class="yv2-newmeta">${t.plays || '0'} plays &middot; ${t.genre}</div>
      </div>
      <div class="yv2-newactions" onclick="event.stopPropagation()">
        <i class="fas fa-heart${_likedTracks && _likedTracks.has(idx) ? ' liked' : ''}" onclick="toggleLikeTrack(${idx});this.classList.toggle('liked')"></i>
        <i class="fas fa-ellipsis-vertical" role="button" aria-label="More options" onclick="yv2VideoMenu('${t.youtubeId}','${_yv2Esc(t.title)}','${_yv2Esc(t.artist)}')"></i>
      </div>
    </div>`;
  }).join('') || `<div style="padding:24px;text-align:center;color:var(--dim);">No videos found for this category</div>`;
}

function _yv2Esc(s) { return String(s || '').replace(/'/g, "&#39;").replace(/"/g, '&quot;'); }

function yv2Watch(youtubeId, title, artist) {
  if (!youtubeId) { showToast('Video not available for this track'); return; }
  const overlay = document.getElementById('yv2WatchOverlay');
  const wrap = document.getElementById('yv2WatchFrameWrap');
  document.getElementById('yv2WatchTitle').textContent = title || '';
  document.getElementById('yv2WatchArtist').textContent = artist || '';
  wrap.innerHTML = `<iframe src="https://www.youtube.com/embed/${youtubeId}?autoplay=1" title="${_yv2Esc(title)}" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe>`;
  overlay.classList.add('open');
}
function yv2CloseWatch() {
  const overlay = document.getElementById('yv2WatchOverlay');
  document.getElementById('yv2WatchFrameWrap').innerHTML = '';
  overlay.classList.remove('open');
}

// ══════════════════════════════════════════════════════════
//  YOUTUBE IFRAME PLAYER API — official embedded playback
//  Keeps users inside YAPSMUSIC: no redirect to youtube.com,
//  no YouTube app handoff, no downloading/extracting video files.
//  Docs: https://developers.google.com/youtube/iframe_api_reference
// ══════════════════════════════════════════════════════════
let _ytPlayer = null;          // single reusable YT.Player instance
let _ytPendingVideoId = null;  // queued video id if the API script hasn't finished loading yet
let _ytCurrentTrackId = null;  // which track's video is loaded right now (for auto-switch on song change)

function _ytLoadApiScript() {
  if (window.YT && window.YT.Player) return; // already loaded
  if (document.getElementById('yt-iframe-api')) return; // already loading
  const tag = document.createElement('script');
  tag.id = 'yt-iframe-api';
  tag.src = 'https://www.youtube.com/iframe_api'; // official YouTube IFrame API loader
  document.head.appendChild(tag);
}
// YouTube's API calls this exact global function name once the script has loaded — required by their spec.
window.onYouTubeIframeAPIReady = function () {
  if (_ytPendingVideoId) _ytCreatePlayer();
};

function _ytCreatePlayer() {
  if (!window.YT || !window.YT.Player || !document.getElementById('ytPlayerFrame')) return;
  _ytPlayer = new YT.Player('ytPlayerFrame', {
    height: '100%', width: '100%',
    playerVars: {
      playsinline: 1,     // REQUIRED to keep video inline on iOS Safari instead of forcing native fullscreen/app
      rel: 0,              // related videos (when shown) stay from the same channel
      modestbranding: 1,
      controls: 0,           // no native YT chrome at all, we render our own play/seek/volume/fullscreen bar
      disablekb: 1,          // avoid double-handling keyboard shortcuts alongside our own controls
      fs: 0,                 // native fullscreen button hidden too; our own expand button uses the Fullscreen API instead
      iv_load_policy: 3,
      origin: location.origin,
    },
    events: {
      onReady: () => {
        if (_ytPendingVideoId) { _ytPlayer.loadVideoById(_ytPendingVideoId); _ytPendingVideoId = null; }
        _ytCcReset();
      },
      onStateChange: _ytOnStateChange,
    },
  });
}

// ── Custom control bar state/helpers (replaces native YT controls entirely) ──
let _ytCcPollTimer = null;
let _ytCcDragging = false;

function _ytFmtTime(s) {
  s = Math.max(0, Math.floor(s || 0));
  const m = Math.floor(s / 60), sec = s % 60;
  return `${m}:${sec < 10 ? '0' : ''}${sec}`;
}

function _ytCcReset() {
  const fill = document.getElementById('ytCcFill'), thumb = document.getElementById('ytCcThumb');
  const cur = document.getElementById('ytCcCurrent'), dur = document.getElementById('ytCcDuration');
  if (fill) fill.style.width = '0%';
  if (thumb) thumb.style.left = '0%';
  if (cur) cur.textContent = '0:00';
  if (dur) dur.textContent = _ytPlayer && typeof _ytPlayer.getDuration === 'function' ? _ytFmtTime(_ytPlayer.getDuration()) : '0:00';
}

function _ytCcStartPoll() {
  _ytCcStopPoll();
  _ytCcPollTimer = setInterval(() => {
    if (!_ytPlayer || _ytCcDragging || typeof _ytPlayer.getCurrentTime !== 'function') return;
    const cur = _ytPlayer.getCurrentTime() || 0;
    const dur = _ytPlayer.getDuration() || 0;
    const pct = dur > 0 ? (cur / dur) * 100 : 0;
    const fill = document.getElementById('ytCcFill'), thumb = document.getElementById('ytCcThumb');
    if (fill) fill.style.width = pct + '%';
    if (thumb) thumb.style.left = pct + '%';
    const curEl = document.getElementById('ytCcCurrent'), durEl = document.getElementById('ytCcDuration');
    if (curEl) curEl.textContent = _ytFmtTime(cur);
    if (durEl) durEl.textContent = _ytFmtTime(dur);
  }, 250);
}
function _ytCcStopPoll() { if (_ytCcPollTimer) { clearInterval(_ytCcPollTimer); _ytCcPollTimer = null; } }

function _ytCcSetPlayIcon(playing) {
  const bar = document.getElementById('ytCcPlayBtn');
  const tap = document.getElementById('ytTapPlayIcon');
  if (bar) bar.innerHTML = playing ? '<i class="fas fa-pause"></i>' : '<i class="fas fa-play"></i>';
  if (tap) tap.innerHTML = playing ? '<i class="fas fa-pause"></i>' : '<i class="fas fa-play"></i>';
  const layer = document.getElementById('ytTapLayer');
  if (layer) layer.classList.toggle('show-btn', !playing);
}

function _ytCcTogglePlay() {
  if (!_ytPlayer) return;
  const state = _ytPlayer.getPlayerState();
  if (state === YT.PlayerState.PLAYING) _ytPlayer.pauseVideo();
  else _ytPlayer.playVideo();
}
function _ytToggleFromTap(e) { e.stopPropagation(); _ytCcTogglePlay(); }

function _ytCcSeek(e) {
  if (!_ytPlayer || typeof _ytPlayer.getDuration !== 'function') return;
  const bar = document.getElementById('ytCcProgress');
  const rect = bar.getBoundingClientRect();
  const pct = Math.min(1, Math.max(0, (e.clientX - rect.left) / rect.width));
  _ytPlayer.seekTo(pct * (_ytPlayer.getDuration() || 0), true);
}

function _ytCcToggleMute() {
  if (!_ytPlayer) return;
  const btn = document.getElementById('ytCcMuteBtn');
  if (_ytPlayer.isMuted()) {
    _ytPlayer.unMute();
    if (btn) btn.innerHTML = '<i class="fas fa-volume-up"></i>';
  } else {
    _ytPlayer.mute();
    if (btn) btn.innerHTML = '<i class="fas fa-volume-mute"></i>';
  }
}
function _ytCcSetVolume(v) {
  if (!_ytPlayer) return;
  _ytPlayer.setVolume(Number(v));
  const btn = document.getElementById('ytCcMuteBtn');
  if (btn) btn.innerHTML = Number(v) === 0 ? '<i class="fas fa-volume-mute"></i>' : '<i class="fas fa-volume-up"></i>';
}
function _ytCcFullscreen() {
  const wrap = document.getElementById('ytModalFrameWrap');
  if (!wrap) return;
  if (wrap.requestFullscreen) wrap.requestFullscreen();
  else if (wrap.webkitRequestFullscreen) wrap.webkitRequestFullscreen();
}

function _ytOnStateChange(e) {
  // Never let the audio track and a YouTube video play over each other.
  if (e.data === YT.PlayerState.PLAYING && isPlaying) {
    audioEngine.pause();
    isPlaying = false;
    updatePlayIcon();
    cancelAnimationFrame(progressInterval);
  }
  if (e.data === YT.PlayerState.PLAYING) { _ytCcSetPlayIcon(true); _ytCcStartPoll(); }
  else if (e.data === YT.PlayerState.PAUSED || e.data === YT.PlayerState.ENDED) { _ytCcSetPlayIcon(false); _ytCcStopPoll(); }
  if (e.data === YT.PlayerState.CUED) _ytCcReset();
}

// Loads a video into the existing player if it's already up, otherwise
// queues it for onReady/onYouTubeIframeAPIReady to pick up.
function _ytLoadVideo(youtubeId) {
  if (!youtubeId) return;
  if (_ytPlayer && typeof _ytPlayer.loadVideoById === 'function') {
    _ytPlayer.loadVideoById(youtubeId);
  } else {
    _ytPendingVideoId = youtubeId;
    _ytLoadApiScript();
    if (window.YT && window.YT.Player) _ytCreatePlayer();
  }
}

// Handles both real YouTube videos (v.youtubeId, played via the official
// IFrame API above) and videos promoted from a user's own upload
// (v.videoUrl, locally hosted mp4 — no YouTube involved at all).
function openTrendingVideo(v) {
  const modal = document.getElementById('ytModal');
  const wrap  = document.getElementById('ytModalFrameWrap');
  const slot  = document.getElementById('ytVideoSlot');
  document.getElementById('ytModalTitle').textContent = v.title || '';
  document.getElementById('ytModalArtist').textContent = v.artist || '';

  if (v.youtubeId) {
    _ytCurrentTrackId = v.trackId != null ? v.trackId : null;
    wrap.classList.add('yt-mode');
    _ytCcSetPlayIcon(false);
    _ytCcReset();
    if (!document.getElementById('ytPlayerFrame')) {
      slot.innerHTML = '<div id="ytPlayerFrame"></div>';
    }
    modal.classList.add('open');
    _ytLoadApiScript();
    if (window.YT && window.YT.Player) {
      if (_ytPlayer) {
        // Reusing an already-ready player from an earlier video open — safe to load directly.
        _ytLoadVideo(v.youtubeId);
      } else {
        // Player was torn down on close (or never built yet). Queue the id and let
        // onReady pick it up once the fresh player actually finishes initializing —
        // calling loadVideoById synchronously right after `new YT.Player(...)` races
        // the iframe's own startup and silently fails.
        _ytPendingVideoId = v.youtubeId;
        _ytCreatePlayer();
      }
    } else {
      _ytPendingVideoId = v.youtubeId;
    }
  } else if (v.videoUrl) {
    _ytCurrentTrackId = null;
    if (_ytPlayer) { try { _ytPlayer.stopVideo(); } catch (e) {} }
    _ytCcStopPoll();
    wrap.classList.remove('yt-mode'); // local mp4 uses its own native <video> controls, not our YT overlay
    slot.innerHTML = `<video src="${v.videoUrl}" controls autoplay playsinline style="position:absolute;inset:0;width:100%;height:100%;object-fit:contain;background:#000;"></video>`;
    _ytPlayer = null; // that div's gone now, next YouTube open recreates the player fresh
    modal.classList.add('open');
  } else {
    wrap.classList.remove('yt-mode');
    slot.innerHTML = '';
    modal.classList.add('open');
  }
}

// Opens the currently-playing song's video (Now Playing "VIDEO" button).
function openTrackVideo() {
  const t = tracks[currentTrack];
  if (!t) return;
  if (!t.youtubeId) { showToast('No video available for this song'); return; }
  openTrendingVideo({ youtubeId: t.youtubeId, title: t.title, artist: t.artist, trackId: t.id });
}

function closeYouTubeModal(e) {
  if (e) e.stopPropagation();
  const modal = document.getElementById('ytModal');
  modal.classList.remove('open');
  if (_ytPlayer) { try { _ytPlayer.stopVideo(); } catch (err) {} }
  _ytCcStopPoll();
  const wrap = document.getElementById('ytModalFrameWrap');
  const slot = document.getElementById('ytVideoSlot');
  if (slot) slot.innerHTML = ''; // stop playback (removes iframe/video entirely)
  if (wrap) wrap.classList.remove('yt-mode');
  _ytPlayer = null;
  _ytCurrentTrackId = null;
}

// If the video modal is open and the user skips to another song (next/prev/
// tapping a different track), auto-load that song's video into the SAME
// player — no reopening, no redirect. If the new song has no video, show
// a friendly empty state but leave the panel open.
function _onTrackChange_video() {
  if (_ytCurrentTrackId === null) return; // video panel isn't open on a YouTube video right now
  const t = tracks[currentTrack];
  if (!t) return;
  if (t.youtubeId) {
    document.getElementById('ytModalTitle').textContent = t.title;
    document.getElementById('ytModalArtist').textContent = t.artist;
    _ytCurrentTrackId = t.id;
    _ytLoadVideo(t.youtubeId);
  } else {
    _ytCurrentTrackId = null;
    document.getElementById('ytModalTitle').textContent = t.title;
    document.getElementById('ytModalArtist').textContent = t.artist;
    const wrap = document.getElementById('ytModalFrameWrap');
    const slot = document.getElementById('ytVideoSlot');
    _ytCcStopPoll();
    if (wrap) wrap.classList.remove('yt-mode');
    if (slot) slot.innerHTML = '<div style="display:flex;align-items:center;justify-content:center;height:100%;color:var(--muted);font-size:13px;font-weight:600;padding:20px;text-align:center;">No video available for this song</div>';
    if (_ytPlayer) { try { _ytPlayer.destroy(); } catch (e) {} _ytPlayer = null; }
  }
}
/* Hook into playTrack — patch after load, same pattern used for lyrics sync above. */
(function() {
  const _origPlayTrackForVideo = window.playTrack;
  window.playTrack = function(idx) {
    _origPlayTrackForVideo && _origPlayTrackForVideo(idx);
    _onTrackChange_video();
  };
})();

// Deferred: several of these depend on const/let data declared later in
// this same script (e.g. _trendingVideos, _heroTimer, tasteData). Running
// them via setTimeout(...,0) lets the rest of the script finish executing
// first, avoiding "Cannot access '...' before initialization" errors that
// used to abort the whole init sequence (and everything wired up after it,
// including page navigation).
setTimeout(() => {
  renderHome();
  renderPersonalizedHome();
  renderTasteProfile();
  renderMessages();
  renderActivity();
  // Pre-render these pages so they load instantly on first visit
  renderCharts();
  renderNotifications();
  renderProfile();
}, 0);

// ── TASTE PROFILE ──
// Built from real activity: liked songs (x3), followed artists (x2) and play history (x1).
// Until there is some activity it shows clearly-labelled "starter picks". Tapping a genre
// excludes/includes it from the Recommended row (saved on this device).
const tasteData = [
  { img:'images/img-07-2eee2d73.jpg', name:'Afrobeats',    pct:72 },
  { img:'images/img-09-6ae12395.jpg', name:'Bongo Flava',  pct:45 },
  { img:'images/img-10-fd5cda78.jpg', name:'Dancehall',    pct:41 },
  { img:'images/img-11-c4e1b948.jpg', name:'R&B',          pct:35 },
  { img:'images/img-12-3bbd709c.jpg', name:'Traditional',  pct:28 },
];
const _TP_GRADS = [['#2f8eff','#7a4cf0'],['#ff512f','#dd2476'],['#11998e','#38ef7d'],['#f7971e','#ff5e62'],['#7f00ff','#e100ff'],['#2193b0','#6a5acd']];
function _tpEsc(v) { return String(v == null ? '' : v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function _tasteExcludedSet() {
  try { return new Set(JSON.parse(localStorage.getItem('yaps_taste_excluded') || '[]')); } catch (e) { return new Set(); }
}
function _tasteSaveExcluded(set) { try { localStorage.setItem('yaps_taste_excluded', JSON.stringify([...set])); } catch (e) {} }
function tasteToggle(name) {
  const ex = _tasteExcludedSet();
  if (ex.has(name)) { ex.delete(name); showToast(name + ' added back to your taste'); }
  else { ex.add(name); showToast(name + ' excluded from recommendations'); }
  _tasteSaveExcluded(ex);
  renderTasteProfile();
  try { if (typeof _renderRecommended === 'function') _renderRecommended(); } catch (e) {}
}
function tasteReset() {
  _tasteSaveExcluded(new Set());
  renderTasteProfile();
  try { if (typeof _renderRecommended === 'function') _renderRecommended(); } catch (e) {}
  showToast('Taste profile reset');
}
function _tasteCompute() {
  const score = {}, liked = {}, played = {};
  const add = (g, w, bucket) => { if (!g) return; score[g] = (score[g] || 0) + w; if (bucket) bucket[g] = (bucket[g] || 0) + 1; };
  try {
    _likedTracks.forEach(i => tracks[i] && add(tracks[i].genre, 3, liked));
    tracks.forEach(t => { if (_followedArtists.has(t.artist)) add(t.genre, 2); });
    _history.forEach(i => tracks[i] && add(tracks[i].genre, 1, played));
  } catch (e) {}
  const entries = Object.entries(score).sort((a, b) => b[1] - a[1]).slice(0, 6);
  if (!entries.length) return null;
  const max = entries[0][1], total = entries.reduce((n, e) => n + e[1], 0);
  return entries.map(([name, sc]) => {
    const t = tracks.find(x => x.genre === name && x.img);
    return { name, pct: Math.max(8, Math.round(sc / max * 100)), share: Math.round(sc / total * 100), sc,
             img: t ? t.img : '', liked: liked[name] || 0, played: played[name] || 0 };
  });
}
function renderTasteProfile() {
  const grid = document.getElementById('taste-grid');
  const hero = document.getElementById('tp-hero');
  if (!grid) return;
  const real = _tasteCompute();
  const items = real || tasteData.map(t => ({ name: t.name, pct: t.pct, share: 0, sc: t.pct, img: t.img, liked: 0, played: 0 }));
  const ex = _tasteExcludedSet();
  const totalSc = items.reduce((n, i) => n + i.sc, 0) || 1;

  if (hero) {
    const top = items.find(i => !ex.has(i.name)) || items[0];
    let liked = 0, followed = 0, played = 0;
    try { liked = _likedTracks.size; followed = _followedArtists.size; played = Math.min(_history.length, 50); } catch (e) {}
    const segs = items.map((i, k) => {
      const g = _TP_GRADS[k % _TP_GRADS.length];
      return { i, g, w: Math.max(4, Math.round(i.sc / totalSc * 100)) };
    });
    hero.innerHTML = `
      <div class="tp-hero-top">
        <div class="tp-hero-ico"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="11" width="3.4" height="9" rx="1.7"/><rect x="8.6" y="4" width="3.4" height="16" rx="1.7"/><rect x="14.2" y="8" width="3.4" height="12" rx="1.7"/><rect x="19.8" y="13" width="2.2" height="7" rx="1.1"/></svg></div>
        <div><div class="tp-eyebrow">Your top vibe</div><div class="tp-top">${_tpEsc(top.name)}</div></div>
        <div class="tp-badge${real ? '' : ' starter'}">${real ? 'Personalised' : 'Starter picks'}</div>
      </div>
      <div class="tp-mix" aria-hidden="true">${segs.map(x => `<span style="flex:${x.w};--g1:${x.g[0]};--g2:${x.g[1]}"></span>`).join('')}</div>
      <div class="tp-legend">${segs.map(x => `<span><i style="--g1:${x.g[0]};--g2:${x.g[1]}"></i>${_tpEsc(x.i.name)}${real ? ` <b>${x.i.share}%</b>` : ''}</span>`).join('')}</div>
      <div class="tp-stats">
        <div class="tp-stat"><b>${liked}</b><small>Liked songs</small></div>
        <div class="tp-stat"><b>${followed}</b><small>Artists followed</small></div>
        <div class="tp-stat"><b>${played}</b><small>Recently played</small></div>
      </div>
      <p class="tp-note">${real
        ? 'Built from the songs you like, the artists you follow and what you play. Tap a genre to include or exclude it from your recommendations.'
        : 'These are starter picks. Like songs, follow artists and play music &mdash; this updates automatically to match your taste.'}</p>`;
  }

  grid.innerHTML = items.map((t, k) => {
    const g = _TP_GRADS[k % _TP_GRADS.length];
    const on = !ex.has(t.name);
    const nameLit = _tpEsc(JSON.stringify(t.name));
    const cap = real
      ? (t.liked || t.played ? `${t.liked} liked · ${t.played} played` : 'From artists you follow')
      : 'Starter pick';
    return `
    <div class="tp-card${on ? ' selected' : ''}${k === 0 ? ' top' : ''}" style="--g1:${g[0]};--g2:${g[1]}" role="switch" aria-checked="${on}" tabindex="0"
         aria-label="${_tpEsc(t.name)}, ${on ? 'included in' : 'excluded from'} recommendations"
         onclick="tasteToggle(${nameLit})" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();tasteToggle(${nameLit})}">
      ${t.img ? `<img class="tp-bg" src="${_tpEsc(t.img)}" alt="" loading="lazy" decoding="async" onerror="this.remove()">` : ''}
      <div class="tp-rank">${k === 0 ? '★ #1' : '#' + (k + 1)}</div>
      <div class="tp-check"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg></div>
      <div class="tp-foot">
        <div class="tp-ring"><svg viewBox="0 0 48 48" aria-hidden="true"><circle class="tr" cx="24" cy="24" r="19"/><circle class="pr" cx="24" cy="24" r="19" style="--p:${t.pct}"/></svg><b>${t.pct}</b></div>
        <div class="tp-txt"><div class="tp-name">${_tpEsc(t.name)}</div><div class="tp-cap">${_tpEsc(cap)}</div></div>
      </div>
    </div>`;
  }).join('');

  const rl = document.getElementById('tasteResetLink');
  if (rl) rl.style.display = ex.size ? '' : 'none';
}

// ── PROMPTED PLAYLIST (Real Claude API) ──
async function generatePromptedPlaylist() {
  const input = document.getElementById('promptPlaylistInput');
  const mood = input.value.trim();
  if (!mood) { showToast('Type a mood first!'); return; }
  const result = document.getElementById('promptPlaylistResult');
  const titleEl = document.getElementById('promptPlaylistTitle');
  const list = document.getElementById('promptPlaylistTracks');

  titleEl.textContent = 'Building "' + mood + '" playlist...';
  result.classList.add('show');
  list.innerHTML = `<div style="padding:20px;text-align:center;color:var(--dim);"><i class="fas fa-spinner fa-spin" style="font-size:24px;"></i></div>`;


  try {
    const parsed = await api('/api/ai/dj', { method: 'POST', body: {
      mood: String(mood).slice(0, 200),
      catalogue: tracks.slice(0, 400).map(t => ({ title: String(t.title || '').slice(0, 150), artist: String(t.artist || '').slice(0, 100), genre: String(t.genre || '').slice(0, 40) })),
    } });

    titleEl.textContent = String(parsed.playlistName || '').replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{2B00}-\u{2BFF}\u{FE0F}\u{200D}]/gu, '').trim() || `${mood} · 5 tracks`;
    list.innerHTML = (parsed.picks || []).map((p, i) => {
      const t = tracks[p.index];
      if (!t) return '';
      return `
        <div class="track-row" onclick="playTrack(${p.index})" style="padding:6px 8px;">
          <div class="tr-num">${i+1}</div>
          <div class="tr-play-btn"><i class="fas fa-play"></i></div>
          <div class="tr-art"><img src="${t.img}" alt="${t.title}" loading="lazy" style="width:100%;height:100%;object-fit:cover;border-radius:6px;"></div>
          <div class="tr-info"><div class="tr-title">${t.title}</div><div class="tr-artist">${t.artist}</div></div>
          <div class="tr-duration">${t.duration}</div>
        </div>`;
    }).join('');
    showToast('AI playlist ready!');
  } catch(err) {
    titleEl.textContent = 'Couldn\'t generate playlist';
    list.innerHTML = `<div style="padding:20px;text-align:center;color:var(--dim);font-size:13px;">Check your connection and try again.</div>`;
    console.error('Playlist AI error:', err);
  }
}

// ── AI DJ CHAT (fully standalone — no external API calls) ──
// ══════════════════════════════════════════════════════════
//  YAPS AI — self-contained logic, works fully offline
// ══════════════════════════════════════════════════════════

let _djChatHistory = [];
let _djIsThinking = false;
let _djVoiceRecog = null;
let _djVoiceActive = false;
let _djLastPicks = []; // last set of picks for "Queue All"

// ── Persistent local memory — survives page reloads, no backend needed ──
const _DJ_HISTORY_KEY = 'yaps_ai_chat_history';
const _DJ_PREFS_KEY = 'yaps_ai_prefs';

function _djLoadPrefs() {
  try {
    const raw = localStorage.getItem(_DJ_PREFS_KEY);
    return raw ? JSON.parse(raw) : { artists: {}, genres: {} };
  } catch (e) { return { artists: {}, genres: {} }; }
}

function _djSavePrefs(prefs) {
  try { localStorage.setItem(_DJ_PREFS_KEY, JSON.stringify(prefs)); } catch (e) {}
}

function _djRememberPreference(type, name) {
  if (!name) return;
  const prefs = _djLoadPrefs();
  const bucket = type === 'artist' ? prefs.artists : prefs.genres;
  bucket[name] = (bucket[name] || 0) + 1;
  _djSavePrefs(prefs);
}

function _djTopPreference(type) {
  const prefs = _djLoadPrefs();
  const bucket = type === 'artist' ? prefs.artists : prefs.genres;
  const entries = Object.entries(bucket);
  if (!entries.length) return null;
  entries.sort((a, b) => b[1] - a[1]);
  return entries[0][0];
}

// ── Permanent mute list — "don't play Rema again" sticks across sessions ──
const _DJ_MUTE_KEY = 'yaps_ai_muted';

function _djLoadMuted() {
  try {
    const raw = localStorage.getItem(_DJ_MUTE_KEY);
    return raw ? JSON.parse(raw) : [];
  } catch (e) { return []; }
}

function _djMute(name) {
  const muted = _djLoadMuted();
  const lower = name.toLowerCase();
  if (!muted.includes(lower)) {
    muted.push(lower);
    try { localStorage.setItem(_DJ_MUTE_KEY, JSON.stringify(muted)); } catch (e) {}
  }
}

function _djUnmuteAll() {
  try { localStorage.removeItem(_DJ_MUTE_KEY); } catch (e) {}
}

function _djSaveHistory() {
  try { localStorage.setItem(_DJ_HISTORY_KEY, JSON.stringify(_djChatHistory.slice(-40))); } catch (e) {}
}

function _djLoadHistory() {
  try {
    const raw = localStorage.getItem(_DJ_HISTORY_KEY);
    return raw ? JSON.parse(raw) : [];
  } catch (e) { return []; }
}

// Replays saved history as plain chat bubbles (track cards aren't persisted,
// just the conversation) so context carries over across a reload.
function _djRestoreHistory() {
  const saved = _djLoadHistory();
  if (!saved.length) return;
  _djChatHistory = saved;
  const area = document.getElementById('djChatArea');
  if (!area) return;
  saved.forEach(m => addDJMessage(m.content, m.role === 'user'));
}

let _djHistoryRestored = false;

function _djTimeGreeting() {
  const h = new Date().getHours();
  if (h >= 5 && h < 12) {
    return "Good morning! I'm YAPS AI, built right into the app, no internet needed. Want something to ease into the day, or straight energy to get you moving? Tell me a mood, artist, or genre";
  }
  if (h >= 12 && h < 17) {
    return "Sssup! I'm YAPS AI, built right into the app, no internet needed. Perfect time for some afternoon Afrobeats or whatever you're feeling. Tell me a mood, an artist, or a genre and I'll build you a set";
  }
  if (h >= 17 && h < 21) {
    return "Evening! I'm YAPS AI, ready to soundtrack your wind-down or your night out. Tell me the mood, an artist, or a genre and I'll build you a set, no internet or outside AI needed";
  }
  return "Late one, eh? I'm YAPS AI, built right into the app. Whether it's a Kampala-nights set or something to chill you out, tell me the vibe, an artist, or a genre";
}

function _djApplyTimeGreeting() {
  const area = document.getElementById('djChatArea');
  if (!area) return;
  const bubble = area.querySelector('.dj-message .dj-msg-bubble');
  if (bubble) bubble.textContent = _djTimeGreeting();
}

function _djRestoreHistoryOnce() {
  if (_djHistoryRestored) return;
  _djHistoryRestored = true;
  const saved = _djLoadHistory();
  if (saved.length) {
    _djRestoreHistory();
  } else {
    _djApplyTimeGreeting();
  }
}

function sendDJPrompt(text) {
  document.getElementById('djInput').value = text;
  navigate('ai-dj');
  sendDJMessage();
}

function sendDJMessage() {
  if (_djIsThinking) return;
  const input = document.getElementById('djInput');
  const msg = input.value.trim();
  if (!msg) return;
  input.value = '';
  addDJMessage(msg, true);
  _djChatHistory.push({ role: 'user', content: msg });
  _djSaveHistory();
  callDJAI();
}

function clearDJChat() {
  _djChatHistory = [];
  _djLastPicks = [];
  _djLastLabel = '';
  try { localStorage.removeItem(_DJ_HISTORY_KEY); } catch (e) {}
  const area = document.getElementById('djChatArea');
  area.innerHTML = `
    <div class="dj-message">
      <div class="dj-msg-avatar"></div>
      <div class="dj-msg-bubble">Fresh start! What vibe are we going for?</div>
    </div>
    <div class="yai-caps" id="yaiCaps">
      <button type="button" class="yai-cap" data-q="Late night drive" onclick="sendDJPrompt(this.dataset.q)"><i class="fas fa-bolt"></i><strong>Build a set</strong><span>Any mood, moment or feeling</span></button>
      <button type="button" class="yai-cap" data-q="45 minutes of party music" onclick="sendDJPrompt(this.dataset.q)"><i class="fas fa-clock"></i><strong>Set by length</strong><span>“45 minutes of party music”</span></button>
      <button type="button" class="yai-cap" data-q="Songs like Yoyo" onclick="sendDJPrompt(this.dataset.q)"><i class="fas fa-shuffle"></i><strong>Find similar</strong><span>“Songs like Yoyo”</span></button>
      <button type="button" class="yai-cap" data-q="Volume 50" onclick="sendDJPrompt(this.dataset.q)"><i class="fas fa-sliders"></i><strong>Control playback</strong><span>“Volume 50”, “rewind 10 seconds”</span></button>
      <button type="button" class="yai-cap" data-q="Stop playing in 30 minutes" onclick="sendDJPrompt(this.dataset.q)"><i class="fas fa-moon"></i><strong>Sleep timer</strong><span>“Stop playing in 30 minutes”</span></button>
      <button type="button" class="yai-cap" data-q="Recommend something for me" onclick="sendDJPrompt(this.dataset.q)"><i class="fas fa-heart"></i><strong>Your taste</strong><span>Picks based on your likes</span></button>
    </div>`;
}

function setDJStatus(status) {
  // status: 'idle' | 'thinking' | 'playing' — drives the orb and the line under the title
  const orb = document.getElementById('yaiOrb');
  if (orb) orb.dataset.state = status;
  const label = document.getElementById('yaiStatus');
  if (label) label.textContent = status === 'thinking' ? 'Thinking…' : status === 'playing' ? 'Playing your set' : 'Ready when you are';
}

// ── Voice Input ──
function toggleDJVoice() {
  const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
  if (!SpeechRecognition) { showToast('Voice input not supported on this browser'); return; }

  if (_djVoiceActive) {
    if (_djVoiceRecog) _djVoiceRecog.stop();
    return;
  }

  _djVoiceRecog = new SpeechRecognition();
  _djVoiceRecog.lang = 'en-UG';
  _djVoiceRecog.interimResults = false;
  _djVoiceRecog.maxAlternatives = 1;

  const btn = document.getElementById('djVoiceBtn');

  _djVoiceRecog.onstart = () => {
    _djVoiceActive = true;
    if (btn) btn.classList.add('listening');
    showToast('Listening...');
  };
  _djVoiceRecog.onresult = e => {
    const text = e.results[0][0].transcript;
    document.getElementById('djInput').value = text;
    sendDJMessage();
  };
  _djVoiceRecog.onend = () => {
    _djVoiceActive = false;
    if (btn) btn.classList.remove('listening');
  };
  _djVoiceRecog.onerror = () => {
    _djVoiceActive = false;
    if (btn) btn.classList.remove('listening');
    showToast('Could not hear you, try again');
  };
  _djVoiceRecog.start();
}

// ── Queue All picks ──
function djQueueAll(picks) {
  if (!picks || picks.length === 0) return;
  picks.forEach((p, i) => {
    const t = tracks[p.index];
    if (!t) return;
    if (i === 0) {
      playTrack(p.index);
    } else {
      _queuedTracks.push(p.index);
    }
  });
  // Update queue panel if open
  if (typeof renderQueue === 'function') renderQueue();
  showToast(`Playing set, ${picks.length} tracks queued`);
  setDJStatus('playing');
}

