// ── small shared helpers ──
function _djEsc(s) {
  return String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[c]));
}
function _djReEsc(s) { return String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }
function _djTitleCase(s) {
  return String(s || '').trim().replace(/\s+/g, ' ').replace(/(^|\s)([a-z])/g, (m, a, b) => a + b.toUpperCase());
}
function _djSecs(d) {
  const m = String(d || '').match(/^(\d+):(\d{2})$/);
  return m ? (+m[1]) * 60 + (+m[2]) : 200;
}

// Keyword test: tiny keys must be whole words, 4-letter keys must start a word,
// longer keys can appear anywhere ("ex" no longer fires on "next" or "exam").
function _djHas(msg, key) {
  if (!key) return false;
  const k = _djReEsc(key);
  if (key.length <= 3) return new RegExp('\\b' + k + '\\b').test(msg);
  if (key.length === 4) return new RegExp('\\b' + k).test(msg);
  return msg.includes(key);
}

// ── Fuzzy matching helpers (typo-tolerant, no library needed) ──
function _lev(a, b) {
  if (a === b) return 0;
  const m = a.length, n = b.length;
  if (!m) return n;
  if (!n) return m;
  let prev = Array.from({ length: n + 1 }, (_, j) => j);
  for (let i = 1; i <= m; i++) {
    const cur = [i];
    for (let j = 1; j <= n; j++) {
      cur[j] = a[i - 1] === b[j - 1]
        ? prev[j - 1]
        : 1 + Math.min(prev[j - 1], prev[j], cur[j - 1]);
    }
    prev = cur;
  }
  return prev[n];
}

// Fuzzy "does msg contain something close to key" — tolerates small typos
function _fuzzyIncludes(msg, key) {
  if (!key) return false;
  if (msg.includes(key)) return true;
  if (key.length < 5) return false; // short keys must match exactly, never fuzzily
  const words = msg.split(/\s+/).filter(Boolean);
  const keyWords = key.split(/\s+/).filter(Boolean);
  const wordDist = w => w.length <= 5 ? 1 : w.length <= 9 ? 2 : 3;
  if (keyWords.length === 1) {
    const maxDist = wordDist(key);
    return words.some(w => Math.abs(w.length - key.length) <= maxDist && _lev(w, key) <= maxDist);
  }
  // Multi-word phrase — require EVERY word in the phrase to closely match the
  // corresponding word in a same-length window (prevents loose whole-phrase matches)
  for (let i = 0; i <= words.length - keyWords.length; i++) {
    const slice = words.slice(i, i + keyWords.length);
    const allClose = keyWords.every((kw, j) => {
      const d = wordDist(kw);
      return Math.abs(slice[j].length - kw.length) <= d && _lev(slice[j], kw) <= d;
    });
    if (allClose) return true;
  }
  return false;
}

// ── Negation / exclusion ("no gospel", "not rema", "without slow songs") ──
function _djExtractExclusions(msg) {
  const out = [];
  const re = /\b(?:no|not|without|except|excluding|skip|avoid)\s+([a-z][a-z0-9' ]{1,30})/g;
  let m;
  while ((m = re.exec(msg))) {
    const phrase = m[1].trim().split(/\b(and|please|thanks|today|right now)\b/)[0].trim();
    if (!phrase || /^(this|that|it|to|ahead|back|the|a|my|me|more|longer|problem|worries)\b/.test(phrase)) continue;
    out.push(phrase);
    const first = phrase.split(' ')[0];
    if (phrase.includes(' ') && first.length >= 3) out.push(first);
  }
  return out.filter(Boolean);
}

function _djIsExcluded(track, exclusions) {
  if (!track) return false;
  const muted = _djLoadMuted();
  const all = (exclusions || []).concat(muted);
  if (!all.length) return false;
  const hay = `${track.artist} ${track.genre} ${(track.tags || []).join(' ')}`.toLowerCase();
  return all.some(ex => hay.includes(ex) || _fuzzyIncludes(hay, ex));
}

function _djFilterExcluded(picks, exclusions) {
  const kept = picks.filter(p => !_djIsExcluded(tracks[p.index], exclusions));
  if (kept.length >= Math.min(4, picks.length)) return kept;
  // Backfill with non-excluded random tracks if we filtered too many out
  const used = new Set(kept.map(p => p.index));
  const pool = [...Array(tracks.length).keys()].filter(i => !used.has(i) && !_djIsExcluded(tracks[i], exclusions));
  while (kept.length < Math.min(4, picks.length) && pool.length) {
    const idx = pool.splice(Math.floor(Math.random() * pool.length), 1)[0];
    kept.push({ index: idx, reason: 'good fit' });
  }
  return kept;
}

// ── Smalltalk — greetings, thanks, time, light chat (no track set needed) ──
function _djTimeHint() {
  const h = new Date().getHours();
  if (h >= 5 && h < 12) return 'a good moment for a morning set.';
  if (h >= 12 && h < 17) return 'afternoon Afrobeats weather.';
  if (h >= 17 && h < 21) return 'prime time to wind down or head out.';
  return 'late-night listening hours.';
}

const _DJ_JOKES = [
  "Why did the musician get arrested? Because he got caught with the drum sticks.",
  "What's a DJ's favourite fruit? Beets, obviously.",
  "I told my phone to play something upbeat. It started charging."
];

function _djSmalltalk(msg) {
  const t = msg.trim();
  if (/^\s*(hi|hello|hey|hiya|sup|yo|howzit|mambo|wassup|what'?s up|oli otya|good morning|good afternoon|good evening)\b[\s!.?]*$/.test(t)) {
    return "Hey! Give me a mood, an artist or a genre, or try “30 minutes of party” or “songs like Yoyo”.";
  }
  if (t.length < 40 && (/\bhow are you\b|\bhow'?s it going\b|\bhow do you do\b/.test(t) || /^oli otya\b/.test(t))) {
    return "All good and ready to spin. What are we listening to?";
  }
  if (/\b(thank you|thanks|thx|appreciate|webale|gyebale)\b/.test(t) && t.length < 40) {
    return "Anytime! Shout whenever you want another set.";
  }
  if (/^\s*(bye|goodbye|see you|later|good night|goodnight)\b/.test(t)) {
    return "Later! I'll be right here whenever you need the next set.";
  }
  if (/\bwhat time is it\b|\bwhat'?s the time\b|\bthe time now\b|\bwhat is the time\b/.test(t)) {
    const d = new Date();
    return `It's ${d.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' })}, ${_djTimeHint()}`;
  }
  if (/\bwhat day is it\b|\bwhat'?s the date\b|\btoday'?s date\b|\bwhat is today\b/.test(t)) {
    return `Today is ${new Date().toLocaleDateString([], { weekday: 'long', day: 'numeric', month: 'long' })}.`;
  }
  if (/\b(tell me a joke|make me laugh|got any jokes|say something funny)\b/.test(t)) {
    return _DJ_JOKES[Math.floor(Math.random() * _DJ_JOKES.length)];
  }
  if (/\bwho (made|built|created|programmed) you\b|\bare you (a )?(real|human|bot|ai|robot)\b/.test(t)) {
    return "I'm YAPS AI, a music assistant that lives inside this app. I work from the YAPS catalogue on your device, so there's no outside AI involved.";
  }
  return null;
}

function _localDJMatch(userMsg, exclusions) {
  const msg = userMsg.toLowerCase();
  let best = null, bestScore = 0;
  for (const vibe of _djVibeDB) {
    if (exclusions && exclusions.length && vibe.keys.some(k => exclusions.some(ex => k === ex || (ex.length > 3 && k.includes(ex))))) continue;
    let score = 0;
    for (const key of vibe.keys) {
      const words = key.split(' ').length;
      if (_djHas(msg, key)) score += words * 2;                              // exact match weighted higher
      else if (key.length >= 5 && _fuzzyIncludes(msg, key)) score += words;  // typo-tolerant match
    }
    if (score > bestScore) { bestScore = score; best = vibe; }
  }
  return best;
}

// Ranks the whole live catalogue against a vibe profile ({g:genre weights, t:tag weights,
// r:region weights, collab, long}). Returns track indices, best first, with a little
// randomness and a bias toward tracks not yet suggested this session.
function _djRankByProfile(prof, exclusions) {
  const out = [];
  tracks.forEach((t, i) => {
    if (_djIsExcluded(t, exclusions)) return;
    let base = (prof.g && prof.g[t.genre]) || 0;
    (t.tags || []).forEach(tg => { if (prof.t && prof.t[tg]) base += prof.t[tg]; });
    if (prof.r && prof.r[t.region]) base += prof.r[t.region];
    if (prof.collab && /(\bft\.?\s|\bfeat\.?\s|&|\sx\s)/i.test(t.artist || '')) base += prof.collab;
    if (base <= 0) return;
    let s = base;
    if (prof.long && _djSecs(t.duration) >= 210) s += 0.6;
    if (!_djSessionSeen.has(i)) s += 0.8;
    s += Math.random() * 1.4;
    out.push([s, i]);
  });
  return out.sort((a, b) => b[0] - a[0]).map(x => x[1]);
}

function _pickRandom(arr, n) {
  const shuffled = [...arr].sort(() => Math.random() - 0.5);
  return shuffled.slice(0, n);
}

// Parses "2.3M" / "41K" / plain numbers into a comparable number
function _djParseCount(str) {
  if (!str) return 0;
  const m = String(str).trim().match(/^([\d.]+)\s*([kKmMbB]?)$/);
  if (!m) return 0;
  const num = parseFloat(m[1]);
  const mult = { k: 1e3, m: 1e6, b: 1e9 }[m[2].toLowerCase()] || 1;
  return num * mult;
}

// ── Session no-repeat bias — remembers what's already been recommended
// this session (not persisted) so repeated requests surface fresher picks first ──
let _djSessionSeen = new Set();

function _djMarkSeen(picks) {
  (picks || []).forEach(p => _djSessionSeen.add(p.index));
}

function _djPickPreferUnseen(pool, n) {
  const unseen = pool.filter(i => !_djSessionSeen.has(i));
  const seen = pool.filter(i => _djSessionSeen.has(i));
  const ordered = [..._pickRandom(unseen, unseen.length), ..._pickRandom(seen, seen.length)];
  return ordered.slice(0, n);
}

// ── Standalone DJ brain — 100% local, no network calls, no API key ──
// Builds live indexes off the real `tracks` catalogue so it recognizes
// every artist/genre/tag you actually have, not just a hardcoded list.
// Words that appear in artist names but shouldn't, on their own, mean "that artist"
const _DJ_NAME_STOP = new Set(['king','queen','kings','prince','princess','lady','lord','mama','papa','sista','brother','sister','pastor','bishop','prophet','apostle','minister','reverend','dj','mc','big','little','young','lil','sir','general','the','and','with','feat','featuring','big','lil','sir','mrs','mr','dr','one','new','dj','mc',
  'worship','praise','gospel','music','choir','band','team','family','ministries','ministry','church','records','sound','voice','voices','kids','youth','children','united','nation','house','life','light','love','rain','sunday','party','night','dance','hype','chill','traditional','international','official','uganda','ugandan','kampala','new','best','top']);

// Splits "A ft. B & C" into individual performers
function _djPerformers(artistStr) {
  return String(artistStr || '').split(/\s+(?:ft\.?|feat\.?|featuring|x|&|and|with)\s+|\s*[,+]\s*/i).map(s => s.trim()).filter(Boolean);
}

let _djIndex = null;
function _djBuildIndex() {
  if (_djIndex && _djIndex.n === tracks.length) return _djIndex;
  const artists = new Map();     // full credit string -> {name, indices[]}
  const performers = new Map();  // individual performer -> {name, indices[]}
  const tokens = new Map();      // distinctive name word -> Set(performer keys)
  const genres = new Map();
  const titles = [];
  tracks.forEach((t, i) => {
    const aKey = (t.artist || '').toLowerCase();
    if (aKey) {
      if (!artists.has(aKey)) artists.set(aKey, { name: t.artist, indices: [] });
      artists.get(aKey).indices.push(i);
    }
    _djPerformers(t.artist).forEach(p => {
      const k = p.toLowerCase();
      if (!performers.has(k)) performers.set(k, { name: p, indices: [] });
      const e = performers.get(k);
      if (!e.indices.includes(i)) e.indices.push(i);
      const parts = k.split(/[^a-z0-9']+/).filter(Boolean);
      parts.forEach((tok, pi) => {
        const firstOfFull = pi === 0 && parts.length >= 2 && tok.length === 3;   // "fik" in "Fik Fameica"
        if ((tok.length >= 4 || firstOfFull) && !_DJ_NAME_STOP.has(tok)) {
          if (!tokens.has(tok)) tokens.set(tok, new Set());
          tokens.get(tok).add(k);
        }
      });
    });
    const gKey = (t.genre || '').toLowerCase();
    if (gKey) {
      if (!genres.has(gKey)) genres.set(gKey, { name: t.genre, indices: [] });
      genres.get(gKey).indices.push(i);
    }
    const tKey = (t.title || '').toLowerCase();
    if (tKey) titles.push({ title: t.title, key: tKey, index: i, artist: t.artist });
  });
  _djIndex = { n: tracks.length, artists, performers, tokens, genres, titles };
  return _djIndex;
}

// Song title lookup: whole-word match for short titles, typo-tolerant only for longer ones
function _djFindTrack(msg) {
  const { titles } = _djBuildIndex();
  let best = null;
  for (const t of titles) {
    const hit = _djHas(msg, t.key) || (t.key.length >= 6 && _fuzzyIncludes(msg, t.key));
    if (hit && (!best || t.key.length > best.key.length)) best = t;
  }
  return best;
}

// Every artist named in the message — full name ("Sheebah Karungi") or just the
// distinctive part ("sheebah", "baraka"), with typo tolerance. Best match first.
function _djFindArtists(msg) {
  const { performers, tokens } = _djBuildIndex();
  const hits = new Map();
  const add = (k, score) => {
    const v = performers.get(k);
    if (!v) return;
    const cur = hits.get(k);
    if (!cur || cur.score < score) hits.set(k, { key: k, name: v.name, indices: v.indices, score });
  };
  for (const [k] of performers) {
    if (k.length >= 4 && _djHas(msg, k)) add(k, k.length * 2);
  }
  for (const [tok, keys] of tokens) {
    const direct = _djHas(msg, tok);
    const fuzzy = !direct && tok.length >= 5 && _fuzzyIncludes(msg, tok);
    if (direct || fuzzy) keys.forEach(k => add(k, direct ? 6 + tok.length * 0.1 : tok.length * 0.6));
  }
  // One person can be credited under several spellings ("Sheebah", "Sheebah Karungi") — merge them
  const merged = [];
  [...hits.values()].sort((a, b) => b.score - a.score).forEach(h => {
    const twin = merged.find(m => m.key.includes(h.key) || h.key.includes(m.key));
    if (twin) twin.indices = [...new Set(twin.indices.concat(h.indices))];
    else merged.push({ ...h, indices: h.indices.slice() });
  });
  return merged;
}
function _djFindArtist(msg) {
  const hits = _djFindArtists(msg);
  return hits.length ? hits[0] : null;
}

const _DJ_GENRE_ALIASES = { 'luganda': 'luganda pop', 'afro pop': 'afropop', 'afro beats': 'afrobeats', 'afrobeat': 'afrobeats', 'dance hall': 'dancehall', 'rnb': 'r&b', 'r and b': 'r&b', 'r n b': 'r&b' };
function _djFindGenre(msg) {
  const { genres } = _djBuildIndex();
  let best = null;
  for (const [key, val] of genres) {
    const hit = _djHas(msg, key) || (key.length >= 5 && _fuzzyIncludes(msg, key));
    if (hit && (!best || key.length > best.key.length)) best = { key, ...val };
  }
  if (!best) {
    for (const [alias, key] of Object.entries(_DJ_GENRE_ALIASES)) {
      if (genres.has(key) && _djHas(msg, alias)) { best = { key, ...genres.get(key) }; break; }
    }
  }
  return best;
}

function _djInfoReply(msg) {
  if (/what (can you|do you)|help me|how (do|does) (this|it|you) work|who are you|what are you|what can i (ask|say)/.test(msg)) {
    return "I'm YAPS AI. I build sets from the YAPS catalogue by mood or feeling (“I'm stressed”, “study time”), by artist (even two at once), by length (“45 minutes of party”), or by similarity (“songs like Yoyo”). I can also control playback (“volume 40”, “rewind 10 seconds”), set a sleep timer, save sets as playlists, and open pages like Playlists or Charts. Say “no gospel” or “don't play Rema again” to tune what I pick.";
  }
  if (/what artists|which artists|who.*(sing|available|got|have)|artist list/.test(msg)) {
    const names = [...new Set(tracks.map(t => t.artist))].slice(0, 12).join(', ');
    return `We've got a solid lineup: ${names}, and more. Just say a name and I'll queue their tracks!`;
  }
  if (/what genre|which genre|genres/.test(msg)) {
    const names = [...new Set(tracks.map(t => t.genre))].join(', ');
    return `Genres on YAPS right now: ${names}. Tell me which one you're feeling!`;
  }
  return null;
}

// ── Playback control commands — YAPS AI can drive the actual player, not just suggest tracks ──
function _djAdjustVolume(delta) {
  const cur = (typeof audioEngine !== 'undefined' && !isNaN(audioEngine.volume)) ? audioEngine.volume : 0.7;
  const vol = Math.max(0, Math.min(1, cur + delta));
  try { audioEngine.volume = vol; } catch (e) {}
  const fill = document.getElementById('volFill');
  if (fill) fill.style.width = (vol * 100) + '%';
  return vol;
}

function _djHandlePlaybackCommand(msg) {
  if (/\b(pause|stop the music|stop playing|hold on|stop it)\b/.test(msg)) {
    if (typeof isPlaying !== 'undefined' && isPlaying) { togglePlay(); return "Paused. Say “play” when you're ready."; }
    return "Already paused.";
  }
  if (/\b(resume|unpause|continue playing|keep playing|play it)\b/.test(msg)) {
    if (typeof isPlaying !== 'undefined' && !isPlaying) { togglePlay(); return "Back on. Enjoy!"; }
    return "Already playing.";
  }
  if (/\b(skip|next song|next track|skip this)\b/.test(msg)) {
    nextTrack();
    return "Skipped. Here's the next one.";
  }
  if (/\b(previous song|go back|last song|previous track)\b/.test(msg)) {
    prevTrack();
    return "Going back.";
  }
  if (/\bshuffle\b/.test(msg)) {
    const wantOff = /\b(off|stop)\b/.test(msg);
    if ((wantOff && shuffleOn) || (!wantOff && !shuffleOn)) toggleShuffle();
    return shuffleOn ? "Shuffle's on." : "Shuffle's off, playing in order.";
  }
  if (/\brepeat\b|\bloop (this|it)\b/.test(msg)) {
    toggleRepeat();
    const label = repeatMode === 0 ? 'off' : repeatMode === 1 ? 'all tracks' : 'this track';
    return `Repeat set to ${label}.`;
  }
  if (/\bvolume\b/.test(msg)) {
    if (/\b(up|higher|increase|max|full|louder)\b/.test(msg)) { _djAdjustVolume(0.15); return "Turned it up."; }
    if (/\b(down|lower|decrease|low|quiet|quieter)\b/.test(msg)) { _djAdjustVolume(-0.15); return "Turned it down."; }
  }
  if (/what('?s| is) (playing|this song|this track)|who (sings|made) this|now playing/.test(msg)) {
    const t = tracks[currentTrack];
    if (!t) return "Nothing's loaded yet, tell me a mood or artist and I'll get something going";
    return `${isPlaying ? "Playing now" : "Loaded (paused)"}: "${t.title}" by ${t.artist} · ${t.genre}`;
  }
  if (/\b(like this|love this|favorite this|add (this |it )?to (my )?(favorites|likes))\b/.test(msg)) {
    const t = tracks[currentTrack];
    if (!t) return "Nothing's playing yet to like. Get a set going first!";
    if (_likedTracks.has(currentTrack)) return `"${t.title}" is already in your likes.`;
    toggleLikeTrack(currentTrack);
    return `Added "${t.title}" to your likes!`;
  }
  if (/\b(unlike this|remove (this |it )?from (my )?(favorites|likes))\b/.test(msg)) {
    const t = tracks[currentTrack];
    if (t && _likedTracks.has(currentTrack)) { toggleLikeTrack(currentTrack); return `Removed "${t.title}" from your likes.`; }
    return "That one's not in your likes anyway.";
  }
  if (/\b(queue this|add (this |it )?to (the |my )?queue)\b/.test(msg)) {
    const t = tracks[currentTrack];
    if (!t) return "Nothing's playing yet to queue.";
    addToQueue(currentTrack);
    return `Queued "${t.title}"`;
  }
  if (/what'?s in (my |the )?queue|queue count|how many.*queue/.test(msg)) {
    if (!_queuedTracks.length) return "Your queue's empty right now. Want me to build a set?";
    return `You've got ${_queuedTracks.length} track${_queuedTracks.length === 1 ? '' : 's'} queued up`;
  }
  return null;
}

// ── YAPS AI ↔ real AI (ChatGPT / Claude) through your own server, so the secret key never reaches the browser ──
function _yaiEndpoint() { return YAPS_AI_URL || (_apiConfigured() ? YAPS_API_URL : ''); }
function _yaiShouldAsk(raw, result) {
  if (!_yaiEndpoint() || !_demoUser) return false;          // signed-in users only (keeps the cost under control)
  const m = String(raw || '').trim().toLowerCase();
  if (result && result.fallback) return true;                // the built-in engine didn't understand it
  if (/\b(play|queue|skip|next|previous|pause|resume|volume|timer|sleep|shuffle|repeat|playlist|save|louder|quieter|turn (it )?(up|down))\b/.test(m)) return false;
  if (/^(what'?s|what is) (playing|next|this)\b/.test(m)) return false;
  return /^(who|why|how|when|where|tell me|explain|what is|what'?s|what are|what does|what was|is |are |was |did |does |do you know|history of|meaning of|difference between)/.test(m);
}
async function _yaiAsk() {
  try {
    const history = _djChatHistory.slice(-10).map(h => ({ role: h.role === 'assistant' ? 'assistant' : 'user', content: String(h.content || '').replace(/<[^>]*>/g, '').slice(0, 600) })).filter(h => h.content);
    const cur = (typeof tracks !== 'undefined' && tracks[currentTrack]) ? tracks[currentTrack] : null;
    const body = {
      messages: history,
      catalogue: tracks.slice(0, 300).map((t, i) => ({ i, t: String(t.title || '').slice(0, 150), a: String(t.artist || '').slice(0, 100), g: String(t.genre || '').slice(0, 40) })),
      now_playing: cur ? (cur.title + ', ' + cur.artist) : null,
    };
    const headers = { 'Content-Type': 'application/json' };
    const { data } = await sb.auth.getSession();
    if (data && data.session) headers.Authorization = 'Bearer ' + data.session.access_token;
    const ctl = new AbortController(); const timer = setTimeout(() => ctl.abort(), 25000);
    const res = await fetch(_yaiEndpoint() + '/api/ai/chat', { method: 'POST', headers, body: JSON.stringify(body), signal: ctl.signal });
    clearTimeout(timer);
    if (res.status === 429) return { message: "You've used today's YAPS AI chat questions. Come back tomorrow, I can still build mixes and play music for you.", picks: [], dna: null, noAutoplay: true };
    if (!res.ok) return null;                                  // any problem: quietly fall back to the built-in answer
    const j = await res.json();
    const picks = (j.picks || []).filter(p => Number.isInteger(p.index) && tracks[p.index]).slice(0, 6).map(p => ({ index: p.index, reason: String(p.reason || '').slice(0, 90) }));
    const text = _djEsc(String(j.message || '')).replace(/\n/g, '<br>');
    if (!text) return null;
    return { message: text, picks, dna: null, noAutoplay: true, aiReply: true };
  } catch (e) { console.warn('YAPS AI (real) unavailable:', e && e.message); return null; }
}

async function callDJAI() {
  _djIsThinking = true;
  setDJStatus('thinking');

  const area = document.getElementById('djChatArea');
  const typingEl = document.createElement('div');
  typingEl.className = 'dj-message';
  typingEl.id = 'djTyping';
  typingEl.innerHTML = `
    <div class="dj-msg-avatar"></div>
    <div class="dj-msg-bubble"><div class="yai-typing" aria-label="YAPS AI is thinking"><span></span><span></span><span></span></div></div>`;
  area.appendChild(typingEl);
  area.scrollTop = area.scrollHeight;

  // Small delay so it feels considered, not instant
  await new Promise(r => setTimeout(r, 450 + Math.random() * 350));

  const lastUserMsgRaw = (_djChatHistory.filter(m => m.role === 'user').pop() || {}).content || '';
  const msg = lastUserMsgRaw.toLowerCase().replace(/[“”]/g, '"').replace(/[‘’]/g, "'");
  let result;
  try {
    const exclusions = _djExtractExclusions(msg);
    result = _djDecide(msg, exclusions);
  } catch (err) {
    console.error('YAPS AI error', err);
    result = { message: "Something went wrong on my side. Try that again, or ask for a mood or artist.", picks: [], dna: null };
  }

  // Open music questions go to the real AI; play/volume/timer/playlist commands stay with the built-in engine.
  if (_yaiShouldAsk(lastUserMsgRaw, result)) {
    const ai = await _yaiAsk();
    if (ai) result = ai;
  }

  _djMarkSeen(result.picks);
  _djChatHistory.push({ role: 'assistant', content: result.message });
  _djSaveHistory();
  if (result.picks && result.picks.length && !result.noAutoplay && !result.keepSet) {
    _djLastPicks = result.picks;
    _djLastLabel = result.label || _djTitleCase(lastUserMsgRaw).slice(0, 28);
  }

  const typing = document.getElementById('djTyping');
  if (typing) typing.remove();

  addDJResponse(result.message, result.picks, result.dna, { noAutoplay: !!result.noAutoplay });
  _djIsThinking = false;
  const playing = (result.picks && result.picks.length && !result.noAutoplay) || (typeof isPlaying !== 'undefined' && isPlaying);
  setDJStatus(playing ? 'playing' : 'idle');
}

// ── Pure decision engine — takes a lowercased message + exclusion list, returns
// {message, picks, dna}. No DOM access, no history mutation — this is what makes
// the whole intent chain independently testable (see /mnt/user-data/outputs test file). ──
// ══════════════ YAPS AI v2 — new understanding ══════════════
let _djLastLabel = '';
let _djPrevVol = null;

function _djSavePlaylist(indices, name) {
  const pl = { id: Date.now(), name, trackIndices: [...new Set(indices)].filter(i => tracks[i]) };
  _userPlaylists.push(pl);
  try { _persistSave(); } catch (e) {}
  return pl;
}

function _djSetVolume(v) {
  v = Math.max(0, Math.min(1, v));
  try { audioEngine.volume = v; } catch (e) {}
  const fill = document.getElementById('volFill');
  if (fill) fill.style.width = (v * 100) + '%';
  return v;
}

// "30 minutes", "1h 30m", "half an hour", "an hour" -> minutes
function _djTimerMinutes(msg) {
  if (/\bhalf an? hour\b/.test(msg)) return 30;
  let total = 0, m;
  m = msg.match(/(\d+(?:\.\d+)?)\s*(?:hours?|hrs?|hr|h)\b/);
  if (m) total += parseFloat(m[1]) * 60; else if (/\ban? hour\b/.test(msg)) total += 60;
  m = msg.match(/(\d+(?:\.\d+)?)\s*(?:minutes?|mins?|min|m)\b/);
  if (m) total += parseFloat(m[1]);
  if (!total) { m = msg.match(/\btimer\b\D{0,12}(\d+)/); if (m) total = parseInt(m[1], 10); }
  return total ? Math.max(1, Math.min(600, Math.round(total))) : null;
}

// "5", "ten" ... "top 3 sheebah songs", "give me 10 songs"
const _DJ_NUMWORDS = { one:1, two:2, three:3, four:4, five:5, six:6, seven:7, eight:8, nine:9, ten:10, twelve:12, fifteen:15, twenty:20 };
function _djParseN(msg) {
  const m = msg.match(/\b(\d{1,2}|one|two|three|four|five|six|seven|eight|nine|ten|twelve|fifteen|twenty)\s+(?:[a-z'&.]+\s+){0,3}?(?:songs?|tracks?|tunes?|bangers?|hits)\b/)
    || msg.match(/\btop\s+(\d{1,2}|three|five|ten)\b/);
  if (!m || /\b(minutes?|mins?|hours?|hrs?)\b/.test(m[0])) return null;
  const n = /^\d+$/.test(m[1]) ? parseInt(m[1], 10) : _DJ_NUMWORDS[m[1]];
  return n ? Math.max(1, Math.min(20, n)) : null;
}

// "30 minutes of gospel", "an hour of chill", "45 mins party mix" -> seconds (music length, not a timer)
function _djParseDuration(msg) {
  if (/\b(timer|sleep|stop|pause|turn off|switch off|shut off|rewind|forward|ahead|back)\b/.test(msg)) return null;
  if (!/\b(of|worth|long|mix|set|playlist|music|songs|session|for)\b/.test(msg)) return null;
  if (/\bhalf an? hour\b/.test(msg)) return 1800;
  let total = 0, m;
  m = msg.match(/(\d+(?:\.\d+)?|an?|one|two|three)\s*(?:hours?|hrs?|hr)\b/);
  if (m) total += (/^\d/.test(m[1]) ? parseFloat(m[1]) : (m[1] === 'two' ? 2 : m[1] === 'three' ? 3 : 1)) * 3600;
  m = msg.match(/(\d+(?:\.\d+)?)\s*(?:minutes?|mins?|min)\b/);
  if (m) total += parseFloat(m[1]) * 60;
  return total >= 300 ? Math.min(total, 4 * 3600) : null;
}

const _DJ_NAV = [
  [/\bnew releases?\b/, 'new-releases', 'New Releases'], [/\btrending videos?\b/, 'trending-videos', 'Trending Videos'],
  [/\b(library|likes page)\b/, 'library', 'your Library'], [/\bplaylists?\b/, 'playlists', 'Playlists'],
  [/\bcharts?\b/, 'charts', 'the Charts'], [/\bartists?\b/, 'artists', 'Artists'], [/\bexplore\b/, 'explore', 'Explore'],
  [/\bquick ?vibes\b/, 'quickvibes', 'Quick Vibes'], [/\bpodcasts?\b/, 'podcasts', 'Podcasts'], [/\bevents?\b/, 'events', 'Events'],
  [/\bmessages?\b|\binbox\b/, 'messages', 'Messages'], [/\bnotifications?\b/, 'notifications', 'Notifications'],
  [/\bsearch\b/, 'search', 'Search'], [/\bprofile\b/, 'profile', 'your Profile'], [/\bhome\b/, 'home', 'Home'],
  [/\bvideos?\b/, 'video', 'Videos']
];

const _DJ_ORD = { first:1, '1st':1, second:2, '2nd':2, third:3, '3rd':3, fourth:4, '4th':4, fifth:5, '5th':5, sixth:6, '6th':6 };

// Commands that act on the app (timer, volume, seek, navigation, queue, history) rather than build a set
function _djHandleExtraCommands(msg) {
  const say = (message, picks, extra) => Object.assign({ message, picks: picks || [], dna: null }, extra || {});

  // Sleep timer
  if (/\b(cancel|turn off|remove|clear|disable|stop)\b.*\b(sleep )?timer\b/.test(msg)) {
    cancelSleepTimer(false);
    return say("Sleep timer is off. Music will keep playing.");
  }
  const timerIntent = /\b(sleep timer|timer|stop playing|stop the music|stop music|pause|turn (?:it |the music )?off|switch (?:it |the music )?off|shut (?:it )?off)\b/.test(msg);
  if (timerIntent && /\b(after|at the end of|when)\b.*\b(this|the current)\s+(song|track)\b|\bend of (?:this |the )?(song|track)\b/.test(msg)) {
    setSleepTimer(0);
    return say("Done. I'll pause when this track ends.");
  }
  if (timerIntent && /\b(?:in|after|for)\b/.test(msg) || /\bsleep timer\b/.test(msg)) {
    const mins = _djTimerMinutes(msg);
    if (mins) {
      setSleepTimer(mins);
      const label = mins >= 60 && mins % 60 === 0 ? `${mins / 60} hour${mins === 60 ? '' : 's'}` : `${mins} minute${mins === 1 ? '' : 's'}`;
      return say(`Sleep timer set. I'll pause the music in ${label}.`);
    }
    if (/\btimer\b/.test(msg)) return say("How long should the timer run? Try “stop playing in 30 minutes”.");
  }

  // Volume to a level, mute / unmute
  const vm = msg.match(/\bvolume\s*(?:to|at|=)?\s*(\d{1,3})\b/) || msg.match(/\b(\d{1,3})\s*(?:%|percent)\s*volume\b/) || msg.match(/\b(?:set|put|make|turn)\b.{0,16}?\b(\d{1,3})\s*(?:%|percent)/);
  if (vm) {
    const pct = Math.max(0, Math.min(100, parseInt(vm[1], 10)));
    _djSetVolume(pct / 100);
    return say(pct === 0 ? "Volume at zero." : `Volume set to ${pct}%.`);
  }
  if (/\b(max(?:imum)? volume|full volume|volume (?:to )?max)\b/.test(msg)) { _djSetVolume(1); return say("Volume maxed out. Mind your ears."); }
  const mu = msg.match(/^\s*(mute|unmute|silence)(?:\s+(?:the\s+)?(?:volume|sound|music|it|audio))?\s*[.!]*$/);
  if (mu) {
    if (mu[1] === 'unmute') { _djSetVolume(_djPrevVol == null ? 0.7 : _djPrevVol); return say("Sound is back on."); }
    try { _djPrevVol = audioEngine.volume > 0 ? audioEngine.volume : (_djPrevVol == null ? 0.7 : _djPrevVol); } catch (e) {}
    _djSetVolume(0);
    return say("Muted. Say “unmute” when you want it back.");
  }

  // Seek / restart
  const sk = msg.match(/\b(forward|ahead|fast[- ]?forward|rewind|go back|back|jump back|jump forward)\s*(?:by\s*)?(\d+)\s*(seconds?|secs?|s|minutes?|mins?|min)\b/);
  if (sk) {
    let sec = parseInt(sk[2], 10) * (/^m/.test(sk[3]) ? 60 : 1);
    if (/rewind|back/.test(sk[1])) sec = -sec;
    try {
      const dur = audioEngine.duration;
      if (!isFinite(dur) || !dur) return say("I can't skip within this track. Seeking isn't available for it.");
      audioEngine.currentTime = Math.max(0, Math.min(dur - 1, audioEngine.currentTime + sec));
      return say(`${sec < 0 ? 'Rewound' : 'Skipped ahead'} ${Math.abs(sec)} second${Math.abs(sec) === 1 ? '' : 's'}.`);
    } catch (e) { return say("I couldn't seek on this one."); }
  }
  if (/\b(restart (this|the|it)|restart$|replay|start over|from the (start|beginning|top)|play (this|it|that) again|run it back)\b/.test(msg)) {
    try {
      audioEngine.currentTime = 0;
      if (typeof isPlaying !== 'undefined' && !isPlaying) togglePlay();
      return say("Back to the start.");
    } catch (e) { return say("I couldn't restart this one."); }
  }

  // Navigation: "open playlists", "go to charts", "take me to new releases"
  const nav = msg.match(/^\s*(?:please\s+)?(?:open|go to|take me to|navigate to|show me|bring up|switch to)\s+(?:the |my |to )?(.{2,30}?)\s*[.!]?$/);
  if (nav && nav[1].split(/\s+/).length <= 3 && !/\b(like|by|from|of|for|with)\b/.test(nav[1])) {
    for (const [re, page, label] of _DJ_NAV) {
      if (re.test(nav[1])) {
        setTimeout(() => navigate(page), 900);
        return say(`Opening ${label}.`);
      }
    }
  }

  // "play the second one", "play number 3" — acts on the set I just gave you
  if (_djLastPicks.length) {
    let pos = null;
    const om = msg.match(/\b(?:play|start|put on)\s+(?:the\s+)?(first|1st|second|2nd|third|3rd|fourth|4th|fifth|5th|sixth|6th|last)(?:\s+(?:one|song|track|pick))?\b/)
      || msg.match(/\b(?:play|start)\s+(?:track\s+)?(?:number|no\.?|#)\s*(\d{1,2})\b/);
    if (om) pos = om[1] === 'last' ? _djLastPicks.length : (_DJ_ORD[om[1]] || parseInt(om[1], 10));
    if (pos && _djLastPicks[pos - 1] && tracks[_djLastPicks[pos - 1].index]) {
      const p = _djLastPicks[pos - 1], t = tracks[p.index];
      return say(`Playing “${_djEsc(t.title)}” by ${_djEsc(t.artist)}, number ${pos} in the set.`, [{ index: p.index, reason: `#${pos} in your set` }], { keepSet: true });
    }
    if (/\b(queue (?:up )?(?:the |this |that )?(?:set|these|them|whole set)|add (?:the |this |that )?(?:set|these|them) to (?:my |the )?queue)\b/.test(msg)) {
      _djLastPicks.forEach(p => addToQueue(p.index));
      return say(`Queued ${_djLastPicks.length} track${_djLastPicks.length === 1 ? '' : 's'} from that set.`);
    }
  }

  if (/\b(?:play|start|put on)\s+(?:the\s+)?(?:first|1st|second|2nd|third|3rd|fourth|4th|fifth|5th|sixth|6th|last)\s+(?:one|song|track|pick)\b/.test(msg) && !_djLastPicks.length) {
    return say("I don't have a set to pick from yet. Ask for a mood or artist first, then say “play the second one”.");
  }

  // Listening history (real data)
  if (/\b(recently played|what did i (?:just )?(?:play|listen to)|my history|play history|listening history|last played|what i played)\b/.test(msg)) {
    const hist = (typeof _history !== 'undefined' ? _history : []).filter(i => tracks[i]).slice(0, 6);
    if (!hist.length) return say("Nothing in your history yet. Play a few tracks and I'll keep count.");
    return say("Here's what you played most recently.", hist.map(i => ({ index: i, reason: 'recently played' })), { noAutoplay: true });
  }

  // "Never play this artist" — mutes whoever is playing now, then skips
  if (/\b(never play|don'?t play|do not play|stop playing|ban|block)\b.*\b(this|that|current)\s+(artist|singer|musician)\b/.test(msg)) {
    const t = tracks[currentTrack];
    if (!t) return say("Nothing's playing right now, so there's no artist to mute.");
    const name = _djPerformers(t.artist)[0] || t.artist;
    _djMute(name.toLowerCase());
    try { nextTrack(); } catch (e) {}
    return say(`Done. No more ${_djEsc(name)} in my sets. Skipping to the next track.`);
  }
  return null;
}

const _djArtistExcluded = (a, exclusions) => (exclusions || []).some(ex => ex.length >= 3 && (a.key.includes(ex) || ex.includes(a.key)));

// Which part of the catalogue does the message ask for? artist(s) > genre > mood > everything
function _djPoolFor(msg, exclusions) {
  const ok = i => !_djIsExcluded(tracks[i], exclusions);
  const arts = _djFindArtists(msg).filter(a => a.score >= 6 && !_djArtistExcluded(a, exclusions));
  if (arts.length) {
    const top = arts.slice(0, 3);
    return { pool: [...new Set(top.flatMap(a => a.indices))].filter(ok), label: top.map(a => a.name).join(' + '), ranked: false };
  }
  const g = _djFindGenre(msg);
  if (g) return { pool: g.indices.filter(ok), label: g.name, ranked: false };
  const v = _localDJMatch(msg, exclusions);
  if (v) return { pool: _djRankByProfile(v.profile, exclusions), label: v.id === 'latenight' ? 'late-night' : v.id, ranked: true, dna: v.dna };
  return { pool: [...Array(tracks.length).keys()].filter(ok), label: 'YAPS favourites', ranked: false };
}

// Fills a set to roughly the requested length
function _djFillDuration(pool, ranked, targetSec) {
  const ordered = ranked ? pool.slice() : _djPickPreferUnseen(pool, pool.length);
  const picks = [];
  let total = 0;
  for (const i of ordered) {
    const s = _djSecs(tracks[i].duration);
    if (picks.length && total >= targetSec - 90) break;
    if (picks.length && total + s > targetSec + 150) continue;
    picks.push({ index: i, reason: tracks[i].duration });
    total += s;
    if (total >= targetSec) break;
  }
  return { picks, total };
}

// "Songs like Yoyo" / "similar to Sheebah"
function _djSimilar(msg, exclusions, N) {
  if (!/\b(like|similar to|sounds like|in the style of|reminds me of|vibe of|same as|in the lane of)\b/.test(msg)) return null;
  const GENERIC = new Set(['Uganda', 'New', 'Trending', 'Weekend', 'Popular']);
  const tr = _djFindTrack(msg);
  const arts = _djFindArtists(msg).filter(a => a.score >= 6 && !_djArtistExcluded(a, exclusions));
  const want = N || 6;
  if (tr) {
    const src = tracks[tr.index];
    const srcPerf = _djPerformers(src.artist).map(s => s.toLowerCase());
    const scored = [];
    tracks.forEach((t, i) => {
      if (i === tr.index || _djIsExcluded(t, exclusions)) return;
      let s = 0;
      if (t.genre === src.genre) s += 3;
      (t.tags || []).forEach(tg => { if (!GENERIC.has(tg) && (src.tags || []).includes(tg)) s += 1.2; });
      if (_djPerformers(t.artist).some(p => srcPerf.includes(p.toLowerCase()))) s += 1.5;
      if (t.region === src.region) s += 0.5;
      s += 0.5 * (1 - Math.min(1, Math.abs(_djSecs(t.duration) - _djSecs(src.duration)) / 120));
      if (!_djSessionSeen.has(i)) s += 0.6;
      scored.push([s + Math.random() * 0.8, i]);
    });
    const picks = scored.sort((a, b) => b[0] - a[0]).slice(0, want).map(x => ({ index: x[1], reason: `like “${src.title}”` }));
    if (picks.length) return { message: `If you like “${_djEsc(src.title)}” by ${_djEsc(src.artist)}, these sit right next to it.`, picks, dna: null, label: `Like ${src.title}` };
  }
  if (arts.length) {
    const a = arts[0];
    const own = new Set(a.indices);
    const gset = new Set(a.indices.map(i => tracks[i].genre));
    const tset = new Set(a.indices.flatMap(i => (tracks[i].tags || []).filter(tg => !GENERIC.has(tg))));
    const scored = [];
    tracks.forEach((t, i) => {
      if (own.has(i) || _djIsExcluded(t, exclusions)) return;
      let s = gset.has(t.genre) ? 3 : 0;
      (t.tags || []).forEach(tg => { if (tset.has(tg)) s += 1; });
      if (!_djSessionSeen.has(i)) s += 0.6;
      if (s > 0) scored.push([s + Math.random() * 0.8, i]);
    });
    const picks = scored.sort((a, b) => b[0] - a[0]).slice(0, want).map(x => ({ index: x[1], reason: `in ${a.name}'s lane` }));
    if (picks.length) return { message: `Not ${_djEsc(a.name)}, but in the same lane.`, picks, dna: null, label: `Like ${a.name}` };
  }
  return null;
}

function _djDidYouMean(msg) {
  const { tokens } = _djBuildIndex();
  const words = msg.split(/[^a-z0-9']+/).filter(w => w.length >= 4);
  let best = null;
  for (const w of words) {
    for (const [tok, keys] of tokens) {
      const d = _lev(w, tok);
      if (d > 0 && d <= (tok.length >= 7 ? 2 : 1) && (!best || d < best.d)) best = { d, name: performersName(keys) };
    }
  }
  return best ? best.name : null;
  function performersName(keys) { const k = [...keys][0]; const p = _djBuildIndex().performers.get(k); return p ? p.name : null; }
}

// ── The decision engine: lowercased message + exclusions -> {message, picks, dna, label?, noAutoplay?} ──
function _djDecide(msg, exclusions, depth) {
  depth = depth || 0;
  let result = null;
  const N = _djParseN(msg);

  // 0) App commands: sleep timer, volume level, seek, navigation, "play the second one", history…
  if (!result) { const ext = _djHandleExtraCommands(msg); if (ext) result = ext; }

  // "more like this" / "songs like this" is a request for similar music, not "like this song"
  const moreLike = /\b(more|songs?|something|music|tracks?|anything|stuff)\s+like\s+(this|that|it)\b/.test(msg);

  // 0.1) Basic playback — pause/play/skip/shuffle/repeat/like/queue
  const skipExclusion = /^\s*skip\s+(?!this|it|that|the|to|ahead|forward|back|song|track|next|one|a\b)[a-z]/.test(msg);
  if (!result && !moreLike && !skipExclusion) {
    const control = _djHandlePlaybackCommand(msg);
    if (control) result = { message: control, picks: [], dna: null };
  }

  // 0.3) Permanent mute — "don't play Rema again", "unmute everything"
  if (!result) {
    if (/\b(unmute everything|remove all mutes|reset mutes|play everything again)\b/.test(msg)) {
      _djUnmuteAll();
      result = { message: "All good. Nothing's muted anymore and the full catalogue is back in play.", picks: [], dna: null };
    } else {
      const muteMatch = msg.match(/\b(?:don'?t play|never play|mute)\s+([a-z0-9' ]{2,30}?)(?:\s+(?:again|anymore|please))?$/);
      if (muteMatch) {
        const target = muteMatch[1].trim();
        _djMute(target);
        result = { message: `Got it. I won't bring up “${_djEsc(target)}” again.`, picks: [], dna: null };
      }
    }
  }

  // 0.5) Smalltalk
  if (!result) { const chat = _djSmalltalk(msg); if (chat) result = { message: chat, picks: [], dna: null }; }

  // 0.6) Playlists: "save this set", "make a playlist called Sunday", "make a playlist of gospel", "add this to my playlist X"
  if (!result) {
    const addTo = msg.match(/\badd (?:this|it|the current(?: song| track)?|this (?:song|track)) to (?:my |the )?(?:playlist )?(.+?)(?: playlist)?\s*[.!]?$/);
    if (addTo && !/\b(queue|favou?rites?|likes?|liked)\b/.test(addTo[1])) {
      const want = addTo[1].trim();
      const pl = _userPlaylists.find(p => p.name.toLowerCase() === want || p.name.toLowerCase().includes(want));
      const t = tracks[currentTrack];
      if (!pl) result = { message: `I couldn't find a playlist called “${_djEsc(want)}”. Say “make a playlist called ${_djEsc(want)}” and I'll create it.`, picks: [], dna: null };
      else if (!t) result = { message: "Nothing's playing yet, so there's nothing to add.", picks: [], dna: null };
      else if (pl.trackIndices.includes(currentTrack)) result = { message: `“${_djEsc(t.title)}” is already in ${_djEsc(pl.name)}.`, picks: [], dna: null };
      else { pl.trackIndices.push(currentTrack); try { _persistSave(); } catch (e) {} result = { message: `Added “${_djEsc(t.title)}” to ${_djEsc(pl.name)}.`, picks: [], dna: null }; }
    } else if (depth === 0 && (/\b(make|create|build|start)\b.*\bplaylist\b/.test(msg) || /\bsave (?:this|the|that)\s+(?:set|mix|playlist|one)\b/.test(msg) || /\bsave (?:it|these|them) (?:as|to) (?:a )?(?:my )?playlist\b/.test(msg))) {
      const named = msg.match(/\b(?:called|named|titled)\s+["“']?([^"”']{1,40})/);
      const name = named ? _djTitleCase(named[1]) : null;
      const rest = msg.replace(/\b(make|create|build|start|save|me|a|an|my|new|the|this|that|set|mix|playlist|playlists|of|with|for|please|called|named|titled)\b/g, ' ').replace(/["“”'].*$/, '').replace(/\s+/g, ' ').trim();
      if (rest.length >= 3 && !named) {
        const inner = _djDecide(rest, exclusions, 1);
        if (inner && inner.picks && inner.picks.length) {
          const pl = _djSavePlaylist(inner.picks.map(p => p.index), `${_djTitleCase(rest).slice(0, 28)} · YAPS AI`);
          result = { message: `Made a playlist, “${_djEsc(pl.name)}”, with ${pl.trackIndices.length} tracks. Find it under Playlists.`, picks: inner.picks, dna: inner.dna, label: _djTitleCase(rest).slice(0, 28), noAutoplay: true };
        }
      }
      if (!result) {
        if (_djLastPicks.length) {
          const pl = _djSavePlaylist(_djLastPicks.map(p => p.index), name || `${_djLastLabel || 'YAPS AI Mix'} · YAPS AI`);
          result = { message: `Saved “${_djEsc(pl.name)}” with ${pl.trackIndices.length} tracks. Find it under Playlists.`, picks: [], dna: null };
        } else {
          result = { message: "Tell me what the playlist should sound like first, for example “make a playlist of gospel”.", picks: [], dna: null };
        }
      }
    }
  }

  // 0.65) Catalogue facts: counts, "tell me about <artist>"
  if (!result) {
    const cnt = msg.match(/\bhow many (songs|tracks|artists|genres)\b/);
    if (cnt) {
      const idx = _djBuildIndex();
      const nArt = idx.performers.size, nGen = idx.genres.size;
      result = { message: `There are ${tracks.length} tracks from ${nArt} artists across ${nGen} genres (${[...idx.genres.values()].map(g => g.name).join(', ')}).`, picks: [], dna: null };
    }
    const about = msg.match(/\b(?:tell me about|who is|who'?s|info on|what do you know about|about)\s+(.{2,40})$/);
    if (!result && about) {
      const a = _djFindArtist(about[1]);
      if (a && a.score >= 6) {
        const genresOf = [...new Set(a.indices.map(i => tracks[i].genre))].join(', ');
        const picks = a.indices.slice(0, 4).map(i => ({ index: i, reason: 'by ' + a.name }));
        _djRememberPreference('artist', a.name);
        result = { message: `${_djEsc(a.name)}: ${a.indices.length} track${a.indices.length === 1 ? '' : 's'} on YAPS, in ${_djEsc(genresOf)}. Tap one to play.`, picks, dna: null, noAutoplay: true };
      }
    }
  }

  // 0.7) "Surprise me"
  if (!result && /\b(surprise me|shuffle everything|anything is fine|you pick|you choose|whatever you want|dealer'?s choice|blow my mind)\b/.test(msg)) {
    const pool = [...Array(tracks.length).keys()].filter(i => !_djIsExcluded(tracks[i], exclusions));
    const picks = _djPickPreferUnseen(pool.length ? pool : [...Array(tracks.length).keys()], N || 6).map(i => ({ index: i, reason: 'surprise pick' }));
    result = { message: "Say no more. Full catalogue shuffle, whatever comes up comes up!", picks, dna: { energy:70, danceability:72, mood:68, tempo:68, Uganda_factor:93 }, label: 'Surprise mix' };
  }

  // 0.8) Your likes
  if (!result && /\b(my liked|my likes|my favorites|my favourites|my favourite songs|liked songs|songs i liked|things i liked)\b/.test(msg)) {
    const likedIdx = [..._likedTracks].filter(i => tracks[i] && !_djIsExcluded(tracks[i], exclusions));
    if (likedIdx.length) {
      const picks = _pickRandom(likedIdx, Math.min(N || 6, likedIdx.length)).map(i => ({ index: i, reason: 'from your likes' }));
      result = { message: "Here's a run through your liked tracks.", picks, dna: { energy:75, danceability:78, mood:80, tempo:74, Uganda_factor:95 }, label: 'Your likes' };
    } else {
      result = { message: "You haven't liked anything yet. Tap the heart on a track and I'll build sets from your favourites.", picks: [], dna: null };
    }
  }

  // 0.9) Personal recommendations from real likes
  if (!result && /\b(recommend (?:something|me|a song|some)|something i('d| would) like|based on my taste|know what i like|suggest (?:something|me|a song)|what should i (?:listen|play))\b/.test(msg)) {
    const likedIdx = [..._likedTracks].filter(i => tracks[i]);
    if (likedIdx.length >= 2) {
      const genreCounts = {};
      likedIdx.forEach(i => { genreCounts[tracks[i].genre] = (genreCounts[tracks[i].genre] || 0) + 1; });
      const topGenre = Object.entries(genreCounts).sort((a, b) => b[1] - a[1])[0];
      if (topGenre) {
        const { genres } = _djBuildIndex();
        const ge = genres.get(topGenre[0].toLowerCase());
        const candidates = (ge ? ge.indices : [...Array(tracks.length).keys()]).filter(i => !_likedTracks.has(i) && !_djIsExcluded(tracks[i], exclusions));
        if (candidates.length) {
          const picks = _djPickPreferUnseen(candidates, Math.min(N || 6, candidates.length)).map(i => ({ index: i, reason: `matches your ${topGenre[0]} taste` }));
          result = { message: `You're clearly into ${_djEsc(topGenre[0])}. Here's more you haven't liked yet.`, picks, dna: { energy:73, danceability:76, mood:74, tempo:72, Uganda_factor:94 }, label: 'For you' };
        }
      }
    }
    if (!result && likedIdx.length < 2) {
      const picks = _djPickPreferUnseen([...Array(tracks.length).keys()].filter(i => !_djIsExcluded(tracks[i], exclusions)), 6).map(i => ({ index: i, reason: 'to get to know your taste' }));
      result = { message: "I don't know your taste yet. Like a couple of tracks and I'll tailor sets to you. Here's a mix to start.", picks, dna: null, label: 'Starter mix' };
    }
  }

  // 1) Energy refinement
  if (!result && /\b(turn it up|more energy|pump it up|faster|hype it up|crank it)\b/.test(msg)) {
    const v = _djVibeDB.find(x => x.id === 'hype');
    const picks = _djRankByProfile(v.profile, exclusions).slice(0, N || 6).map(i => ({ index: i, reason: 'more energy' }));
    result = { message: "Say less. Cranking the energy up!", picks, dna: v.dna, label: 'More energy' };
  }
  if (!result && /\b(chill it down|less energy|slow it down|slower|calm it down|tone it down)\b/.test(msg)) {
    const v = _djVibeDB.find(x => x.id === 'chill');
    const picks = _djRankByProfile(v.profile, exclusions).slice(0, N || 6).map(i => ({ index: i, reason: 'dialled back' }));
    result = { message: "Easing off the throttle. Here's something smoother.", picks, dna: v.dna, label: 'Dialled back' };
  }

  // 1.5) "Something different" — leaves the genre of the last set
  if (!result && /\b(something different|different vibe|change it up|switch it up|mix it up|something else|not this|change the vibe|switch lanes)\b/.test(msg)) {
    const lastGenres = new Set(_djLastPicks.map(p => tracks[p.index] && tracks[p.index].genre).filter(Boolean));
    let pool = [...Array(tracks.length).keys()].filter(i => !lastGenres.has(tracks[i].genre) && !_djIsExcluded(tracks[i], exclusions));
    if (pool.length < 4) pool = [...Array(tracks.length).keys()].filter(i => !_djIsExcluded(tracks[i], exclusions));
    const picks = _djPickPreferUnseen(pool, N || 6).map(i => ({ index: i, reason: tracks[i].genre }));
    result = {
      message: lastGenres.size ? `Switching lanes. Leaving ${[...lastGenres].map(_djEsc).join(' and ')} behind.` : "Mixing it up. Here's something different.",
      picks, dna: { energy:60, danceability:65, mood:60, tempo:62, Uganda_factor:88 }, label: 'Something different'
    };
  }

  // 1.6) What's new — newest uploads first
  if (!result && /\b(what'?s new|new songs?|new releases?|new music|new tracks?|latest|newest|just dropped|fresh (?:songs?|music|tracks?)|recently added)\b/.test(msg)) {
    const newest = [...Array(tracks.length).keys()].filter(i => !_djIsExcluded(tracks[i], exclusions))
      .sort((a, b) => (Number(tracks[b].id) || 0) - (Number(tracks[a].id) || 0)).slice(0, N || 6);
    result = { message: "Fresh on YAPS. These are the newest uploads.", picks: newest.map(i => ({ index: i, reason: 'new' })), dna: { energy:75, danceability:78, mood:75, tempo:74, Uganda_factor:94 }, label: 'New on YAPS' };
  }

  // 1.7) Length filters — "songs under 3 minutes", "shortest songs", "longest tracks"
  if (!result) {
    const under = msg.match(/\b(?:under|less than|shorter than|below)\s+(\d+(?:\.\d+)?)\s*(?:min|minutes?)\b/);
    const over = msg.match(/\b(?:over|more than|longer than|above)\s+(\d+(?:\.\d+)?)\s*(?:min|minutes?)\b/);
    const shortest = /\b(shortest|short songs?|short tracks?|quick songs?|quick tracks?)\b/.test(msg);
    const longest = /\b(longest|long songs?|long tracks?)\b/.test(msg);
    if (under || over || shortest || longest) {
      const base = _djPoolFor(msg, exclusions);
      let pool = base.pool.slice();
      if (under) pool = pool.filter(i => _djSecs(tracks[i].duration) < parseFloat(under[1]) * 60);
      if (over) pool = pool.filter(i => _djSecs(tracks[i].duration) > parseFloat(over[1]) * 60);
      if (shortest) pool.sort((a, b) => _djSecs(tracks[a].duration) - _djSecs(tracks[b].duration));
      else if (longest) pool.sort((a, b) => _djSecs(tracks[b].duration) - _djSecs(tracks[a].duration));
      else pool = _djPickPreferUnseen(pool, pool.length);
      pool = pool.slice(0, N || 6);
      if (pool.length) {
        const what = under ? `under ${under[1]} minutes` : over ? `over ${over[1]} minutes` : shortest ? 'the shortest' : 'the longest';
        result = { message: `Here are ${what}${base.label === 'YAPS favourites' ? '' : ' in ' + _djEsc(base.label)}.`, picks: pool.map(i => ({ index: i, reason: tracks[i].duration })), dna: null, label: _djTitleCase(what) };
      }
    }
  }

  // 1.8) "Songs like Yoyo", "similar to Sheebah"
  if (!result) { const sim = _djSimilar(msg, exclusions, N); if (sim) result = sim; }
  // "more like this" with no previous set -> similar to what's playing now
  if (!result && moreLike && !_djLastPicks.length && tracks[currentTrack]) {
    const sim = _djSimilar('songs like ' + tracks[currentTrack].title.toLowerCase(), exclusions, N);
    if (sim) result = sim;
  }

  // 1.9) Sets by length — "30 minutes of gospel", "an hour of chill"
  if (!result) {
    const secs = _djParseDuration(msg);
    if (secs) {
      const base = _djPoolFor(msg, exclusions);
      const { picks, total } = _djFillDuration(base.pool.length ? base.pool : [...Array(tracks.length).keys()], base.ranked, secs);
      if (picks.length) {
        const mins = Math.round(total / 60);
        const asked = Math.round(secs / 60);
        const short = total < secs - 150;
        result = {
          message: short
            ? `That's everything I have for ${_djEsc(base.label)}: ${mins} minutes across ${picks.length} tracks (you asked for ${asked}).`
            : `${mins} minutes of ${_djEsc(base.label)}, ${picks.length} tracks, ready to go.`,
          picks, dna: base.dna || null, label: `${asked} min ${base.label}`
        };
      }
    }
  }

  if (!result && /^\s*(?:an?|\d+(?:\.\d+)?)\s*(?:minutes?|mins?|hours?|hrs?|hour)\s*[.!?]*\s*$/.test(msg)) {
    result = { message: "What should I fill it with? Try “30 minutes of gospel” or “an hour of chill”.", picks: [], dna: null };
  }

  // 2) Direct song — "play Yoyo", "put on Sissa"
  if (!result) {
    const trackHit = _djFindTrack(msg);
    if (trackHit && /\b(play|put on|queue|start|listen to)\b/.test(msg)) {
      result = { message: `${_djEsc(trackHit.title)} by ${_djEsc(trackHit.artist)}, playing now.`, picks: [{ index: trackHit.index, reason: 'requested track' }], dna: null, label: trackHit.title };
    }
  }

  // 2.5) Two or more artists — back-to-back mix
  if (!result) {
    const arts = _djFindArtists(msg).filter(a => a.score >= 6 && !_djArtistExcluded(a, exclusions));
    const distinct = [];
    arts.forEach(a => { if (!distinct.some(d => d.indices.join() === a.indices.join())) distinct.push(a); });
    if (distinct.length >= 2) {
      const top = distinct.slice(0, 3);
      const lists = top.map(a => _djFilterExcluded(a.indices.map(i => ({ index: i, reason: 'by ' + a.name })), exclusions));
      const mixed = [];
      for (let r = 0; mixed.length < (N || 8) && lists.some(l => r < l.length); r++) lists.forEach(l => { if (r < l.length && mixed.length < (N || 8)) mixed.push(l[r]); });
      if (mixed.length) {
        top.forEach(a => _djRememberPreference('artist', a.name));
        const names = top.map(a => a.name).join(' + ');
        result = { message: `${_djEsc(names)}, back to back.`, picks: mixed, dna: { energy:75, danceability:78, mood:75, tempo:74, Uganda_factor:96 }, label: names };
      }
    }
  }

  // 3) Artist + genre — "gospel from Wilson Bugembe"
  if (!result) {
    const artistHit = _djFindArtist(msg);
    const genreHit = _djFindGenre(msg);
    if (artistHit && artistHit.score >= 6 && genreHit && !_djArtistExcluded(artistHit, exclusions)) {
      const overlap = artistHit.indices.filter(i => genreHit.indices.includes(i));
      if (overlap.length) {
        const picks = _djFilterExcluded(overlap.slice(0, N || 6).map(i => ({ index: i, reason: `${genreHit.name} · ${artistHit.name}` })), exclusions);
        if (picks.length) {
          _djRememberPreference('artist', artistHit.name);
          _djRememberPreference('genre', genreHit.name);
          result = { message: `${_djEsc(artistHit.name)}'s ${_djEsc(genreHit.name)} tracks, coming up.`, picks, dna: { energy:72, danceability:76, mood:72, tempo:72, Uganda_factor:95 }, label: `${artistHit.name} ${genreHit.name}` };
        }
      }
    }
  }

  // 3.5) Batch queue — "queue all of Sheebah"
  if (!result && /\b(queue (all|everything)|add (all|everything)( of| from)?)\b/.test(msg)) {
    const artistHit = _djFindArtist(msg);
    if (artistHit && !_djArtistExcluded(artistHit, exclusions)) {
      const items = _djFilterExcluded(artistHit.indices.map(i => ({ index: i, reason: `by ${artistHit.name}` })), exclusions);
      items.forEach(p => addToQueue(p.index));
      _djRememberPreference('artist', artistHit.name);
      result = { message: `Queued all ${items.length} ${_djEsc(artistHit.name)} tracks. Check your queue!`, picks: items.slice(0, 6), dna: { energy:75, danceability:78, mood:75, tempo:74, Uganda_factor:96 }, label: artistHit.name, noAutoplay: true };
    }
  }

  // 4) Artist (works for any performer in the catalogue, by first name, last name or full name)
  if (!result) {
    const artistHit = _djFindArtist(msg);
    if (artistHit && artistHit.score >= 4 && !_djArtistExcluded(artistHit, exclusions)) {
      const picks = _djFilterExcluded(artistHit.indices.slice(0, N || 6).map(i => ({ index: i, reason: `by ${artistHit.name}` })), exclusions);
      if (picks.length) {
        _djRememberPreference('artist', artistHit.name);
        result = { message: `${_djEsc(artistHit.name)}! Here's what we've got from them.`, picks, dna: { energy:75, danceability:78, mood:75, tempo:74, Uganda_factor:96 }, label: artistHit.name };
      }
    }
  }

  // 5) Genre
  if (!result) {
    const genreHit = _djFindGenre(msg);
    const genreExcluded = genreHit && exclusions.some(ex => genreHit.key.includes(ex) || ex.includes(genreHit.key));
    if (genreHit && !genreExcluded && !_localDJMatch(msg, exclusions)) {
      const picks = _djFilterExcluded(_djPickPreferUnseen(genreHit.indices, Math.min(N || 6, genreHit.indices.length)).map(i => ({ index: i, reason: genreHit.name })), exclusions);
      if (picks.length) {
        _djRememberPreference('genre', genreHit.name);
        result = { message: `${_djEsc(genreHit.name)} it is. Here's a set pulled straight from that genre.`, picks, dna: { energy:70, danceability:74, mood:70, tempo:70, Uganda_factor:90 }, label: genreHit.name };
      }
    }
  }

  // 5.5) Trending / most popular
  if (!result && /\b(trending|popular|most played|top songs|top tracks|hits|biggest songs|chart)\b/.test(msg)) {
    const ranked = [...Array(tracks.length).keys()].filter(i => !_djIsExcluded(tracks[i], exclusions))
      .sort((a, b) => {
        const d = _djParseCount(tracks[b].plays) - _djParseCount(tracks[a].plays);
        if (d) return d;
        return ((tracks[b].tags || []).includes('Trending') ? 1 : 0) - ((tracks[a].tags || []).includes('Trending') ? 1 : 0);
      });
    if (ranked.length) {
      result = { message: "Here's what's hottest on YAPS right now.", picks: ranked.slice(0, N || 6).map(i => ({ index: i, reason: (tracks[i].tags || []).includes('Trending') ? 'trending' : `${tracks[i].plays} plays` })), dna: { energy:80, danceability:82, mood:78, tempo:78, Uganda_factor:96 }, label: 'Trending' };
    }
  }

  // 6) "More / another / similar" — continues the last set without repeats
  if (!result && (moreLike || /\b(more|again|another|keep going|continue|similar|same vibe)\b/.test(msg)) && _djLastPicks.length) {
    const used = new Set(_djLastPicks.map(p => p.index));
    const lastG = {};
    _djLastPicks.forEach(p => { const g = tracks[p.index] && tracks[p.index].genre; if (g) lastG[g] = (lastG[g] || 0) + 1; });
    const topG = Object.entries(lastG).sort((a, b) => b[1] - a[1])[0];
    let pool = [...Array(tracks.length).keys()].filter(i => !used.has(i) && !_djIsExcluded(tracks[i], exclusions));
    const sameGenre = topG ? pool.filter(i => tracks[i].genre === topG[0]) : [];
    if (sameGenre.length >= 4) pool = sameGenre;
    const picks = _djPickPreferUnseen(pool, Math.min(N || 6, pool.length)).map(i => ({ index: i, reason: 'more of that energy' }));
    if (picks.length) result = { message: "More where that came from. Same wavelength, fresh tracks.", picks, dna: { energy:70, danceability:72, mood:68, tempo:70, Uganda_factor:90 }, label: _djLastLabel ? `More ${_djLastLabel}` : 'More of that' };
  }

  // 7) Moods, activities, feelings
  if (!result) {
    const match = _localDJMatch(msg, exclusions);
    if (match) {
      const want = N || 6;
      let idx = _djRankByProfile(match.profile, exclusions).slice(0, want);
      if (idx.length < Math.min(4, want)) {
        const rest = [...Array(tracks.length).keys()].filter(i => !idx.includes(i) && !_djIsExcluded(tracks[i], exclusions));
        idx = idx.concat(_pickRandom(rest, Math.min(4, want) - idx.length));
      }
      result = {
        message: match.messages[Math.floor(Math.random() * match.messages.length)],
        picks: idx.map(i => ({ index: i, reason: match.why })),
        dna: match.dna,
        label: _djTitleCase(match.id === 'latenight' ? 'late night' : match.id)
      };
    }
  }

  // 8) Questions about me / the catalogue
  if (!result) { const info = _djInfoReply(msg); if (info) result = { message: info, picks: [], dna: null }; }

  // 9) Fallback — never a dead end
  if (!result) {
    const ask = msg.match(/\b(?:play|songs? by|music by|something by|anything by|put on|listen to|i want|i wanna)\s+(?:some\s+)?([a-z0-9' ]{2,30})$/);
    const topArtist = _djTopPreference('artist');
    const { performers } = _djBuildIndex();
    let pool = [...Array(tracks.length).keys()].filter(i => !_djIsExcluded(tracks[i], exclusions));
    let message = "I didn't catch a mood, artist or genre in that, so here's a solid mix to get you going. Try “chill”, “Sheebah”, or “30 minutes of gospel”.";
    let label = 'YAPS mix';
    const genericAsk = ask && /^(something|anything|some music|music|songs?|a song|a track|me something|some songs?)\b/.test(ask[1].trim());
    if (exclusions && exclusions.length && !ask) {
      message = `Noted, I'll leave ${_djEsc(exclusions[0])} out. Here's a mix without it. Tell me a mood or artist for something sharper.`;
    }
    if (genericAsk) message = "Here's something to get you going. Tell me a mood, artist or genre for a sharper pick.";
    if (ask && !genericAsk) {
      const target = ask[1].trim();
      const guess = _djDidYouMean(target);
      message = guess
        ? `I couldn't find “${_djEsc(target)}”. Did you mean ${_djEsc(guess)}? Here's a mix in the meantime.`
        : `I couldn't find “${_djEsc(target)}” in the catalogue yet. Here's a mix in the meantime, or tell me a mood, genre or another artist.`;
    } else if (topArtist && !(exclusions && exclusions.length) && performers.has(topArtist.toLowerCase())) {
      const fav = performers.get(topArtist.toLowerCase()).indices.filter(i => !_djIsExcluded(tracks[i], exclusions));
      if (fav.length && !(exclusions && exclusions.length)) { pool = fav; message = genericAsk ? `Starting with ${_djEsc(topArtist)}, since you keep coming back to them.` : `Not sure what you mean, but since you keep coming back to ${_djEsc(topArtist)}, here's more.`; label = topArtist; }
    }
    const picks = _djPickPreferUnseen(pool.length ? pool : [...Array(tracks.length).keys()], N || 5).map(i => ({ index: i, reason: 'Uganda vibes' }));
    result = { message, picks, dna: { energy:65, danceability:68, mood:65, tempo:65, Uganda_factor:92 }, label, fallback: true };
  }

  return result;
}

function addDJMessage(text, isUser) {
  const area = document.getElementById('djChatArea');
  if (isUser) { const caps = document.getElementById('yaiCaps'); if (caps) caps.remove(); }
  const div = document.createElement('div');
  div.className = 'dj-message' + (isUser ? ' user' : '');
  div.innerHTML = `
    <div class="dj-msg-avatar"></div>
    <div class="dj-msg-bubble">${isUser ? _djEsc(text) : text}</div>
  `;
  area.appendChild(div);
  area.scrollTop = area.scrollHeight;
}

// Sets are kept here (not in inline onclick JSON) so buttons stay small and safe
let _djSetSeq = 0;
const _djSets = {};

function djPlaySet(id) {
  const s = _djSets[id];
  if (s) djQueueAll(s.picks);
}

function djSaveSet(id) {
  const s = _djSets[id];
  if (!s) return;
  const name = `${s.label || 'YAPS AI Mix'} · YAPS AI`;
  _djSavePlaylist(s.picks.map(p => p.index), name);
  const b = document.getElementById('yaiSave' + id);
  if (b) { b.innerHTML = '<i class="fas fa-check"></i> Saved'; b.disabled = true; }
  showToast(`Saved “${name}” to Playlists`);
}

function addDJResponse(text, picks, dna, opts) {
  opts = opts || {};
  const area = document.getElementById('djChatArea');
  const list = (picks || []).filter(p => tracks[p.index]);
  const SHOW = 6;
  const autoplay = !opts.noAutoplay && list.length > 0;

  const cards = list.slice(0, SHOW).map((p, i) => {
    const t = tracks[p.index];
    const now = autoplay && i === 0;
    return `
      <div class="dj-msg-track${now ? ' is-now' : ''}" role="button" tabindex="0" title="Play now"
           onclick="playTrack(${p.index})" onkeydown="if(event.key==='Enter'){playTrack(${p.index})}">
        <div class="dj-msg-track-art"><img src="${_djEsc(t.img)}" alt="" loading="lazy">${now ? '<span class="yai-eq"><i></i><i></i><i></i></span>' : ''}</div>
        <div class="yai-trk-main">
          <div class="yai-trk-title">${_djEsc(t.title)}</div>
          <div class="yai-trk-sub">${_djEsc(t.artist)} · ${_djEsc(t.genre)}</div>
          ${p.reason ? `<div class="yai-trk-why">${_djEsc(p.reason)}</div>` : ''}
        </div>
        <div class="yai-trk-end"><span class="yai-trk-play"><i class="fas fa-play"></i></span><span class="yai-trk-dur">${_djEsc(t.duration)}</span></div>
      </div>`;
  }).join('');
  const more = list.length > SHOW ? `<div class="yai-more">+ ${list.length - SHOW} more in this set</div>` : '';

  let actions = '';
  if (list.length > 1) {
    const sid = ++_djSetSeq;
    _djSets[sid] = { picks: list, label: _djLastLabel || 'YAPS AI Mix' };
    actions = `
      <div class="yai-actions">
        <button type="button" class="yai-btn primary" onclick="djPlaySet(${sid})"><i class="fas fa-play"></i> Play set · ${list.length} tracks</button>
        <button type="button" class="yai-btn" id="yaiSave${sid}" onclick="djSaveSet(${sid})"><i class="fas fa-plus"></i> Save as playlist</button>
      </div>`;
  }

  const DNA_LABELS = { energy: 'Energy', danceability: 'Danceability', mood: 'Mood', tempo: 'Tempo', Uganda_factor: 'Uganda factor' };
  const dnaHTML = dna ? `
    <details class="yai-dna">
      <summary>Set DNA</summary>
      ${Object.entries(dna).map(([k, v]) => `
        <div class="yai-dna-row"><span>${DNA_LABELS[k] || _djEsc(k.replace(/_/g, ' '))}</span><div class="yai-dna-bar"><b style="width:${Math.max(0, Math.min(100, v))}%"></b></div><em>${v}</em></div>`).join('')}
    </details>` : '';

  const follow = list.length ? `
    <div class="yai-follow">
      <button type="button" class="dj-prompt-chip" data-q="more like this" onclick="sendDJPrompt(this.dataset.q)">More like this</button>
      <button type="button" class="dj-prompt-chip" data-q="something different" onclick="sendDJPrompt(this.dataset.q)">Different vibe</button>
      <button type="button" class="dj-prompt-chip" data-q="turn it up" onclick="sendDJPrompt(this.dataset.q)">More energy</button>
      <button type="button" class="dj-prompt-chip" data-q="chill it down" onclick="sendDJPrompt(this.dataset.q)">Dial it back</button>
    </div>` : '';

  const div = document.createElement('div');
  div.className = 'dj-message';
  div.innerHTML = `
    <div class="dj-msg-avatar"></div>
    <div class="dj-msg-bubble${list.length ? ' wide' : ''}">
      <div class="yai-say">${text}</div>
      ${cards}${more}${actions}${dnaHTML}${follow}
    </div>`;
  area.appendChild(div);
  area.scrollTop = area.scrollHeight;

  // Auto-play first pick
  if (autoplay) {
    playTrack(list[0].index);
    setDJStatus('playing');
  }
}

