let _userSearchTimer = null;
async function searchYapsUsers(query) {
  clearTimeout(_userSearchTimer);
  const res = document.getElementById('userSearchResults');
  if (!query || query.length < 2) {
    res.innerHTML = '<div style="padding:24px;text-align:center;color:var(--dim);font-size:13px;">Type a name to find users</div>';
    return;
  }
  res.innerHTML = '<div style="padding:24px;text-align:center;color:var(--dim);font-size:13px;">Searching…</div>';
  _userSearchTimer = setTimeout(async () => {
    if (!sb) return;
    let data = null, error = null;
    try { data = await _profilesSearch(query); } catch (e) { error = e; }

    if (error || !data || data.length === 0) {
      res.innerHTML = '<div style="padding:24px;text-align:center;color:var(--dim);font-size:13px;">No users found</div>';
      return;
    }

    data.forEach(u => { _avatarCache[u.id] = u.avatar_url || ''; });
    res.innerHTML = data.map(u => {
      const name   = u.full_name || u.username || 'YAPS User';
      const color  = _nameColor(name);
      const badge  = (u.account_type === 'artist' || u.account_type === 'dj' || u.account_type === 'promoter') ? '<span style="font-size:10px;background:var(--accent-dim);color:var(--accent);border-radius:8px;padding:2px 7px;margin-left:6px;">' + (u.account_type === 'dj' ? 'DJ' : 'Artist') + '</span>' : '';
      const handle = u.username ? `@${u.username}` : 'YAPS listener';
      return `<div class="msg-thread" onclick="startChatWithUser(${_jsArg(u.id)},${_jsArg(name)})">
        <div class="msg-avatar" style="background:${color};overflow:hidden;">${_avatarInner(u.avatar_url, name)}</div>
        <div class="msg-thread-info">
          <div class="msg-thread-name">${_escHtml(name)}${badge}</div>
          <div class="msg-thread-preview">${_escHtml(handle)}</div>
        </div>
        <i class="fas fa-chevron-right" style="color:var(--dim);font-size:12px;"></i>
      </div>`;
    }).join('');
  }, 300);
}

function startChatWithUser(userId, userName) {
  closeNewChatModal();
  const convId = _convId(_demoUser.id, userId);
  openChatView(convId, userId, userName);
}

/* ── Artist profile: does this artist have a YAPS account? ── */
function _normName(v) { return String(v || '').toLowerCase().replace(/[^a-z0-9]/g, ''); }

async function _resolveArtistAccount(a) {
  const btn = document.getElementById('apMsgBtn');
  if (btn) btn.style.display = '';
  if (!a || !sb) return;
  try {
    if (!a._account) {
      const data = await _profilesSearch(a.name);
      // exact match only — never message a "close enough" stranger
      a._account = (data || []).find(u =>
        _normName(u.full_name) === _normName(a.name) || _normName(u.username) === _normName(a.name)) || null;
    }
    const isMe = a._account && _demoUser && a._account.id === _demoUser.id;
    if (a._account && isMe && _currentArtistProfile === a && btn) btn.style.display = 'none';   // no Message button on your own profile
  } catch (e) { /* lookup failed, leave the button hidden */ }
}

/* ── Called from artist profile Message button ── */
function openChatWithArtist() {
  const a = _currentArtistProfile;
  if (!a) return;
  if (!a._account) { cnMessageArtist(a.name); return; }
  _requireLogin(() => {
    const u = a._account;
    navigate('messages');
    setTimeout(() => openChatView(_convId(_demoUser.id, u.id), u.id, u.full_name || a.name), 80);
  });
}

/* ═══════════════════════════════════════════════════════════════
   FIND FRIENDS FROM CONTACTS
   - Android Chrome: native Contact Picker (user chooses contacts)
   - Other browsers (iPhone etc.): paste/type numbers instead
   Numbers are sent over HTTPS to /api/contacts/match, compared and
   discarded by the server. Nothing from your contacts is stored.
   ═══════════════════════════════════════════════════════════════ */
// Safe argument for an inline on*="" handler: a JSON string literal that is then HTML-escaped for the attribute.
// (Escaping only ' is NOT enough: " closes the attribute, \ escapes the quote, and &#39; is decoded back to ' before the JS runs.)
function _jsArg(v) { return _escHtml(JSON.stringify(String(v == null ? '' : v))); }
function _escHtml(v) {
  return String(v == null ? '' : v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

// Normalise any phone format to +E.164. Defaults to Uganda (+256) for local numbers.
function _normPhone(raw, cc) {
  cc = cc || '256';
  let s = String(raw || '').trim();
  if (!s) return null;
  const hasPlus = s.charAt(0) === '+';
  s = s.replace(/\D/g, '');
  if (!hasPlus) {
    if (s.indexOf('00') === 0) s = s.slice(2);
    else if (s.charAt(0) === '0') s = cc + s.slice(1);
    else if (s.length <= 9) s = cc + s;
  }
  return (s.length >= 8 && s.length <= 15) ? '+' + s : null;
}

const _CONTACTS_API = ('contacts' in navigator) && ('ContactsManager' in window);

async function findFriendsFromContacts() {
  _requireLogin(async () => {
    if (!_CONTACTS_API) { _showManualContactEntry(); return; }
    let picked;
    try {
      picked = await navigator.contacts.select(['name', 'tel'], { multiple: true });
    } catch (e) {
      if (e && e.name !== 'AbortError') showToast('Could not open your contacts');
      return;
    }
    if (!picked || !picked.length) return;
    const entries = [];
    picked.forEach(c => (c.tel || []).forEach(t => entries.push({ name: (c.name && c.name[0]) || '', phone: t })));
    await _matchContacts(entries);
  });
}

function _showManualContactEntry() {
  const res = document.getElementById('userSearchResults');
  res.innerHTML = `<div style="padding:16px;">
    <div style="font-size:13px;color:var(--muted);margin-bottom:8px;">Your browser can't open your contact list. Paste or type phone numbers (one per line or separated by commas) to see who is on YAPS.</div>
    <textarea id="manualContactsInput" class="form-textarea" rows="5" placeholder="0772 123456&#10;+256 701 234567"></textarea>
    <button class="btn-primary" style="width:100%;justify-content:center;margin-top:10px;padding:11px;" onclick="_submitManualContacts()">Check numbers</button>
  </div>`;
}

function _submitManualContacts() {
  const raw = (document.getElementById('manualContactsInput') || {}).value || '';
  const entries = raw.split(/[\n,;]+/).map(x => x.trim()).filter(Boolean).map(x => ({ name: '', phone: x }));
  if (!entries.length) { showToast('Enter at least one number'); return; }
  _matchContacts(entries);
}

async function _matchContacts(entries) {
  const res = document.getElementById('userSearchResults');
  const nameByPhone = {};
  entries.forEach(e => { const n = _normPhone(e.phone); if (n && !nameByPhone[n]) nameByPhone[n] = e.name; });
  const phones = Object.keys(nameByPhone).slice(0, 500);
  if (!phones.length) { showToast('No valid phone numbers found'); return; }

  res.innerHTML = '<div style="padding:24px;text-align:center;color:var(--dim);font-size:13px;">Checking your contacts…</div>';
  let matches;
  try {
    matches = await _contactsMatch(phones);
  } catch (e) {
    res.innerHTML = '<div style="padding:24px;text-align:center;color:var(--dim);font-size:13px;">Could not check contacts right now. Try again.</div>';
    return;
  }
  matches = (matches || []).filter(u => !_demoUser || u.id !== _demoUser.id);
  const notOn = Math.max(0, phones.length - matches.length);

  let html = '';
  if (matches.length) {
    html += `<div style="padding:6px 12px 8px;font-size:11px;font-weight:800;letter-spacing:.06em;color:var(--muted);text-transform:uppercase;">${matches.length} of your contacts on YAPS</div>`;
    html += matches.map(u => {
      const yapsName = u.full_name || u.username || 'YAPS User';
      const contactName = nameByPhone[u.phone] || '';
      const shown = contactName || yapsName;
      const sub = contactName && contactName !== yapsName ? yapsName : (u.username ? '@' + u.username : 'On YAPS');
      const avatar = u.avatar_url
        ? `<img loading="lazy" decoding="async" src="${_escHtml(u.avatar_url)}" alt="" style="width:100%;height:100%;object-fit:cover;border-radius:50%;">`
        : _escHtml(shown.charAt(0).toUpperCase());
      return `<div class="msg-thread" data-id="${_escHtml(u.id)}" data-name="${_escHtml(yapsName)}" onclick="startChatWithUser(this.dataset.id,this.dataset.name)">
        <div class="msg-avatar" style="background:${_nameColor(shown)};overflow:hidden;">${avatar}</div>
        <div class="msg-thread-info">
          <div class="msg-thread-name">${_escHtml(shown)}</div>
          <div class="msg-thread-preview">${_escHtml(sub)}</div>
        </div>
        <span class="btn-primary" style="padding:6px 12px;font-size:12px;"><i class="fas fa-comment-dots"></i> Message</span>
      </div>`;
    }).join('');
  } else {
    html += `<div style="padding:28px 24px 12px;text-align:center;color:var(--dim);"><i class="fas fa-user-friends" style="font-size:28px;opacity:.4;display:block;margin-bottom:10px;"></i><div style="font-size:14px;font-weight:600;">None of these contacts are on YAPS yet</div></div>`;
  }
  if (notOn > 0) {
    html += `<div style="padding:14px 16px;text-align:center;"><button class="btn-ghost" onclick="inviteFriendsToYaps()"><i class="fas fa-share-alt"></i> Invite ${notOn} friend${notOn === 1 ? '' : 's'} to YAPS</button></div>`;
  }
  res.innerHTML = html;
}

async function inviteFriendsToYaps() {
  const data = { title: 'YAPSMusic', text: 'Join me on YAPSMusic, stream Ugandan music and chat with me there.', url: location.origin };
  try {
    if (navigator.share) { await navigator.share(data); return; }
    await navigator.clipboard.writeText(data.text + ' ' + data.url);
    showToast('Invite link copied');
  } catch (e) { /* user cancelled */ }
}


