  document.getElementById('qvpBack').addEventListener('click', qvpGoBack);
  const hdr = document.getElementById('qvpHeader'), page = document.getElementById('page-quickvibes');
  const setH = () => { const h = hdr.offsetHeight; if (h) page.style.setProperty('--qvp-head-h', h + 'px'); };
