// ── Fold Trending Videos into the swipeable YAPS VIDEO feed ──
// Reuses the same YouTube-sourced entries shown in the horizontal
// "Trending videos" row, so scrolling up/down on the Video page also
// surfaces them as full-screen, autoplay-muted cards (playback via the
// YouTube IFrame API — see buildYvCard / renderVideoFeed below).
_trendingVideos.forEach(tv => {
  _videoData.push({
    artist: tv.artist, handle: '@' + tv.artist.replace(/\s+/g, ''), verified: true, time: 'Trending',
    location: 'Uganda', desc: `${tv.title}, trending now`,
    hashtags: '#YAPS #Trending #UgandanMusic',
    sound: `${tv.title}, ${tv.artist}`,
    likes: _formatCount(tv.views || 0), comments: '0', shares: '0',
    img: tv.img || _ytThumb(tv.youtubeId),
    youtubeId: tv.youtubeId,
    avatar: tv.img || _ytThumb(tv.youtubeId),
    isDemo: false,
  });
});

let _yvLiked = new Set();
let _yvFollowed = new Set();
let _yvCurrentTab = 'foryou';
let _yvPaused = new Set();
let _yvProgressTimers = {};
let _yvDoubleTapTimers = {};

/* ── IMPROVEMENT 1: Simulated progress bar — rAF-driven ── */
function yvStartProgress(i) {
  yvStopProgress(i);
  const fill = document.getElementById('yv-pfill-' + i);
  if (!fill) return;
  let pct = parseFloat(fill.style.width) || 0;
  let lastTime = performance.now();
  function tick(now) {
    const delta = now - lastTime;
    lastTime = now;
    pct += delta * 0.0015; // ~0.12 per 80ms
    if (pct >= 100) { fill.style.width = '100%'; return; }
    fill.style.width = pct + '%';
    _yvProgressTimers[i] = requestAnimationFrame(tick);
  }
  _yvProgressTimers[i] = requestAnimationFrame(tick);
}
function yvStopProgress(i) {
  cancelAnimationFrame(_yvProgressTimers[i]);
  delete _yvProgressTimers[i];
}

let _yvFeedCacheTab = null;
let _yvObserver = null;

/* ── Real, Supabase-backed video feed ── */
const _videoDataSeed = _videoData.slice(); // offline/empty-state fallback (the "upload your video" prompt card)
function _formatCount(n) {
  n = Number(n) || 0;
  if (n >= 1000000) return (n / 1000000).toFixed(1).replace(/\.0$/, '') + 'M';
  if (n >= 1000) return (n / 1000).toFixed(1).replace(/\.0$/, '') + 'K';
  return String(n);
}
function _mapVideoRow(row, likedVideoIds) {
  return {
    _id: row.id, _uploaderId: row.uploader_id,
    artist: row.uploader_name || 'YAPS User', handle: '@' + (row.uploader_name || 'user').replace(/\s+/g, ''),
    verified: !!row.verified, time: _timeAgo(row.created_at),
    location: row.location || 'Uganda', desc: row.caption || '',
    hashtags: row.hashtags || '#yaps', sound: row.sound || `Original sound, ${row.uploader_name || 'YAPS User'}`,
    likes: _formatCount(row.likes_count), comments: _formatCount(row.comments_count), shares: _formatCount(row.shares_count),
    _likesCount: row.likes_count || 0, _commentsCount: row.comments_count || 0,
    video: row.video_url, img: row.thumbnail_url || '',
    avatar: row.uploader_avatar || 'https://images.unsplash.com/photo-1531746020798-e6953c6e8e04?w=100&q=70&auto=format',
    isDemo: false,
    _liked: likedVideoIds.has(row.id),
  };
}
async function _loadVideoFeed() {
  if (!sb) return; // stay on the offline demo seed
  try {
    const data = await api('/api/videos?limit=30');
    const likedVideoIds = new Set((data || []).filter(r => r.liked).map(r => r.id));
    const mapped = (data || []).map(row => _mapVideoRow(row, likedVideoIds));
    _videoData = mapped.length ? mapped : _videoDataSeed;
    _yvLiked = new Set();
    _videoData.forEach((v, i) => { if (v._liked) _yvLiked.add(i); });
    _yvFeedCacheTab = null;
    if (currentPage === 'video') renderVideoFeed();
  } catch (err) {
    console.error('Failed to load video feed:', err);
  }
}
let _yvChannel = null;
function _subscribeVideoFeed() {
  if (!sb || _yvChannel) return;
  _yvChannel = sb.channel('yaps_videos_feed')
    .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'yaps_videos' }, payload => {
      const row = payload.new;
      if (row.status && row.status !== 'approved') return;
      _videoData = [_mapVideoRow(row, new Set()), ..._videoData.filter(v => !v.isDemo)];
      _yvFeedCacheTab = null;
      if (currentPage === 'video') renderVideoFeed();
    })
    .subscribe();
}

function renderVideoFeed() {
  const feed = document.getElementById('yv-feed');
  if (!feed) return;
  // Only rebuild when tab changes
  if (_yvFeedCacheTab === _yvCurrentTab && feed.children.length > 0) return;
  _yvFeedCacheTab = _yvCurrentTab;
  // Stop all existing progress timers before rebuild
  Object.keys(_yvProgressTimers).forEach(k => cancelAnimationFrame(_yvProgressTimers[k]));
  _yvProgressTimers = {};
  const total = _videoData.length;
  feed.innerHTML = _videoData.map((v, i) => buildYvCard(v, i, total)).join('');
  // Observe cards to auto-start progress when visible
  if (_yvObserver) _yvObserver.disconnect();
  if ('IntersectionObserver' in window) {
    _yvObserver = new IntersectionObserver((entries) => {
      entries.forEach(e => {
        const idx = parseInt(e.target.dataset.idx);
        const videoEl = document.getElementById('yv-video-' + idx);
        const isYtSlot = videoEl && videoEl.classList.contains('yv-yt-slot');
        if (e.isIntersecting) {
          if (!_yvPaused.has(idx)) {
            yvStartProgress(idx);
            if (isYtSlot) yvLoadYouTube(idx);
            else if (videoEl) videoEl.play().catch(() => {});
          }
          yvShowSwipeHints(idx);
        } else {
          yvStopProgress(idx);
          if (isYtSlot) yvUnloadYouTube(idx);
          else if (videoEl) videoEl.pause();
        }
      });
    }, { threshold: 0.7 });
    feed.querySelectorAll('.yv-card').forEach(c => _yvObserver.observe(c));
  }
}

function buildYvCard(v, i, total) {
  const liked = _yvLiked.has(i);
  const followed = _yvFollowed.has(v.handle);
  const paused = _yvPaused.has(i);
  const total_ = total || _videoData.length;
  return `
  <div class="yv-card${paused ? ' paused' : ''}" id="yv-card-${i}" data-idx="${i}"
       onclick="yvHandleTap(event,${i})"
       ondblclick="yvDoubleTapLike(event,${i})">
    ${v.video
      ? `<video class="yv-bg" id="yv-video-${i}" src="${v.video}" ${v.img ? `poster="${v.img}"` : ''} autoplay muted loop playsinline preload="metadata"></video>`
      : v.youtubeId
        ? `<div class="yv-bg yv-yt-slot" id="yv-video-${i}" data-yt="${v.youtubeId}" style="background-image:url('${v.img}');background-size:cover;background-position:center;"></div>`
        : `<img class="yv-bg" src="${v.img}" alt="${v.artist}" loading="lazy">`}

    <!-- 2: Heart burst target -->
    <div class="yv-heart-burst" id="yv-hburst-${i}"></div>

    ${v.isDemo ? `
    <div class="yv-demo-label">
      <div class="yv-demo-icon"></div>
      <p><strong>Demo Preview</strong></p>
      <p>Upload your video to go live on YAPS</p>
    </div>` : ''}

    <!-- YAPS VIDEO badge -->
    <div class="yv-badge">
      <i class="fas fa-play-circle"></i>
      <span>YAPS <b>VIDEO</b></span>
    </div>

    <!-- 7: Card counter -->
    <div class="yv-card-counter">${i + 1} / ${total_}</div>

    <!-- Centre play icon (shows when paused) -->
    <div class="yv-play-center"><i class="fas fa-play" style="margin-left:4px;"></i></div>

    <!-- 3: Swipe indicators -->
    ${i > 0 ? `<div class="yv-swipe-hint top" id="yv-sh-top-${i}">
      <div class="yv-swipe-chevron"><i class="fas fa-chevron-up"></i></div>
    </div>` : ''}
    ${i < total_ - 1 ? `<div class="yv-swipe-hint bottom" id="yv-sh-bot-${i}">
      <div class="yv-swipe-chevron"><i class="fas fa-chevron-down"></i></div>
    </div>` : ''}

    <!-- Right actions -->
    <div class="yv-actions" onclick="event.stopPropagation()">
      <!-- 8: Follow avatar + improved follow button -->
      <div class="yv-follow-wrap">
        <div class="yv-avatar" style="position:relative;">
          <img loading="lazy" decoding="async" src="${v.avatar}" alt="${v.artist}">
          <div class="yv-avatar-yaps-label">YAPS</div>
          ${!followed ? `<div class="yv-follow-plus">+</div>` : ''}
        </div>
        <button class="yv-follow-btn${followed ? ' following' : ''}" id="yv-fbtn-${i}"
          onclick="yvToggleFollow('${v.handle}',${i},this)">
          ${followed ? '<i class="fas fa-check"></i> Following' : '+ Follow'}
        </button>
      </div>

      <!-- Like (single tap on button, double tap on card also triggers) -->
      <div class="yv-action" onclick="yvToggleLike(${i},this)">
        <div class="yv-action-icon${liked ? ' liked' : ''}" id="yv-licon-${i}">
          <i class="fas fa-heart"></i>
        </div>
        <div class="yv-action-label" id="yv-likes-${i}">${v.likes}</div>
      </div>

      <!-- 5: Comments — opens drawer -->
      <div class="yv-action" onclick="yvOpenComments(${i})">
        <div class="yv-action-icon">
          <i class="fas fa-comment-dots"></i>
        </div>
        <div class="yv-action-label">${v.comments}</div>
      </div>

      <!-- Bookmark -->
      <div class="yv-action" onclick="showToast('Saved!')">
        <div class="yv-action-icon">
          <i class="fas fa-bookmark"></i>
        </div>
        <div class="yv-action-label">1,326</div>
      </div>

      <!-- 4: Share — opens sheet -->
      <div class="yv-action" onclick="yvOpenShare(${i})">
        <div class="yv-action-icon">
          <i class="fas fa-share"></i>
        </div>
        <div class="yv-action-label">${v.shares}</div>
      </div>

      <!-- Sound toggle — videos autoplay muted (required by mobile browsers), tap to unmute -->
      <div class="yv-action" onclick="yvToggleSound(${i}); event.stopPropagation()">
        <div class="yv-action-icon" id="yv-sound-icon-${i}">
          <i class="fas fa-volume-${_yvSoundOn ? 'up' : 'mute'}"></i>
        </div>
        <div class="yv-action-label">${_yvSoundOn ? 'Sound on' : 'Tap for sound'}</div>
      </div>

      <!-- 6: Vinyl with sound bar animation -->
      <div class="yv-vinyl" id="yv-vinyl-${i}" onclick="showToast('${v.sound}'); event.stopPropagation()">
        <img loading="lazy" decoding="async" src="${v.avatar}" alt="sound">
        <div class="yv-vinyl-bars">
          <span></span><span></span><span></span><span></span><span></span>
        </div>
      </div>
    </div>

    <!-- Caption -->
    <div class="yv-caption">
      <div class="yv-location"><i class="fas fa-map-marker-alt"></i>${v.location}</div>
      <div class="yv-username">
        ${v.handle}
        ${v.verified ? '<i class="fas fa-check-circle"></i>' : ''}
      </div>
      <div class="yv-time">· ${v.time}</div>
      <div class="yv-desc">${v.desc}</div>
      <div class="yv-hashtags">${v.hashtags}</div>
      <div class="yv-sound-row">
        <i class="fas fa-music"></i> <span>${v.sound}</span>
      </div>
    </div>

    <!-- 1: Progress bar -->
    <div class="yv-progress-bar">
      <div class="yv-progress-fill" id="yv-pfill-${i}"></div>
    </div>
  </div>`;
}

/* ── YouTube-sourced cards in the swipeable feed ──
   Only the active (visible) card gets a live iframe; every other card
   just shows its thumbnail. Keeps things light even with lots of
   trending videos mixed into the feed, and means autoplay only ever
   fires for the card the user is actually looking at. */
// Remembers the user's sound choice across videos/sessions. Starts muted
// because mobile browsers block unmuted autoplay outright — once the user
// taps to unmute once, every video after that (this session and future
// visits) plays with sound already on, matching TikTok/Reels behavior.
let _yvSoundOn = localStorage.getItem('yaps_video_sound_pref') === 'on';

function yvLoadYouTube(i) {
  const slot = document.getElementById('yv-video-' + i);
  if (!slot || !slot.classList.contains('yv-yt-slot') || slot.dataset.loaded === '1') return;
  const ytId = slot.dataset.yt;
  slot.dataset.loaded = '1';
  const muteParam = _yvSoundOn ? 0 : 1;
  slot.innerHTML = `<iframe id="yv-yt-iframe-${i}" src="https://www.youtube.com/embed/${ytId}?autoplay=1&mute=${muteParam}&loop=1&playlist=${ytId}&controls=0&playsinline=1&modestbranding=1&rel=0&enablejsapi=1"
    style="position:absolute;inset:0;width:100%;height:100%;border:0;" allow="autoplay; encrypted-media" allowfullscreen></iframe>`;
}
function yvUnloadYouTube(i) {
  const slot = document.getElementById('yv-video-' + i);
  if (!slot || !slot.classList.contains('yv-yt-slot')) return;
  slot.dataset.loaded = '0';
  slot.innerHTML = ''; // drop the iframe entirely so it actually stops playing/using bandwidth
}

// Toggles sound for the currently loaded video and remembers the choice
// for every video after this one (session + future visits via localStorage).
function yvToggleSound(i) {
  _yvSoundOn = !_yvSoundOn;
  localStorage.setItem('yaps_video_sound_pref', _yvSoundOn ? 'on' : 'off');
  const iframe = document.getElementById('yv-yt-iframe-' + i);
  if (iframe && iframe.contentWindow) {
    iframe.contentWindow.postMessage(JSON.stringify({
      event: 'command',
      func: _yvSoundOn ? 'unMute' : 'mute',
      args: []
    }), '*');
  }
  const icon = document.getElementById('yv-sound-icon-' + i);
  if (icon) icon.innerHTML = `<i class="fas fa-volume-${_yvSoundOn ? 'up' : 'mute'}"></i>`;
  const label = icon && icon.parentElement ? icon.parentElement.querySelector('.yv-action-label') : null;
  if (label) label.textContent = _yvSoundOn ? 'Sound on' : 'Tap for sound';
  showToast(_yvSoundOn ? 'Sound on' : 'Muted');
}

/* Distinguish single tap (pause) from double tap (like) */
function yvHandleTap(e, i) {
  // If double tap already handled, skip
  if (e._yvDouble) return;
  if (_yvDoubleTapTimers[i]) {
    clearTimeout(_yvDoubleTapTimers[i]);
    _yvDoubleTapTimers[i] = null;
    return; // second tap, double tap handled by dblclick
  }
  _yvDoubleTapTimers[i] = setTimeout(() => {
    _yvDoubleTapTimers[i] = null;
    yvTogglePause(i);
  }, 220);
}

function yvTogglePause(i) {
  const videoEl = document.getElementById('yv-video-' + i);
  const isYtSlot = videoEl && videoEl.classList.contains('yv-yt-slot');
  if (_yvPaused.has(i)) {
    _yvPaused.delete(i);
    yvStartProgress(i);
    if (isYtSlot) yvLoadYouTube(i);
    else if (videoEl) videoEl.play().catch(() => {});
    const vinyl = document.getElementById('yv-vinyl-' + i);
    if (vinyl) vinyl.style.animationPlayState = 'running';
  } else {
    _yvPaused.add(i);
    yvStopProgress(i);
    if (isYtSlot) yvUnloadYouTube(i);
    else if (videoEl) videoEl.pause();
    const vinyl = document.getElementById('yv-vinyl-' + i);
    if (vinyl) vinyl.style.animationPlayState = 'paused';
  }
  const card = document.getElementById('yv-card-' + i);
  if (card) card.classList.toggle('paused', _yvPaused.has(i));
}

/* ── IMPROVEMENT 2: Double-tap heart burst ── */
function yvDoubleTapLike(e, i) {
  e._yvDouble = true;
  // trigger like
  if (!_yvLiked.has(i)) {
    const likeEl = document.getElementById('yv-licon-' + i);
    if (likeEl) yvToggleLike(i, likeEl.closest('.yv-action'));
  }
  // burst animation on card
  const burst = document.getElementById('yv-hburst-' + i);
  if (burst) {
    burst.classList.remove('burst');
    void burst.offsetWidth; // reflow
    burst.classList.add('burst');
    setTimeout(() => burst.classList.remove('burst'), 700);
  }
  // scatter mini hearts
  const card = document.getElementById('yv-card-' + i);
  if (card) {
    const rect = card.getBoundingClientRect();
    const cx = (e.clientX || rect.left + rect.width / 2) - rect.left;
    const cy = (e.clientY || rect.top + rect.height / 2) - rect.top;
    for (let p = 0; p < 6; p++) {
      const h = document.createElement('div');
      h.className = 'yv-heart-particle';
      h.textContent = '';
      const angle = (p / 6) * 360;
      const ox = Math.cos(angle * Math.PI / 180) * (20 + Math.random() * 30);
      const oy = Math.sin(angle * Math.PI / 180) * (20 + Math.random() * 30);
      h.style.cssText = `left:${cx + ox}px;top:${cy + oy}px;--r:${Math.random()*40-20}deg;animation-delay:${p*0.05}s`;
      card.appendChild(h);
      setTimeout(() => h.remove(), 1000);
    }
  }
}

function yvToggleLike(i, el) {
  const iconEl = document.getElementById('yv-licon-' + i) || el.querySelector('.yv-action-icon');
  const labelEl = document.getElementById('yv-likes-' + i);
  const v = _videoData[i];
  const nowLiked = !_yvLiked.has(i);

  if (nowLiked) {
    _yvLiked.add(i);
    if (iconEl) {
      iconEl.classList.add('liked');
      iconEl.style.transform = 'scale(1.4)';
      setTimeout(() => { iconEl.style.transform = ''; }, 260);
    }
  } else {
    _yvLiked.delete(i);
    if (iconEl) iconEl.classList.remove('liked');
  }

  if (v._id && sb && _demoUser) {
    // Real video — persist the like/unlike and keep an accurate count
    v._likesCount = Math.max(0, (v._likesCount || 0) + (nowLiked ? 1 : -1));
    v.likes = _formatCount(v._likesCount);
    if (labelEl) labelEl.textContent = v.likes;
    (async () => {
      try {
        if (nowLiked) {
          await api('/api/videos/' + v._id + '/like', { method: 'POST' });
          if (v._uploaderId && v._uploaderId !== _demoUser.id) {
            sendNotification({ toUserId: v._uploaderId, type: 'like', body: `${_demoUser.name} liked your video` });
          }
        } else {
          await api('/api/videos/' + v._id + '/like', { method: 'DELETE' });
        }
      } catch (err) { console.error('Like sync failed:', err); }
    })();
  } else {
    // Demo/offline card — cosmetic only, matches previous behavior
    if (labelEl) {
      if (nowLiked) {
        const n = parseFloat(v.likes);
        labelEl.textContent = isNaN(n) ? v.likes : (n + 0.1).toFixed(1) + 'K';
      } else {
        labelEl.textContent = v.likes;
      }
    }
  }
}

/* ── IMPROVEMENT 8: Follow button with animation ── */
function yvToggleFollow(handle, i, btn) {
  const plusEl = btn.closest('.yv-follow-wrap').querySelector('.yv-follow-plus');
  btn.classList.add('pulse');
  setTimeout(() => btn.classList.remove('pulse'), 320);
  if (_yvFollowed.has(handle)) {
    _yvFollowed.delete(handle);
    btn.innerHTML = '+ Follow';
    btn.classList.remove('following');
    if (plusEl) plusEl.style.display = 'flex';
    showToast('Unfollowed ' + handle);
  } else {
    _yvFollowed.add(handle);
    btn.innerHTML = '<i class="fas fa-check"></i> Following';
    btn.classList.add('following');
    if (plusEl) plusEl.style.display = 'none';
    showToast('Following ' + handle);
  }
}

