function _renderCommentsList(items) {
  const list = document.getElementById('yv-comments-list');
  if (!items.length) {
    list.innerHTML = `<div style="padding:30px;text-align:center;color:var(--dim);">No comments yet, be the first!</div>`;
    return;
  }
  list.innerHTML = items.map(c => `
    <div class="yv-comment-item">
      <div class="yv-comment-avatar"><img loading="lazy" decoding="async" src="${_escHtml(_safeUrl(c.avatar) || 'data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw==')}" alt="${_escHtml(c.name)}"></div>
      <div class="yv-comment-body">
        <div class="yv-comment-name">${_escHtml(c.name)}</div>
        <div class="yv-comment-text">${_escHtml(c.text)}</div>
        <div class="yv-comment-meta">
          <span>${c.time}</span>
          ${c.likes != null ? `<span class="yv-comment-like" onclick="showToast('Liked comment')">${c.likes} likes</span>` : ''}
          <span style="cursor:pointer" onclick="showToast('Replying…')">Reply</span>
        </div>
      </div>
    </div>
  `).join('');
}
async function yvOpenComments(i) {
  const v = _videoData[i];
  const drawer = document.getElementById('yv-comments-drawer');
  if (!drawer) return;
  _commentsMode = 'video';
  _yvCommentsOpenIdx = i;
  document.getElementById('yv-comments-title').textContent = v.comments + ' Comments';
  drawer.classList.add('open');

  if (v._id && sb) {
    document.getElementById('yv-comments-list').innerHTML = `<div style="padding:30px;text-align:center;color:var(--dim);">Loading…</div>`;
    try {
      const data = await api('/api/videos/' + v._id + '/comments?limit=50');
      _renderCommentsList((data || []).map(c => ({
        name: '@' + (c.user_name || 'user').replace(/\s+/g, ''), text: c.body, time: _timeAgo(c.created_at), avatar: c.user_avatar || 'https://images.unsplash.com/photo-1531746020798-e6953c6e8e04?w=60&q=60&auto=format',
      })));
    } catch (err) {
      console.error('Failed to load comments:', err);
      _renderCommentsList([]);
    }
  } else {
    _renderCommentsList([]);
  }
}
function yvCloseComments() {
  const drawer = document.getElementById('yv-comments-drawer');
  if (drawer) drawer.classList.remove('open');
  _yvCommentsOpenIdx = null;
}
async function yvSendComment() {
  const inp = document.getElementById('yv-comment-input');
  if (!inp || !inp.value.trim()) return;
  const text = inp.value.trim();
  const v = _yvCommentsOpenIdx != null ? _videoData[_yvCommentsOpenIdx] : null;
  const list = document.getElementById('yv-comments-list');
  const el = document.createElement('div');
  el.className = 'yv-comment-item';
  el.innerHTML = `
    <div class="yv-comment-avatar" style="background:linear-gradient(135deg,#2f8eff,#1a6bb5);display:flex;align-items:center;justify-content:center;font-size:14px;font-weight:700;color:#fff;overflow:hidden;">${_demoUser ? _avatarInner(_demoUser.avatar, _demoUser.name) : 'Y'}</div>
    <div class="yv-comment-body">
      <div class="yv-comment-name">${_escHtml(_demoUser ? '@' + _demoUser.name.replace(/\s+/g, '') : '@You')}</div>
      <div class="yv-comment-text">${_escHtml(text)}</div>
      <div class="yv-comment-meta"><span>Just now</span></div>
    </div>`;
  list.prepend(el);
  inp.value = '';
  if (!(v && v._id && sb && _demoUser)) {
    // Not stored on the server (demo item, or not signed in): say so instead of claiming it was posted.
    showToast(_demoUser ? 'Comment shown on this device only' : 'Sign in to post a comment others can see');
    return;
  }
  {
    try {
      await api('/api/videos/' + v._id + '/comments', { method: 'POST', body: { body: String(text).slice(0, 500) } });
      showToast('Comment posted!');
      v._commentsCount = (v._commentsCount || 0) + 1;
      v.comments = _formatCount(v._commentsCount);
      const label = document.querySelector(`#yv-card-${_yvCommentsOpenIdx} .yv-action-label`);
      document.getElementById('yv-comments-title').textContent = v.comments + ' Comments';
      if (v._uploaderId && v._uploaderId !== _demoUser.id) {
        sendNotification({ toUserId: v._uploaderId, type: 'comment', body: `${_demoUser.name} commented on your video` });
      }
      notifyMentions(text, '');
    } catch (err) {
      console.error('Comment send failed:', err);
      el.remove(); inp.value = text;   // roll back the optimistic row so the UI matches what was saved
      showToast('Could not post your comment. Please try again.');
    }
  }
}

