function yvCloseUploadModal() {
  const modal = document.getElementById('yv-upload-modal');
  if (modal) modal.classList.remove('open');
  // Reset form
  const preview = document.getElementById('yv-upload-preview');
  const dropzone = document.getElementById('yv-upload-dropzone');
  const form = document.getElementById('yv-upload-form');
  if (preview) preview.style.display = 'none';
  if (dropzone) dropzone.style.display = 'flex';
  if (form) form.style.display = 'none';
  const thumbEl = document.getElementById('yv-upload-thumb');
  if (thumbEl) thumbEl.src = '';
  const nameEl = document.getElementById('yv-upload-filename');
  if (nameEl) nameEl.textContent = '';
  _yvUploadFile = null;
}

let _yvUploadFile = null;

function yvHandleVideoFile(file) {
  if (!file) return;
  if (!file.type.startsWith('video/') && !file.type.startsWith('image/')) {
    showToast('Please pick a video or image file'); return;
  }
  _yvUploadFile = file;
  const dropzone = document.getElementById('yv-upload-dropzone');
  const preview = document.getElementById('yv-upload-preview');
  const form = document.getElementById('yv-upload-form');
  const nameEl = document.getElementById('yv-upload-filename');
  const thumbEl = document.getElementById('yv-upload-thumb');
  if (dropzone) dropzone.style.display = 'none';
  if (preview) preview.style.display = 'flex';
  if (form) form.style.display = 'block';
  if (nameEl) nameEl.textContent = file.name;
  // Show thumbnail
  if (thumbEl) {
    if (file.type.startsWith('image/')) {
      thumbEl.src = URL.createObjectURL(file);
    } else {
      // Video — show a default placeholder
      thumbEl.src = 'https://images.unsplash.com/photo-1571330735066-03aaa9429d89?w=120&q=70&auto=format';
    }
  }
}

async function yvSubmitUpload() {
  const caption = document.getElementById('yv-upload-caption')?.value?.trim();
  const tags = document.getElementById('yv-upload-tags')?.value?.trim();
  const sound = document.getElementById('yv-upload-sound')?.value?.trim();
  if (!caption) { showToast('Add a caption first!'); return; }
  if (!_yvUploadFile) { showToast('Choose a video first!'); return; }
  if (!sb || !_demoUser) { showToast('Sign in to upload a video'); return; }
  if (!_yvUploadFile.type.startsWith('video/')) { showToast('Please choose a video file'); return; }
  const MAX_VIDEO_BYTES = 50 * 1024 * 1024; // 50MB (Supabase free-plan file limit)
  if (_yvUploadFile.size > MAX_VIDEO_BYTES) { showToast('Video too large (max 50 MB)'); return; }
  if (!document.getElementById('yv-upload-copyright')?.checked) { showToast('Please confirm you own the rights to this video'); return; }

  const ownerUpload = typeof _isOwner === 'function' && _isOwner();
  const markTrending = ownerUpload && document.getElementById('yvMarkTrending')?.checked;
  const hashtags = tags ? (tags.split(' ').filter(t => t.startsWith('#')).join(' ') || '#yaps') : '#yaps';

  const progWrap = document.getElementById('yv-upload-progress-wrap');
  const progFill = document.getElementById('yv-upload-progress-fill');
  const submitBtn = document.getElementById('yv-upload-submit-btn');
  if (progWrap) progWrap.style.display = 'block';
  if (submitBtn) { submitBtn.disabled = true; submitBtn.textContent = 'Uploading…'; }
  const setPct = (p) => { if (progFill) progFill.style.width = p + '%'; const lb = document.querySelector('.yv-upload-prog-label'); if (lb) lb.textContent = p > 0 && p < 100 ? 'Uploading your video… ' + Math.floor(p) + '%' : 'Uploading your video…'; };
  setPct(10);

  try {
    const ext = (_yvUploadFile.name.split('.').pop() || 'mp4').toLowerCase();
    const path = `${_demoUser.id}/${Date.now()}.${ext}`;
    const videoUrl = await _apiUpload('yaps-videos', _yvUploadFile, { onProgress: p => setPct(3 + p * 0.87) });
    setPct(92);
    const inserted = await api('/api/videos', { method: 'POST', body: {
      video_url: videoUrl, copyright_confirmed: true, thumbnail_url: null, caption: String(caption).slice(0, 500),
      hashtags: String(hashtags).slice(0, 200), sound: sound ? String(sound).slice(0, 150) : null, location: 'Uganda',
    } });
    setPct(100);
    if (inserted && inserted.status && inserted.status !== 'approved') {
      const cb = document.getElementById('yv-upload-copyright'); if (cb) cb.checked = false;
      yvCloseUploadModal(); showToast('Video submitted, it goes live once approved'); return;
    }

    const newPost = _mapVideoRow(inserted, new Set());
    _videoData = [newPost, ..._videoData.filter(v => !v.isDemo)];
    _yvFeedCacheTab = null; // force rebuild
    if (markTrending) {
      _trendingVideos.unshift({ videoUrl: newPost.video, img: newPost.img || 'https://images.unsplash.com/photo-1516450360452-9312f5e86fc7?w=800&q=70&auto=format', title: caption || 'My video', artist: _demoUser.name, views: '0' });
      if (typeof renderTrendingVideos === 'function') renderTrendingVideos();
    }
    yvCloseUploadModal();
    if (currentPage === 'video') {
      renderVideoFeed();
      const feedEl = document.getElementById('yv-feed');
      if (feedEl) feedEl.scrollTop = 0;
    } else {
      navigate('video');
    }
    showToast(markTrending ? 'Video uploaded and featured in Trending!' : 'Video uploaded! You\'re live on YAPS!');

    // Let followers/everyone know when the official account drops a video.
    if (ownerUpload) {
      sendNotification({ toUserId: null, type: 'release', body: `New video: "${caption}"` });
    }
  } catch (err) {
    console.error('Video upload failed:', err);
    showToast(_uploadErrText(err));
  } finally {
    if (submitBtn) { submitBtn.disabled = false; submitBtn.textContent = 'Post'; }
    if (progWrap) progWrap.style.display = 'none';
    setPct(0);
  }
}



