/* ── Key lookup ── */
function _lyricsKey(title, artist) {
  return `${title}|${artist}`.toLowerCase().replace(/\s+/g,' ').trim();
}

/* ── Open lyrics panel ── */
async function openLyrics() {
  const panel = document.getElementById('lyricsPanel');
  const body  = document.getElementById('lpBody');
  const npBtn = document.getElementById('npLyricsBtn');
  if (!panel) return;

  _lyricsOpen = true;
  panel.classList.add('open');
  if (npBtn) npBtn.classList.add('active');

  const t = tracks[currentTrack];
  document.getElementById('lpTrackName').textContent  = t.title;
  document.getElementById('lpArtistName').textContent = t.artist;

  // If already loaded for this track, just re-render
  if (_lyricsTrackIdx === currentTrack && _lyricsData) {
    _renderLyrics(_lyricsData);
    _startLyricsSync();
    return;
  }

  body.innerHTML = '';   // no loading screen, lyrics appear as soon as they're ready
  const reqIdx = currentTrack;

  // Check hardcoded DB first
  const key = _lyricsKey(t.title, t.artist);
  if (_lyricsDB[key]) {
    _lyricsTrackIdx = currentTrack;
    _lyricsData     = _lyricsDB[key];
    document.getElementById('lpSourceBadge').innerHTML = '<i class="fas fa-music"></i> Official Lyrics';
    _renderLyrics(_lyricsData);
    _startLyricsSync();
    return;
  }

  // Try AI generation
  const apiKey = true; // the key lives on the server now; /api/ai/lyrics decides if AI is available
  if (apiKey) {
    try {
      const lyrics = await _generateLyricsAI(t.title, t.artist, apiKey);
      if (reqIdx !== currentTrack || !_lyricsOpen) return;   // track changed / panel closed while waiting
      _lyricsTrackIdx = currentTrack;
      _lyricsData     = lyrics;
      document.getElementById('lpSourceBadge').innerHTML = '<i class="fas fa-robot"></i> AI Generated';
      _renderLyrics(_lyricsData);
      _startLyricsSync();
    } catch(e) {
      _showLyricsEmpty(true);
    }
  } else {
    // Show demo placeholder lyrics
    _lyricsTrackIdx = currentTrack;
    _lyricsData = _demoPlaceholderLyrics(t.title, t.artist);
    document.getElementById('lpSourceBadge').innerHTML = '<i class="fas fa-star"></i> Demo Lyrics';
    _renderLyrics(_lyricsData);
    _startLyricsSync();
  }
}

/* ── Close lyrics panel ── */
function closeLyrics() {
  _lyricsOpen = false;
  document.getElementById('lyricsPanel').classList.remove('open');
  const npBtn = document.getElementById('npLyricsBtn');
  if (npBtn) npBtn.classList.remove('active');
  _stopLyricsSync();
}

/* ── Render lyrics lines into DOM ── */
function _renderLyrics(data) {
  const body = document.getElementById('lpBody');
  body.innerHTML = data.map((item, i) => {
    if (item.s) return `<div class="lp-section">${item.s}</div>`;
    return `<div class="lp-line" id="lp-line-${i}" data-p="${item.p || 0}" onclick="_lyricsSeekTo(${item.p || 0})">${item.t}</div>`;
  }).join('');
}

/* ── Sync highlighting to playback progress ── */
function _startLyricsSync() {
  _stopLyricsSync();
  _lyricsSyncTimer = setInterval(_syncLyricsHighlight, 300);
}

function _stopLyricsSync() {
  if (_lyricsSyncTimer) { clearInterval(_lyricsSyncTimer); _lyricsSyncTimer = null; }
}

function _syncLyricsHighlight() {
  if (!_lyricsOpen || !_lyricsData) return;
  const progress = currentProgress; // global from main app

  // Update progress fill
  const fill = document.getElementById('lpProgressFill');
  if (fill) fill.style.width = progress + '%';

  // Find active line
  const lines = document.querySelectorAll('.lp-line');
  if (!lines.length) return;

  let activeEl = null;
  lines.forEach(el => {
    const p = parseFloat(el.dataset.p || 0);
    el.classList.remove('active', 'passed');
    if (p <= progress) {
      el.classList.add('passed');
      activeEl = el;
    }
  });

  if (activeEl) {
    activeEl.classList.remove('passed');
    activeEl.classList.add('active');
    // Auto-scroll active line into view
    activeEl.scrollIntoView({ block: 'center', behavior: 'smooth' });
  }
}

/* ── Seek on lyric tap ── */
function _lyricsSeekTo(pct) {
  currentProgress = pct;
  if (audioEngine && audioEngine.duration) {
    audioEngine.currentTime = (pct / 100) * audioEngine.duration;
  }
  updateProgress();
}

/* ── Empty state ── */
function _showLyricsEmpty(retry) {
  const body = document.getElementById('lpBody');
  body.innerHTML = `
    <div class="lp-empty">
      <i class="fas fa-microphone-slash"></i>
      <p>No lyrics found</p>
      <span>Lyrics for this track aren't available yet</span>
      ${retry ? `<button class="lp-retry-btn" onclick="openLyrics()"><i class="fas fa-redo"></i> Try Again</button>` : ''}
    </div>`;
}

