/* ── AI lyrics generation via Claude API ── */
async function _generateLyricsAI(title, artist) {
  const lyrics = await api('/api/ai/lyrics', { method: 'POST', body: { title: String(title).slice(0, 150), artist: String(artist).slice(0, 100) } });
  if (!Array.isArray(lyrics)) throw new Error('Bad response');
  return lyrics;
}

/* ── Auto-close lyrics when track changes ── */
function _onTrackChange_lyrics() {
  if (_lyricsOpen) {
    // Reset loaded data so new track gets fresh lyrics
    _lyricsTrackIdx = -1;
    _lyricsData     = null;
    openLyrics(); // reload for new track
  }
}

/* Hook into playTrack — patch after load */
(function() {
  const _origPlayTrack = window.playTrack;
  window.playTrack = function(idx) {
    _origPlayTrack && _origPlayTrack(idx);
    setTimeout(_onTrackChange_lyrics, 200);
  };
})();

/* Count plays of shared (uploaded) tracks on the API */
(function() {
  let _lastCounted = null;
  const _prev = window.playTrack;
  window.playTrack = function(idx) {
    _prev && _prev(idx);
    try {
      const t = tracks[idx];
      if (t && t._remote && t.id !== _lastCounted) {
        _lastCounted = t.id;
        api('/api/tracks/' + t.id + '/play', { method: 'POST' }).catch(() => {});
      }
    } catch (e) {}
  };
})();

