 const keep=q&&document.activeElement&&document.activeElement.id==='ysQ';b.innerHTML=h;if(view==='taste'&&typeof renderTasteProfile==='function'){try{renderTasteProfile()}catch(e){}}const nv=window._ysNav;window._ysNav=0;if(nv){b.classList.remove('ys-a1','ys-a2');void b.offsetWidth;b.classList.add(nv>0?'ys-a1':'ys-a2')}
