/* ── script #63 ── */
(function () {
  var sheet = document.getElementById('yvmSheet'), cur = null, lastFocus = null;
  function toast(m) { if (typeof showToast === 'function') showToast(m); }
  function close() { sheet.classList.remove('open'); if (lastFocus && lastFocus.focus) { try { lastFocus.focus(); } catch (e) {} } }
  function copy(text) {
    if (navigator.clipboard && navigator.clipboard.writeText) return navigator.clipboard.writeText(text);
    return new Promise(function (res, rej) {
      var ta = document.createElement('textarea'); ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';
      document.body.appendChild(ta); ta.select();
      try { document.execCommand('copy') ? res() : rej(); } catch (e) { rej(e); } ta.remove();
    });
  }
  window.yv2VideoMenu = function (id, title, artist) {
    if (!id) { toast('Video unavailable'); return; }
    cur = { url: 'https://youtu.be/' + encodeURIComponent(id), title: title, artist: artist };
    document.getElementById('yvmT').textContent = title || 'Video';
    document.getElementById('yvmA').textContent = artist || '';
    lastFocus = document.activeElement;
    sheet.classList.add('open');
    var first = sheet.querySelector('.yvm-i'); if (first) first.focus();
  };
  sheet.addEventListener('click', function (e) {
    if (e.target === sheet) { close(); return; }
    var b = e.target.closest('.yvm-i'); if (!b || !cur) return;
    var a = b.getAttribute('data-a'), v = cur;
    close();
    if (a === 'share') {
      if (navigator.share) navigator.share({ title: v.title + ' by ' + v.artist, text: 'Watch ' + v.title + ' by ' + v.artist + ' on YAPSMusic', url: v.url }).catch(function () {});
      else copy(v.url).then(function () { toast('Link copied'); }, function () { toast('Couldn\u2019t copy link'); });
    } else if (a === 'copy') {
      copy(v.url).then(function () { toast('Link copied'); }, function () { toast('Couldn\u2019t copy link'); });
    } else if (a === 'yt') {
      window.open(v.url, '_blank', 'noopener');
    } else if (a === 'report') {
      if (typeof openFeedback === 'function') openFeedback('bug');
    }
  });
  document.addEventListener('keydown', function (e) { if (e.key === 'Escape' && sheet.classList.contains('open')) close(); });

  // Send any feedback that was saved while offline
  function flush() {
    if (typeof flushFeedbackQueue !== 'function') return;
    flushFeedbackQueue().then(function (n) { if (n) toast(n === 1 ? 'Your saved feedback was sent' : n + ' saved messages were sent'); }).catch(function () {});
  }
  window.addEventListener('online', flush);
  window.addEventListener('load', function () { setTimeout(flush, 5000); });
})();

