var seen = {}, last = null, members = null, BASE_SUB = "", chan = null, poll = null, bootId = 0, bound = false, booted = false, authHooked = false, pendingOpts = null;

function nearBottom() { var l = $("ccLog"); return l.scrollHeight - l.scrollTop - l.clientHeight < 120; }
