function showEmpty() { $("ccLog").innerHTML = '<div class="cc-empty"><i class="fas fa-comments"></i><b>No messages yet</b>Say hello 👋</div>'; }
function autoGrow() { var i = $("ccInput"); i.style.height = "auto"; i.style.height = Math.min(i.scrollHeight, 120) + "px"; }

function isHub() { return COMMUNITY === "yaps-connect"; }   // the shared room for all listeners
