  var d = isHub() && typeof window.yapsSongOfTheDay === "function" ? window.yapsSongOfTheDay() : null;
  if (!d) { box.hidden = true; box.innerHTML = ""; return; }
  var t = d.track, img = safeUrl(t.img) || (/^images\//.test(t.img || "") ? t.img : "");
  box.innerHTML = (img ? '<img src="' + esc(img) + '" alt="">' : "") + '<div class="cc-pin-t"><small>\uD83D\uDCCC Song of the Day \u00B7 talk about it here</small><b>' + esc(t.title) + '</b><span>' + esc(t.artist || "") + '</span></div><button type="button" id="ccPinPlay" aria-label="Play song of the day"><i class="fas fa-play"></i></button>';
  box.hidden = false;
