  var pick = $("ccPick"), pq = $("ccPickQ"), pl = $("ccPickL");
  function drawPick() {
    var q = pq.value.trim().toLowerCase(), list = (typeof tracks !== "undefined" && tracks) ? tracks : [], out = [];
    for (var i = 0; i < list.length && out.length < 30; i++) { var t = list[i]; if (t && t.title && (!q || (t.title + " " + (t.artist || "")).toLowerCase().indexOf(q) >= 0)) out.push(t); }
    pl.innerHTML = (q ? '<button type="button" class="cc-song" data-own="1"><span><b>Request \u201C' + esc(pq.value.trim()) + '\u201D</b><small>Send exactly what you typed</small></span></button>' : "") +
      out.map(function (t) { return '<button type="button" class="cc-song" data-t="' + esc(t.title) + '" data-a="' + esc(t.artist || "") + '">' + (safeUrl(t.img) ? '<img alt="" loading="lazy" src="' + esc(t.img) + '">' : "") + '<span><b>' + esc(t.title) + '</b><small>' + esc(t.artist || "") + "</small></span></button>"; }).join("");
  }
