function validC(v){v=v.trim();return/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)||v.replace(/\D/g,'').length>=9}
function done(){stepTxt.textContent='Entered';card.innerHTML='<div class="gv-ok">\u2705</div><h2>You\u2019re entered!</h2><p>Thanks for taking part. Being entered doesn\u2019t guarantee a gift. YAPS checks every entry before choosing winners.</p><ol><li>Entries close '+esc(fmt(CONFIG.closesAt))+'.</li><li>Winners are announced on the Earnings page on '+esc(fmt(CONFIG.winnersAnnounceAt))+'.</li><li>You never pay anything to enter or to receive a gift. YAPS will never ask for your PIN, password or a one-time code.</li></ol>'+(CONFIG.contact?'<p class="gv-note">Official contact: '+esc(CONFIG.contact)+'</p>':'')+'<button class="gv-ans" data-a="home">Back to YAPS Music</button>'}
