/* ── script #117 ── */
(function () {
  // Bottom nav + mini player are hidden whenever the on-screen keyboard is open (so they never ride up
  // above it) and come back as soon as the keyboard closes (done typing, Back pressed, tapped away).
  var root = document.documentElement, t, vv = window.visualViewport, base = 0, seen = false;
  function typing(el) {
    if (!el || el.nodeType !== 1) return false;
    if (el.isContentEditable) return true;
    var tag = el.tagName;
    if (tag === 'TEXTAREA' || tag === 'SELECT') return true;
    if (tag !== 'INPUT') return false;
    return !/^(button|checkbox|radio|range|submit|reset|file|color|image)$/i.test(el.type || 'text');
  }
  function curH() { return vv ? vv.height : window.innerHeight; }
  function shrunk() {
    var h = curH();
    if (!seen) base = Math.max(base, window.innerHeight, h);
    return base - h > 120;
  }
  function show() { root.classList.remove('kb-open'); }
  function hide() { root.classList.add('kb-open'); }
  document.addEventListener('focusin', function (e) {
    clearTimeout(t);
    if (typing(e.target)) hide();   // hide immediately, before the keyboard finishes sliding up
  });
  document.addEventListener('focusout', function () {
    clearTimeout(t);
    // delay so moving focus between inputs (or re-rendering the chat composer after send) doesn't flicker the nav
    t = setTimeout(function () {
      if (typing(document.activeElement)) return;
      if (seen && shrunk()) return;  // keyboard still physically open: keep hidden
      seen = false; show();
    }, 200);
  });
  function onVV() {
    if (shrunk()) { seen = true; hide(); }
    else if (seen) { seen = false; show(); }   // keyboard closed (even if the field kept focus)
  }
  if (vv) vv.addEventListener('resize', onVV);
  window.addEventListener('orientationchange', function () { base = 0; seen = false; setTimeout(function () { if (!typing(document.activeElement)) show(); }, 300); });
  window.addEventListener('pagehide', function () { seen = false; show(); });
  // Follow the visual viewport so the header stays on screen while the keyboard is up
  function pin() {
    if (!vv) return;
    root.style.setProperty('--vvt', (root.classList.contains('kb-open') ? Math.max(0, vv.offsetTop) : 0) + 'px');
  }
  if (vv) { vv.addEventListener('resize', pin); vv.addEventListener('scroll', pin); }
  new MutationObserver(pin).observe(root, { attributes: true, attributeFilter: ['class'] });
})();

/* ── script #119 ── */
(function () {
  var mq = window.matchMedia('(min-width: 1024px)');
  var slot = null;
  function place() {
    var s = document.querySelector('.home-search'), b = document.getElementById('homeAdBanner');
    if (!s || !b) return;
    if (!slot) { slot = document.createElement('span'); slot.hidden = true; s.parentNode.insertBefore(slot, s); }
    // only move it in while the box is actually showing (Premium users have no box)
    var want = mq.matches && getComputedStyle(b).display !== 'none';
    if (want && s.parentNode !== b) {
      b.insertBefore(s, b.querySelector('.sub-btn') || b.querySelector('.ad-artists'));
      b.classList.add('has-search');
    } else if (!want && s.parentNode === b) {
      slot.parentNode.insertBefore(s, slot.nextSibling);
      b.classList.remove('has-search');
    }
  }
  var b0 = document.getElementById('homeAdBanner');
  if (b0) new MutationObserver(place).observe(b0, { attributes: true, attributeFilter: ['style', 'class'] });
  (mq.addEventListener ? mq.addEventListener('change', place) : mq.addListener(place));
  window.addEventListener('resize', place);
  place(); setTimeout(place, 1500); setTimeout(place, 5000);
})();

/* ── script #122 id=app-icon-picker-js ── */
(function(){
  var KEY='yaps_app_icon', COUNT=16;
  function pad(n){return (n<10?'0':'')+n}
  function ls(k,v){try{if(v===undefined)return localStorage.getItem(k);localStorage.setItem(k,v)}catch(e){return null}}
  function setLinks(n){
    var head=document.head;
    head.querySelectorAll('link[rel="icon"],link[rel="shortcut icon"],link[rel="apple-touch-icon"]').forEach(function(l){l.parentNode.removeChild(l)});
    function add(rel,size,href){var l=document.createElement('link');l.rel=rel;l.type='image/png';if(size)l.sizes=size;l.href=href;head.appendChild(l)}
    if(n===0){
      add('icon','32x32','icons/favicon-32.png?v=4');add('icon','192x192','icons/icon-192.png?v=4');add('icon','512x512','icons/icon-512.png?v=4');
      add('apple-touch-icon','180x180','icons/apple-touch-icon.png?v=4');
    } else {
      var b='icons/app-icon-'+pad(n)+'-';
      add('icon','96x96',b+'96.png');add('icon','192x192',b+'192.png');add('icon','512x512',b+'512.png');
      add('apple-touch-icon','180x180',b+'180.png');
    }
  }
  function setManifest(n){
    var l=document.querySelector('link[rel="manifest"]'); if(!l)return;
    var href=n===0?'manifest.json':'manifest-'+pad(n)+'.json';
    if(n===0){l.setAttribute('href',href);return}
    // only switch if that manifest file really exists on the site
    try{fetch(href,{method:'HEAD',cache:'no-cache'}).then(function(r){l.setAttribute('href',r.ok?href:'manifest.json')}).catch(function(){})}catch(e){}
  }
  function mark(n){
    var g=document.getElementById('appIconGrid'); if(!g)return;
    g.querySelectorAll('.app-icon-opt').forEach(function(b){
      var on=+b.dataset.n===n; b.classList.toggle('active',on); b.setAttribute('aria-checked',on?'true':'false');
    });
  }
  window.setAppIcon=function(n,opts){
    n=+n||0; opts=opts||{};
    ls(KEY,String(n)); setLinks(n); setManifest(n); mark(n);
    if(!opts.silent&&typeof showToast==='function')showToast('App icon updated');
  };
  function build(){
    var g=document.getElementById('appIconGrid'); if(!g||g.children.length)return;
    var html='<button type="button" class="app-icon-opt" data-n="0" role="radio" aria-label="Original icon" onclick="setAppIcon(0)"><img loading="lazy" alt="" src="icons/icon-192.png?v=4"><span class="aio-def">ORIGINAL</span></button>';
    for(var i=1;i<=COUNT;i++)html+='<button type="button" class="app-icon-opt" data-n="'+i+'" role="radio" aria-label="Icon '+i+'" onclick="setAppIcon('+i+')"><img loading="lazy" alt="" src="icons/app-icon-'+pad(i)+'-96.png"></button>';
    g.innerHTML=html;
    mark(+ls(KEY)||0);
  }
  build();
  var saved=+ls(KEY)||0;
  if(saved>0){setLinks(saved);setManifest(saved)}
})();

